insert into private.study_guides (guide, chunks, sha256) values ('study_guide_bua201', 45, '47bff2c0e69174b296df0c1b7254a89d8e72e588615a32899208402a389bdd27');
insert into private.study_guide_chunks (guide, ordinal, chunk) values ('study_guide_bua201', 1, $study_guide${"guide":"study_guide_bua201","code":"BUA201","courseId":"40000000-0000-4000-8000-000000000002","actor":"00000000-0000-4000-8000-000000000045","overview":{"itemId":"393817a6-f4f6-5563-9b22-4614aa481ad9","before":{"title":"Principles of Business Administration I","body":"Foundation course covering business functions, marketing fundamentals, organizational structure, management concepts, business environment analysis, and contemporary issues in Nigerian business administration.","topics":[{"chapter":"1-2","description":"Business Functions and Organizational Structure"},{"chapter":"3-4","description":"Marketing Fundamentals and Segmentation"},{"chapter":"5-6","description":"Management Concepts and Principles"},{"chapter":"7-8","description":"Business Environment and Strategy"},{"chapter":"9-10","description":"Contemporary Issues and Change Management in Nigeria"},{"chapter":"11-12","description":"Business Ownership, Ethics, and Corporate Governance"}],"examFocus":["Definition of business functions","Organizational structure types and benefits","Market segmentation strategies","Management theories and applications","PESTLE analysis and business environment","Contemporary challenges in Nigerian business","Business ownership types and liability","Corporate governance principles (NCCG 2018)","Leadership theories and styles","Theory explanations and definitions"],"keyTakeaways":[{"title":"The True Purpose of Business Goes Beyond Profit","description":"While classical thinkers like Adam Smith viewed businesses narrowly as profit-maximizing machines, the modern view sees businesses as social institutions responsible for value creation, employment generation, and wealth distribution for all stakeholders."},{"title":"Management is Universal and Interconnected","description":"Wherever there are people and goals, management is required. The four core functions—Planning, Organising, Leading, and Controlling—are deeply interrelated. You cannot control what you have not planned. Success is measured by Effectiveness (doing the right things) and Efficiency (using the least resources)."},{"title":"Constantly Scan the Dynamic Business Environment","description":"No business operates in a vacuum. Always apply the PESTLE framework (Political, Economic, Sociocultural, Technological, Legal, Environmental) to analyze forces shaping your industry and adapt to opportunities and threats."},{"title":"The Reality of the Nigerian Business Context","description":"As managers in Nigeria, you will face infrastructure deficits, economic volatility (inflation, FX constraints), and security threats. You must act as an \"Organizational Stabiliser\" and Change Agent while managing cultural rigidity, employee burnout, and the skills gap."},{"title":"Organizations are Open Systems Requiring Integration","description":"Systems Theory views businesses as open systems that receive inputs, transform them, and produce outputs. Cross-functional integration is critical—Marketing, Operations, HR, and Finance must work together, not in silos."},{"title":"Understand Business Ownership and Liability","description":"A Sole Proprietorship carries unlimited personal liability—your personal assets can be seized to pay business debts. Incorporating as a company (like a PLC) creates a separate legal entity and provides limited liability protection."},{"title":"Ethics, Governance, and Responsible Leadership","description":"Management is a recognized profession requiring adherence to ethical codes like NIM's. Uphold the NCCG 2018 principles: Responsibility, Accountability, Transparency, and Fairness. Strive to be a Transformational or Servant Leader who guides with honesty and empathy."}]},"after":{"title":"Principles of Business Administration I","body":"Foundation course covering business functions, marketing fundamentals, organizational structure, management concepts, business environment analysis, and contemporary issues in Nigerian business administration.","topics":[{"chapter":"1-2","description":"Business Functions and Organizational Structure"},{"chapter":"3-4","description":"Marketing Fundamentals and Segmentation"},{"chapter":"5-6","description":"Management Concepts and Principles"},{"chapter":"7-8","description":"Business Environment and Strategy"},{"chapter":"9-10","description":"Contemporary Issues and Change Management in Nigeria"},{"chapter":"11-12","description":"Business Ownership, Ethics, and Corporate Governance"}],"examFocus":["Definition of business functions","Organizational structure types and benefits","Market segmentation strategies","Management theories and applications","PESTLE analysis and business environment","Contemporary challenges in Nigerian business","Business ownership types and liability","Corporate governance principles (NCCG 2018)","Leadership theories and styles","Theory explanations and definitions"],"keyTakeaways":[{"title":"The True Purpose of Business Goes Beyond Profit","description":"While classical thinkers like Adam Smith viewed businesses narrowly as profit-maximizing machines, the modern view sees businesses as social institutions responsible for value creation, employment generation, and wealth distribution for all stakeholders."},{"title":"Management is Universal and Interconnected","description":"Wherever there are people and goals, management is required. The four core functions—Planning, Organising, Leading, and Controlling—are deeply interrelated. You cannot control what you have not planned. Success is measured by Effectiveness (doing the right things) and Efficiency (using the least resources)."},{"title":"Constantly Scan the Dynamic Business Environment","description":"No business operates in a vacuum. Always apply the PESTLE framework (Political, Economic, Sociocultural, Technological, Legal, Environmental) to analyze forces shaping your industry and adapt to opportunities and threats."},{"title":"The Reality of the Nigerian Business Context","description":"As managers in Nigeria, you wil$study_guide$);
insert into private.study_guide_chunks (guide, ordinal, chunk) values ('study_guide_bua201', 2, $study_guide$l face infrastructure deficits, economic volatility (inflation, FX constraints), and security threats. You must act as an \"Organizational Stabiliser\" and Change Agent while managing cultural rigidity, employee burnout, and the skills gap."},{"title":"Organizations are Open Systems Requiring Integration","description":"Systems Theory views businesses as open systems that receive inputs, transform them, and produce outputs. Cross-functional integration is critical—Marketing, Operations, HR, and Finance must work together, not in silos."},{"title":"Understand Business Ownership and Liability","description":"A Sole Proprietorship carries unlimited personal liability—your personal assets can be seized to pay business debts. Incorporating as a company (like a PLC) creates a separate legal entity and provides limited liability protection."},{"title":"Ethics, Governance, and Responsible Leadership","description":"Management is a recognized profession requiring adherence to ethical codes like NIM's. Uphold the NCCG 2018 principles: Responsibility, Accountability, Transparency, and Fairness. Strive to be a Transformational or Servant Leader who guides with honesty and empathy."}],"outcomes":["Define and explain the key operating elements and functions of business organisations.","Appraise the core management functions (planning, organising, leading and controlling) and show how they relate.","Apply foundational management knowledge to marketing, accounting, finance, human resources and operations.","Explain the impact of the internal and external environment on modern business, with particular reference to Nigeria.","Explain the forms of business ownership, their advantages, limitations and regulation.","Analyse the roles, skills and responsibilities of managers as change agents and leaders.","Evaluate corporate governance principles and ethical leadership practices.","Learn from the careers, leadership styles and decisions of successful Nigerian and global managers."],"assessment":["Expect a test and an examination, mostly objective questions, plus possible short quizzes during the semester.","Expect definitions, lists, theories and who proposed them, Nigerian examples and facts about the managers studied.","Every topic is examinable."]}},"retire":[{"itemId":"a3c225a1-6931-5e88-84e1-a975156eefa1","revision":1,"parentRevision":null},{"itemId":"1017807e-5367-5081-acc8-d03f7f92077c","revision":1,"parentRevision":null},{"itemId":"acb95982-cc2e-5ae2-b8a5-6722b603f4b6","revision":1,"parentRevision":null},{"itemId":"22b7bad2-2ca2-59e4-b251-cd5b19c185d6","revision":1,"parentRevision":null},{"itemId":"702df91d-6197-58dd-9ce5-b2ced61b6067","revision":1,"parentRevision":null},{"itemId":"633a4461-32b9-59e9-8771-46eeed5032bb","revision":1,"parentRevision":null},{"itemId":"dd57107d-3832-56f1-8147-b30167d9e1f5","revision":1,"parentRevision":null},{"itemId":"3a6db09b-456a-54cc-8627-e91bddb5ae8f","revision":1,"parentRevision":null},{"itemId":"dc6f3299-d2be-567a-b401-354e4f301b7c","revision":1,"parentRevision":null},{"itemId":"23db08e1-1221-5256-90b8-5596290affad","revision":1,"parentRevision":null}],"notes":[{"kind":"note","itemId":"250078f5-591a-55c7-b1c6-17d305159b34","sourceKey":"guide-topic:1","position":1,"payload":{"title":"Introduction to Business and Management","body":"What business is, its features, how it evolved and why it exists; stakeholders, sectors and the resources managers combine; what management is (efficiency, effectiveness, art and science); and the evolution of management thought from Taylor, Fayol and Weber through Mayo, Maslow, Herzberg and McGregor to quantitative, systems, contingency and modern approaches.","noteType":"guide_topic","number":1,"mustKnow":[{"text":"What business is, its features, how it evolved and why it exists; stakeholders, sectors and the resources managers combine; what management is (efficiency, effectiveness, art and science); and the evolution of management thought from Taylor, Fayol and Weber through Mayo, Maslow, Herzberg and McGregor to quantitative, systems, contingency and modern approaches."}],"lessons":[{"number":"1.1","title":"Meaning and nature of business","mustKnow":[{"type":"list","ordered":false,"items":[{"text":[{"text":"Business:","bold":true},{"text":" any organised activity that provides goods or services to customers on a regular basis with the aim of earning a profit. It is carried on under risk and uncertainty."}]},{"text":[{"text":"Profit:","bold":true},{"text":" the amount by which total revenue exceeds total expenses. Profit = Total revenue − Total expenses. If expenses are higher, the result is a "},{"text":"loss","bold":true},{"text":"."}]},{"text":[{"text":"Characteristics of business:","bold":true}]}]},{"type":"list","ordered":true,"start":1,"items":[{"text":[{"text":"Exchange (dealings) in goods or services for value."}]},{"text":[{"text":"Regularity of dealings (a one-off sale is not business)."}]},{"text":[{"text":"Profit motive."}]},{"text":[{"text":"Risk and uncertainty (profit is never guaranteed)."}]},{"text":[{"text":"Buyer and seller."}]},{"text":[{"text":"Satisfaction of human wants (creation of utility)."}]},{"text":[{"text":"An economic activity (not done for love, pleasure or as a gift)."}]}]},{"type":"list","ordered":false,"items":[{"text":[{"text":"Factors of production and their rewards:","bold":true}]}]},{"type":"table","header":[[{"text":"Factor"}],[{"text":"Reward"}]],"rows":[[[{"text":"Land (all natural resources)"}],[{"text":"Rent"}]],[[{"text":"Labour (human effort)"}],[{"text":"Wages (salaries)"}]],[[{"text":"Capital (man-made aids such as machines, buildings)"}],[{"text":"Interest"}]],[[{"text":"Entrepreneur (organiser and risk-bearer)"}],[{"text":"Profit"}]]]},{"type":"list","ordered":false,"items":[{"text":[{"text":"Profit is a "},{"text":"reward","bold":true},{"text":", not a factor of production."}]},{"text":[{"text":"Entrepreneur:","bold":true},{"text":" a person who brings together land, labour and capita$study_guide$);
insert into private.study_guide_chunks (guide, ordinal, chunk) values ('study_guide_bua201', 3, $study_guide$l to start a business and bears the risk of losing his money."}]},{"text":[{"text":"Evolution of business:","bold":true},{"text":" subsistence (producing only for your own use) → "},{"text":"barter","bold":true},{"text":" (goods for goods) → "},{"text":"money","bold":true},{"text":" → trade and commerce → "},{"text":"Industrial Revolution","bold":true},{"text":" (Britain, late 18th century) → the modern company."}]},{"text":[{"text":"Main problem of barter:","bold":true},{"text":" the need for a "},{"text":"double coincidence of wants","bold":true},{"text":" (you must find someone who has what you want and wants what you have). Money solved it."}]},{"text":[{"text":"Separation of ownership from control","bold":true},{"text":" came most directly from the "},{"text":"Industrial Revolution","bold":true},{"text":": factories needed huge capital, so many shareholders put in money (owners) while hired professional managers ran the firm (control)."}]}]}],"explainMore":[{"type":"list","ordered":false,"items":[{"text":[{"text":"A trader in Mile 12 Market who regularly buys rice in bulk and resells at a profit is in business. A mother cooking for her family, a birthday gift, or Aisha selling her own used laptop once for ₦150,000 are not; the laptop sale fails mainly on "},{"text":"regularity","bold":true},{"text":", even though it had a buyer, a seller, a money price and a gain."}]},{"text":[{"text":"Chidi uses his savings, rents a shop in Yaba, hires two bakers and buys ovens, knowing he could lose his money. He is acting as an "},{"text":"entrepreneur","bold":true},{"text":": he organises the other factors and bears the risk."}]},{"text":[{"text":"Worked example:","bold":true},{"text":" Chidi's bakery earns total revenue of ₦2,500,000 in a month and spends ₦1,900,000 on flour, wages, rent and diesel. Profit = ₦2,500,000 − ₦1,900,000 = "},{"text":"₦600,000","bold":true},{"text":". The ₦2,500,000 is revenue, not profit, and the savings he started with are capital, not profit."}]},{"text":[{"text":"Other barter problems: no common measure of value, goods cannot be divided easily, no store of value."}]},{"text":[{"text":"Traps: business does "},{"text":"not","bold":true},{"text":" guarantee profit; it covers "},{"text":"services","bold":true},{"text":" as well as goods."}]}]}]},{"number":"1.2","title":"Purpose of business, stakeholders and key operating elements","mustKnow":[{"type":"list","ordered":false,"items":[{"text":[{"text":"Purposes of business in society:","bold":true},{"text":" providing goods and services people need; creating jobs and incomes; paying taxes (government revenue); earning profit for owners; creating wealth and innovation; contributing to community development (social responsibility). Making the laws of a country is "},{"text":"not","bold":true},{"text":" a purpose of business; that is government's job."}]},{"text":[{"text":"Stakeholder:","bold":true},{"text":" any individual or group that can affect or is affected by the business's activities."}],"blocks":[{"type":"list","ordered":false,"items":[{"text":[{"text":"Internal:","bold":true},{"text":" employees, managers, owners."}]},{"text":[{"text":"External:","bold":true},{"text":" customers, suppliers, government (tax authority, regulators), creditors, host community."}]}]}]},{"text":[{"text":"Sectors of the economy:","bold":true}]}]},{"type":"table","header":[[{"text":"Sector"}],[{"text":"Activity"}],[{"text":"Examples"}]],"rows":[[[{"text":"Primary"}],[{"text":"Extracting natural resources"}],[{"text":"Farming (cocoa), mining (tin), fishing, forestry"}]],[[{"text":"Secondary"}],[{"text":"Turning raw materials into goods"}],[{"text":"Cement, textile, food factories; construction"}]],[[{"text":"Tertiary"}],[{"text":"Providing services"}],[{"text":"Banking, insurance, transport, retail"}]]]},{"type":"list","ordered":false,"items":[{"text":[{"text":"Commerce","bold":true},{"text":" = trade (buying and selling: home and foreign) + "},{"text":"aids to trade","bold":true},{"text":" (banking, insurance, transport, communication, warehousing, advertising)."}]},{"text":[{"text":"Non-profit organisation:","bold":true},{"text":" uses any surplus to pursue its mission instead of distributing it to owners. It still needs management and may employ paid staff."}]},{"text":[{"text":"Organisation:","bold":true},{"text":" a group of people working together in a structured way to achieve common goals (goals, people, structure)."}]},{"text":[{"text":"Four resources managers combine (key operating elements):","bold":true}]}]},{"type":"list","ordered":true,"start":1,"items":[{"text":[{"text":"Human:","bold":true},{"text":" managers and staff (e.g. the sales force)."}]},{"text":[{"text":"Financial:","bold":true},{"text":" money (e.g. a bank loan of ₦5,000,000)."}]},{"text":[{"text":"Physical:","bold":true},{"text":" buildings, machines, vehicles, raw materials (e.g. delivery vans)."}]},{"text":[{"text":"Information:","bold":true},{"text":" data managers use (e.g. market research on customer preferences)."}]}]}],"explainMore":[{"type":"list","ordered":false,"items":[{"text":[{"text":"A firm in Ogun State that turns limestone into bags of cement is in the "},{"text":"secondary","bold":true},{"text":" sector; the quarry stage alone is primary. A commercial bank is "},{"text":"tertiary","bold":true},{"text":"."}]},{"text":[{"text":"Customer satisfaction is a "},{"text":"goal","bold":true},{"text":", not a resource."}]},{"text":[{"text":"Every business also works through functional areas (production or operations, marketing, finance and accounting, human resources) inside an "},{"text":"environment","bold":true},{"text":" of customers, competitors, government and technology. Goals, people, structure, resources, technology and management are the operating elements that make it run."}]}]}]},{"number":"1.3","title":"What management is","mustKnow":[{"type":"list","ordered":false,"items":[{"text":[{"text":"Management","bold":true},{"text":" (Mary Parker Fo$study_guide$);
insert into private.study_guide_chunks (guide, ordinal, chunk) values ('study_guide_bua201', 4, $study_guide$llett): \"the art of getting things done through people.\""}]},{"text":[{"text":"Henri Fayol:","bold":true},{"text":" to manage is to forecast and plan, to organise, to command, to coordinate and to control."}]},{"text":[{"text":"Working definition:","bold":true},{"text":" the process of planning, organising, leading and controlling an organisation's human, financial, physical and information resources to achieve its goals efficiently and effectively."}]}]},{"type":"table","header":[[],[{"text":"Efficiency"}],[{"text":"Effectiveness"}]],"rows":[[[{"text":"Meaning"}],[{"text":"Using the fewest resources (time, money, labour) for a given output"}],[{"text":"Achieving the goals the organisation set"}]],[[{"text":"Phrase"}],[{"text":"Doing things right"}],[{"text":"Doing the right things"}]],[[{"text":"Concerned with"}],[{"text":"Means (inputs)"}],[{"text":"Ends (results)"}]]]},{"type":"list","ordered":false,"items":[{"text":[{"text":"Good management needs "},{"text":"both","bold":true},{"text":"."}]},{"text":[{"text":"Management is both an art and a science:","bold":true},{"text":" it rests on a body of organised principles (science), but applying them well requires personal skill, experience, creativity and judgement (art)."}]}]}],"explainMore":[{"type":"list","ordered":false,"items":[{"text":[{"text":"A Lagos factory makes plastic chairs at the lowest unit cost in its industry, but customers no longer want the design and most remain unsold: "},{"text":"efficient but not effective","bold":true},{"text":"."}]},{"text":[{"text":"Why not a \"pure\" science: management deals with people, so its principles do "},{"text":"not","bold":true},{"text":" give exactly the same result in every situation. Why not a \"pure\" art: it does have principles that can be taught, so it is not learnt only from experience."}]},{"text":[{"text":"A manager who relies on experience, creativity and judgement while applying management principles is practising management as "},{"text":"both","bold":true},{"text":" an art and a science."}]}]}]},{"number":"1.4","title":"The classical school","mustKnow":[{"type":"paragraph","text":[{"text":"The classical approach has "},{"text":"three","bold":true},{"text":" branches: "},{"text":"scientific management","bold":true},{"text":", "},{"text":"administrative management","bold":true},{"text":", "},{"text":"bureaucratic management","bold":true},{"text":". The human relations movement is "},{"text":"not","bold":true},{"text":" classical."}]},{"type":"paragraph","text":[{"text":"Scientific management: Frederick W. Taylor","bold":true},{"text":" (father of scientific management; "},{"text":"The Principles of Scientific Management","italic":true},{"text":", 1911). Main focus: raise "},{"text":"worker efficiency","bold":true},{"text":" through systematic study of tasks and methods."}]},{"type":"list","ordered":true,"start":1,"items":[{"text":[{"text":"Develop a science for each part of a job (replace rule of thumb)."}]},{"text":[{"text":"Scientifically select, train and develop workers."}]},{"text":[{"text":"Cooperate with workers so work follows the scientific method."}]},{"text":[{"text":"Divide work and responsibility between management and workers."}]}]},{"type":"list","ordered":false,"items":[{"text":[{"text":"Time and motion study:","bold":true},{"text":" find the "},{"text":"one best way","bold":true},{"text":" of doing a job and set a standard time for it."}]},{"text":[{"text":"Differential piece-rate:","bold":true},{"text":" a worker who produces "},{"text":"more","bold":true},{"text":" than the standard is paid a "},{"text":"higher rate per unit","bold":true},{"text":"; below standard, a lower rate."}]},{"text":[{"text":"Frank and Lillian Gilbreth:","bold":true},{"text":" motion study (bricklaying; "},{"text":"therbligs","bold":true},{"text":" = basic hand motions)."}]},{"text":[{"text":"Henry Gantt:","bold":true},{"text":" the "},{"text":"Gantt chart","bold":true},{"text":", a bar chart showing planned and actual progress of tasks against time."}]}]},{"type":"paragraph","text":[{"text":"Administrative management: Henri Fayol","bold":true},{"text":" (French industrialist; father of modern management theory). "},{"text":"5 elements (functions):","bold":true},{"text":" planning, organising, commanding, coordinating, controlling. "},{"text":"Staffing is not one of Fayol's five.","bold":true}]},{"type":"paragraph","text":[{"text":"Fayol's 14 principles:","bold":true}]},{"type":"list","ordered":true,"start":1,"items":[{"text":[{"text":"Division of work:","bold":true},{"text":" specialisation."}]},{"text":[{"text":"Authority and responsibility:","bold":true},{"text":" right to give orders, matched by responsibility."}]},{"text":[{"text":"Discipline:","bold":true},{"text":" obedience and respect for agreements."}]},{"text":[{"text":"Unity of command:","bold":true},{"text":" each employee receives orders from "},{"text":"only one superior","bold":true},{"text":"."}]},{"text":[{"text":"Unity of direction:","bold":true},{"text":" "},{"text":"one head and one plan","bold":true},{"text":" for a group of activities with the same objective."}]},{"text":[{"text":"Subordination of individual interest to the general interest.","bold":true}]},{"text":[{"text":"Remuneration:","bold":true},{"text":" fair pay."}]},{"text":[{"text":"Centralisation:","bold":true},{"text":" degree to which authority is concentrated at the top."}]},{"text":[{"text":"Scalar chain:","bold":true},{"text":" the unbroken line of authority from highest to lowest rank, through which communication passes."}]},{"text":[{"text":"Order:","bold":true},{"text":" \"a place for everything and everything in its place\", for people and things."}]},{"text":[{"text":"Equity:","bold":true},{"text":" kindness and justice."}]},{"text":[{"text":"Stability of tenure of personnel.","bold":true}]},{"text":[{"text":"Initiative:","bold":true},{"text":" allowing staff to think up and carry out plans."}]},{"text":[{"text":"Esprit de corps:","bol$study_guide$);
insert into private.study_guide_chunks (guide, ordinal, chunk) values ('study_guide_bua201', 5, $study_guide$d":true},{"text":" harmony and team spirit."}]}]},{"type":"paragraph","text":[{"text":"Bureaucratic management: Max Weber","bold":true},{"text":" (German sociologist). Ideal bureaucracy features: division of labour; clear "},{"text":"hierarchy","bold":true},{"text":" of authority; formal written "},{"text":"rules","bold":true},{"text":" and procedures; "},{"text":"impersonality","bold":true},{"text":"; selection and promotion on "},{"text":"technical qualification","bold":true},{"text":"; career orientation. Authority is "},{"text":"rational-legal","bold":true},{"text":" (based on rules and the position held), not traditional (custom) or charismatic (personal appeal)."}]}],"explainMore":[{"type":"list","ordered":false,"items":[{"text":[{"text":"Taylor worked at Midvale and Bethlehem Steel. In the pig-iron study, a loader's output rose from 12.5 to 47.5 tons a day: increase = (47.5 − 12.5) ÷ 12.5 × 100 = "},{"text":"280%","bold":true},{"text":"."}]},{"text":[{"text":"Criticism of Taylor:","bold":true},{"text":" treated workers like "},{"text":"economic machines","bold":true},{"text":" (paid only for output), ignored social needs, made work monotonous."}]},{"text":[{"text":"Applying Fayol: Bola gets orders from both the sales and finance managers = breach of "},{"text":"unity of command","bold":true},{"text":". A Kano mill splitting spinning, weaving and dyeing = "},{"text":"division of work","bold":true},{"text":". A manager refusing to lend company vans for a private event = "},{"text":"subordination of individual interest","bold":true},{"text":". A Lagos supermarket letting cashiers test new queue ideas = "},{"text":"initiative","bold":true},{"text":"."}]},{"text":[{"text":"Unity of command is about "},{"text":"one boss per person","bold":true},{"text":"; unity of direction is about "},{"text":"one plan per objective","bold":true},{"text":". Exams swap them."}]},{"text":[{"text":"Promotion based on personal loyalty to the boss is the "},{"text":"opposite","bold":true},{"text":" of Weber's bureaucracy."}]}]}]},{"number":"1.5","title":"Behavioural (human relations) and quantitative schools","mustKnow":[{"type":"list","ordered":false,"items":[{"text":[{"text":"Behavioural school","bold":true},{"text":" emerged to address the "},{"text":"human and social side of work","bold":true},{"text":" (informal groups, worker attitudes) that classical theory largely ignored."}]},{"text":[{"text":"Hawthorne studies","bold":true},{"text":" (Western Electric, near Chicago, 1924 to 1932; "},{"text":"Elton Mayo","bold":true},{"text":"): the Human Relations School grew mainly out of them. Key finding that challenged classical theory: "},{"text":"informal groups influence productivity","bold":true},{"text":"; social needs and attention matter, not just wages."}]},{"text":[{"text":"Hawthorne effect:","bold":true},{"text":" workers change their behaviour or productivity because they know they are being "},{"text":"observed and given attention","bold":true},{"text":"."}]},{"text":[{"text":"Human relations approach:","bold":true},{"text":" emphasis on social needs of workers and informal groups."}]},{"text":[{"text":"Chester Barnard:","bold":true},{"text":" "},{"text":"acceptance theory of authority","bold":true},{"text":" (authority depends on whether subordinates "},{"text":"accept","bold":true},{"text":" orders)."}]},{"text":[{"text":"Abraham Maslow's hierarchy (bottom to top):","bold":true},{"text":" physiological, safety, social (belonging), esteem, "},{"text":"self-actualisation","bold":true},{"text":" (top)."}]},{"text":[{"text":"Frederick Herzberg's two-factor theory:","bold":true}],"blocks":[{"type":"list","ordered":false,"items":[{"text":[{"text":"Hygiene factors","bold":true},{"text":" (prevent dissatisfaction): "},{"text":"salary","bold":true},{"text":", working conditions, company policy, supervision, job security."}]},{"text":[{"text":"Motivators","bold":true},{"text":" (create satisfaction): achievement, recognition, the work itself, responsibility, advancement."}]}]}]},{"text":[{"text":"Douglas McGregor:","bold":true}]}]},{"type":"table","header":[[{"text":"Theory X"}],[{"text":"Theory Y"}]],"rows":[[[{"text":"Workers dislike work, avoid responsibility"}],[{"text":"Work is natural; people seek responsibility"}]],[[{"text":"Must be closely supervised, controlled, threatened"}],[{"text":"Exercise self-direction and self-control when committed to objectives"}]],[[{"text":"Tight supervision, centralisation, punishment"}],[{"text":"Job enrichment, empowerment, participation"}]]]},{"type":"list","ordered":false,"items":[{"text":[{"text":"Quantitative (management science) approach:","bold":true},{"text":" mathematical and statistical tools such as "},{"text":"linear programming","bold":true},{"text":" and "},{"text":"operations research","bold":true},{"text":" to improve decisions (from World War II)."}]}]}],"explainMore":[{"type":"list","ordered":false,"items":[{"text":[{"text":"Hawthorne began as "},{"text":"lighting","bold":true},{"text":" tests: output rose in both test and control groups, even when light was dimmed, so lighting was not the cause."}]},{"text":[{"text":"A firm applying Theory Y involves employees in setting their own goals and gives them responsibility for results. Clock-in checks and penalties are Theory X."}]},{"text":[{"text":"A manager who uses strict controls in a crisis but participative methods in stable periods is applying "},{"text":"Theory X and Theory Y situationally","bold":true},{"text":". McGregor himself favoured Theory Y."}]},{"text":[{"text":"Herzberg trap: salary does not motivate on its own; it is hygiene."}]}]}]},{"number":"1.6","title":"Systems, contingency and modern approaches","mustKnow":[{"type":"list","ordered":false,"items":[{"text":[{"text":"Systems approach:","bold":true},{"text":" the organisation is a set of interrelated parts (subsystems) that takes "},{"text":"inputs","bold":true},{"text":", "},{"text":"transforms","bold":true},{"text":" them and retu$study_guide$);
insert into private.study_guide_chunks (guide, ordinal, chunk) values ('study_guide_bua201', 6, $study_guide$rns "},{"text":"outputs","bold":true},{"text":", with "},{"text":"feedback","bold":true},{"text":"."}],"blocks":[{"type":"list","ordered":false,"items":[{"text":[{"text":"Open system:","bold":true},{"text":" interacts with its environment. "},{"text":"Closed system:","bold":true},{"text":" does not."}]},{"text":[{"text":"Synergy:","bold":true},{"text":" parts working together achieve more than they would separately."}]},{"text":[{"text":"Entropy:","bold":true},{"text":" a system runs down without new inputs."}]}]}]},{"text":[{"text":"Contingency (situational) approach:","bold":true},{"text":" the best management practice "},{"text":"depends on the situation","bold":true},{"text":"; there is no one best way."}]},{"text":[{"text":"Management by objectives (MBO), Peter Drucker:","bold":true},{"text":" managers and subordinates "},{"text":"jointly","bold":true},{"text":" set specific goals and later review performance against them."}]},{"text":[{"text":"Modern thinking","bold":true},{"text":" stresses flexibility because organisations operate in "},{"text":"dynamic and complex environments","bold":true},{"text":": total quality management (Deming, Juran), learning organisations, digitisation, globalisation."}]}]},{"type":"paragraph","text":[{"text":"Historical order:","bold":true}]},{"type":"list","ordered":true,"start":1,"items":[{"text":[{"text":"Scientific management (about 1880s to 1910s)"}]},{"text":[{"text":"Human relations (1920s to 1930s)"}]},{"text":[{"text":"Quantitative (1940s)"}]},{"text":[{"text":"Systems (1950s to 1960s)"}]},{"text":[{"text":"Contingency (1960s to 1970s)"}]},{"text":[{"text":"Modern approaches"}]}]}],"explainMore":[{"type":"list","ordered":false,"items":[{"text":[{"text":"Systems view of a bakery: inputs = flour, sugar, bakers' labour; transformation = mixing and baking; outputs = bread; feedback = customer complaints."}]},{"text":[{"text":"Contingency contradicts Taylor's \"one best way\"."}]},{"text":[{"text":"Under MBO, targets are not imposed from the top; that is its whole point."}]}]}]}],"recap":[{"type":"list","ordered":false,"items":[{"text":[{"text":"Business = regular, organised provision of goods or services for profit, under risk."}]},{"text":[{"text":"Profit = total revenue − total expenses; profit is the entrepreneur's reward, not a factor."}]},{"text":[{"text":"Barter needed a double coincidence of wants; the Industrial Revolution separated ownership from control."}]},{"text":[{"text":"Sectors: primary (extract), secondary (make), tertiary (serve). Insurance is an aid to trade."}]},{"text":[{"text":"Four resources: human, financial, physical, information."}]},{"text":[{"text":"Efficiency = doing things right; effectiveness = doing the right things. Management is both art and science."}]},{"text":[{"text":"Classical: Taylor (scientific), Fayol (5 elements, 14 principles), Weber (bureaucracy, rational-legal)."}]},{"text":[{"text":"Behavioural: Hawthorne and Mayo, Barnard, Maslow, Herzberg (salary = hygiene), McGregor X and Y."}]},{"text":[{"text":"Then quantitative, systems (synergy, open system), contingency (\"it depends\"), modern (MBO, Drucker)."}]}]}],"theory":{"itemId":"9e27de07-deff-553b-8100-c1b8ba78e7e2","question":[{"type":"paragraph","text":[{"text":"A Surulere bakery aims to sell 2,000 loaves a week at ₦700 each. In Week 1 it bakes 2,000 loaves at a total cost of ₦1,000,000 and sells all of them. In Week 2 it cuts total cost to ₦800,000 for 2,000 loaves but sells only 1,200. Find the cost per loaf and profit each week, and say which week was more efficient and which more effective."}]}]},"practice":[{"topic":"Introduction to Business and Management","named":false}]}},{"kind":"note","itemId":"42559aef-faff-55a6-acb7-4cca1d55d18a","sourceKey":"guide-topic:2","position":2,"payload":{"title":"Universality of Management and Managerial Roles","body":"The four management functions (POLC) and how they link; the process and systems views; universality and management across functional areas; top, middle and first-line managers; Mintzberg's ten roles in three groups; Katz's three skills and how they change by level; managers as organisational stabilisers.","noteType":"guide_topic","number":2,"mustKnow":[{"text":"The four management functions (POLC) and how they link; the process and systems views; universality and management across functional areas; top, middle and first-line managers; Mintzberg's ten roles in three groups; Katz's three skills and how they change by level; managers as organisational stabilisers."}],"lessons":[{"number":"2.1","title":"The four management functions and how they link","mustKnow":[{"type":"list","ordered":false,"items":[{"text":[{"text":"Manager:","bold":true},{"text":" a person who plans, organises, leads and controls the work of others so that organisational goals are achieved."}]},{"text":[{"text":"The four functions (POLC):","bold":true}]}]},{"type":"list","ordered":true,"start":1,"items":[{"text":[{"text":"Planning:","bold":true},{"text":" setting goals and deciding in advance what to do, how and when to do it. It comes "},{"text":"first","bold":true},{"text":" and is the "},{"text":"foundation","bold":true},{"text":" of the other functions because it gives them direction."}]},{"text":[{"text":"Organising:","bold":true},{"text":" allocating tasks, resources and authority: creating departments, assigning jobs, setting reporting lines. Its result is the "},{"text":"organisation structure","bold":true},{"text":" (the formal framework of jobs, departments, reporting relationships and lines of authority)."}]},{"text":[{"text":"Leading (directing):","bold":true},{"text":" motivating, communicating with and influencing employees to work towards goals."}]},{"text":[{"text":"Controlling:","bold":true},{"text":" monitoring performance and ensuring that "},{"text":"deviations from plans are corrected","bold":true},{"text":"."}]}]},{"type":"list","ordered":false,"items":[{"text":[{"text":"\"Bargaining\" is "},{"text":"not","$study_guide$);
insert into private.study_guide_chunks (guide, ordinal, chunk) values ('study_guide_bua201', 7, $study_guide$bold":true},{"text":" one of the POLC functions."}]},{"text":[{"text":"Control process (4 steps in order):","bold":true}]}]},{"type":"list","ordered":true,"start":1,"items":[{"text":[{"text":"Set standards."}]},{"text":[{"text":"Measure actual performance."}]},{"text":[{"text":"Compare performance with standards."}]},{"text":[{"text":"Take corrective action."}]}]},{"type":"list","ordered":false,"items":[{"text":[{"text":"Interrelationship:","bold":true},{"text":" the functions are "},{"text":"interrelated and continuous","bold":true},{"text":", not separate one-off steps. "},{"text":"Control provides feedback for future plans","bold":true},{"text":": deviations found during controlling lead managers to revise their plans."}]}]},{"type":"table","header":[[{"text":"Function"}],[{"text":"Example activity"}]],"rows":[[[{"text":"Planning"}],[{"text":"Writing a five-year strategy; setting a target of three new depots"}]],[[{"text":"Organising"}],[{"text":"Creating units, assigning tasks, allocating equipment"}]],[[{"text":"Leading"}],[{"text":"Praising a worker; settling a quarrel; morning pep talk"}]],[[{"text":"Controlling"}],[{"text":"Checking whether production costs are within budget"}]]]}],"explainMore":[{"type":"list","ordered":false,"items":[{"text":[{"text":"Mission statement:","bold":true},{"text":" an organisation's fundamental, long-term purpose (why it exists). A "},{"text":"vision","bold":true},{"text":" states what it wants to become. Goals and budgets are narrower."}]},{"text":[{"text":"Levels of strategy:","bold":true}],"blocks":[{"type":"list","ordered":false,"items":[{"text":[{"text":"Corporate-level:","bold":true},{"text":" portfolio decisions about "},{"text":"which businesses or industries","bold":true},{"text":" the firm should be in."}]},{"text":[{"text":"Business-level:","bold":true},{"text":" how to compete in one business."}]},{"text":[{"text":"Functional-level:","bold":true},{"text":" how each department (marketing, production) supports the business strategy."}]}]}]},{"text":[{"text":"Levels of control:","bold":true},{"text":" "},{"text":"strategic control","bold":true},{"text":" focuses on the organisation's "},{"text":"long-term direction","bold":true},{"text":"; "},{"text":"operational control","bold":true},{"text":" focuses on daily tasks and routine supervision."}]},{"text":[{"text":"Centralisation:","bold":true},{"text":" authority concentrated at the top; it "},{"text":"limits employee empowerment","bold":true},{"text":". "},{"text":"Decentralisation:","bold":true},{"text":" authority pushed down; it promotes "},{"text":"faster decision-making at lower levels","bold":true},{"text":"."}]},{"text":[{"text":"Fayol listed five functions (planning, organising, commanding, coordinating, controlling); modern texts merge them into four, with leading replacing commanding."}]},{"text":[{"text":"Worked example (controlling):","bold":true},{"text":" an Ibadan distributor budgets sales of ₦10,000,000 for the month; actual sales are ₦8,200,000."}],"blocks":[{"type":"list","ordered":false,"items":[{"text":[{"text":"Shortfall = ₦10,000,000 − ₦8,200,000 = ₦1,800,000."}]},{"text":[{"text":"Shortfall as % of budget = ₦1,800,000 ÷ ₦10,000,000 × 100 = "},{"text":"18%","bold":true},{"text":" (so 82% of target was achieved)."}]},{"text":[{"text":"Comparing and investigating this is "},{"text":"controlling","bold":true},{"text":"; the findings feed into next month's "},{"text":"plan","bold":true},{"text":"."}]}]}]},{"text":[{"text":"A bottling-plant manager who sees bottles leaving the line under-filled and adjusts the filling machine is at step 4, "},{"text":"taking corrective action","bold":true},{"text":"."}]}]}]},{"number":"2.2","title":"Process and systems perspectives; universality","mustKnow":[{"type":"list","ordered":false,"items":[{"text":[{"text":"Process perspective:","bold":true},{"text":" management is a "},{"text":"continuous series of interrelated functions","bold":true},{"text":" (planning, organising, leading, controlling)."}]},{"text":[{"text":"Systems perspective:","bold":true},{"text":" an organisation is a "},{"text":"set of interrelated parts","bold":true},{"text":" that takes "},{"text":"inputs","bold":true},{"text":" from the environment, "},{"text":"transforms","bold":true},{"text":" them and returns "},{"text":"outputs","bold":true},{"text":", with "},{"text":"feedback","bold":true},{"text":"."}]}]},{"type":"table","header":[[{"text":"Element"}],[{"text":"Meaning"}],[{"text":"Bakery"}],[{"text":"Commercial bank"}]],"rows":[[[{"text":"Inputs"}],[{"text":"Resources taken in"}],[{"text":"Flour, sugar, bakers' labour"}],[{"text":"Deposits, staff skills"}]],[[{"text":"Transformation"}],[{"text":"Processing"}],[{"text":"Mixing and baking"}],[{"text":"Assessing loans, processing transactions"}]],[[{"text":"Outputs"}],[{"text":"What goes out"}],[{"text":"Loaves sold"}],[{"text":"Satisfied customers, profit"}]],[[{"text":"Feedback"}],[{"text":"Information about outputs used to adjust inputs or the process"}],[{"text":"Complaints about stale bread"}],[{"text":"Complaints to the call centre"}]]]},{"type":"list","ordered":false,"items":[{"text":[{"text":"Open system:","bold":true},{"text":" constantly interacts with and depends on its environment for resources and customers. A "},{"text":"closed system","bold":true},{"text":" does not. "},{"text":"Subsystems","bold":true},{"text":" (departments) are "},{"text":"interdependent","bold":true},{"text":"."}]},{"text":[{"text":"A manager using systems theory "},{"text":"emphasises the interdependence of subsystems","bold":true},{"text":" and does not ignore the environment."}]},{"text":[{"text":"Universality of management:","bold":true},{"text":" management principles and functions apply to "},{"text":"all kinds of organisations","bold":true},{"text":" (business, government, church, club, school) and at "},{"text":"all levels","bold":true},{"text":"."}]}]}],"explainMore":[{"type":"list","ordered":false,"items":[{"text":[{"te$study_guide$);
insert into private.study_guide_chunks (guide, ordinal, chunk) values ('study_guide_bua201', 8, $study_guide$xt":"When production breaks down at a Lagos beverage company and marketing misses delivery promises, that shows "},{"text":"interdependent subsystems","bold":true},{"text":"."}]},{"text":[{"text":"A church youth fellowship leader in Surulere sets goals, forms committees, motivates members and reviews each event: POLC outside business, so "},{"text":"universality","bold":true},{"text":"."}]},{"text":[{"text":"Universality does not mean principles are fixed laws or that every manager uses the same style; how they are applied varies with level, size, culture and country."}]},{"text":[{"text":"Management across functional areas:","bold":true},{"text":" production, marketing, finance, HR and operations managers each "},{"text":"plan, organise, lead and control","bold":true},{"text":" within their own areas. Marketing needs control systems too; planning is not only the finance manager's job."}]}]}]},{"number":"2.3","title":"Types and levels of managers","mustKnow":[{"type":"table","header":[[{"text":"Level"}],[{"text":"Main job"}],[{"text":"Typical titles"}]],"rows":[[[{"text":"Top","bold":true}],[{"text":"Organisation-wide decisions, long-term strategy and policies"}],[{"text":"Managing director, CEO, chairman, executive director"}]],[[{"text":"Middle","bold":true}],[{"text":"Translate top management's goals into specific plans for their units; coordinate first-line managers"}],[{"text":"Regional sales manager, plant manager, head of department, branch manager"}]],[[{"text":"First-line","bold":true},{"text":" (supervisory)"}],[{"text":"Direct day-to-day work of operatives"}],[{"text":"Foreman, shift supervisor, team leader"}]]]},{"type":"list","ordered":false,"items":[{"text":[{"text":"Operative (non-managerial) employees do the work themselves and manage no one."}]},{"text":[{"text":"Functional manager:","bold":true},{"text":" responsible for a "},{"text":"single specialised area","bold":true},{"text":" (finance, marketing, HR)."}]},{"text":[{"text":"General manager:","bold":true},{"text":" responsible for "},{"text":"several areas","bold":true},{"text":" (production, marketing, finance, personnel) of a whole unit or division."}]},{"text":[{"text":"Top managers make decisions with a "},{"text":"longer time horizon that affect the whole organisation","bold":true},{"text":"."}]},{"text":[{"text":"All levels perform all four functions, but "},{"text":"top managers spend relatively more time planning","bold":true},{"text":"; "},{"text":"first-line managers spend relatively more time leading and directing","bold":true},{"text":" day-to-day work."}]}]}],"explainMore":[{"type":"list","ordered":false,"items":[{"text":[{"text":"A foreman in a Kaduna factory who assigns daily tasks to machine operators, checks their work and reports to the production manager is a "},{"text":"first-line","bold":true},{"text":" manager."}]},{"text":[{"text":"The head of a regional division of a food company running production, marketing, finance and personnel is a "},{"text":"general","bold":true},{"text":" manager (middle level in a large group)."}]},{"text":[{"text":"A "},{"text":"project manager","bold":true},{"text":" coordinates people from different departments for a temporary project."}]},{"text":[{"text":"Traps: representing shareholders at the AGM is the board's role; personally doing routine production is operative work."}]}]}]},{"number":"2.4","title":"Mintzberg's ten managerial roles","mustKnow":[{"type":"paragraph","text":[{"text":"Henry Mintzberg","bold":true},{"text":" studied five chief executives at work and identified "},{"text":"10 roles","bold":true},{"text":" in "},{"text":"3 groups","bold":true},{"text":":"}]},{"type":"table","header":[[{"text":"Group"}],[{"text":"Role"}],[{"text":"What the manager does"}]],"rows":[[[{"text":"Interpersonal (3)","bold":true}],[{"text":"Figurehead"}],[{"text":"Ceremonial and symbolic duties: cutting ribbons, signing certificates"}]],[[],[{"text":"Leader"}],[{"text":"Hiring, training, motivating and praising staff"}]],[[],[{"text":"Liaison"}],[{"text":"Building a network of contacts "},{"text":"outside","bold":true},{"text":" the unit (regulators, other firms) for information and favours"}]],[[{"text":"Informational (3)","bold":true}],[{"text":"Monitor"}],[{"text":"Seeking and receiving information: reading trade journals and reports"}]],[[],[{"text":"Disseminator"}],[{"text":"Passing information "},{"text":"inside","bold":true},{"text":" the unit to subordinates"}]],[[],[{"text":"Spokesperson"}],[{"text":"Passing information "},{"text":"outside","bold":true},{"text":" to the public, media, regulators"}]],[[{"text":"Decisional (4)","bold":true}],[{"text":"Entrepreneur"}],[{"text":"Starting new projects and improvements"}]],[[],[{"text":"Disturbance handler"}],[{"text":"Taking charge in crises (fire, strikes)"}]],[[],[{"text":"Resource allocator"}],[{"text":"Deciding who gets what (budget, people, time)"}]],[[],[{"text":"Negotiator"}],[{"text":"Bargaining with unions, suppliers, partners"}]]]},{"type":"paragraph","text":[{"text":"Memory aid: "},{"text":"3 + 3 + 4 = 10","bold":true},{"text":"."}]}],"explainMore":[{"type":"list","ordered":false,"items":[{"text":[{"text":"MD of a Nigerian bank opens a branch and signs long-service certificates = "},{"text":"figurehead","bold":true},{"text":"."}]},{"text":[{"text":"Plant manager reads trade journals and daily reports = "},{"text":"monitor","bold":true},{"text":"."}]},{"text":[{"text":"Branch manager passes a new customer-service policy to staff = "},{"text":"disseminator","bold":true},{"text":"."}]},{"text":[{"text":"Head of corporate affairs of a telecom company explains a six-hour network outage on television = "},{"text":"spokesperson","bold":true},{"text":"."}]},{"text":[{"text":"Lagos fintech manager launches USSD account opening = "},{"text":"entrepreneur","bold":true},{"text":"."}]},{"text":[{"text":"Warehouse fire and threatened walk-off = "},{"text":"disturbance handler","bold":true},{"text":"."}]},{"text":[{"text$study_guide$);
insert into private.study_guide_chunks (guide, ordinal, chunk) values ('study_guide_bua201', 9, $study_guide$":"Divisional head shares a ₦50,000,000 budget among sales, production and training = "},{"text":"resource allocator","bold":true},{"text":". For example 40%, 35% and 25% give ₦20,000,000, ₦17,500,000 and ₦12,500,000."}]},{"text":[{"text":"HR director agrees wages with union officials = "},{"text":"negotiator","bold":true},{"text":"."}]},{"text":[{"text":"Common traps: "},{"text":"spokesperson","bold":true},{"text":" is informational (not interpersonal or decisional); "},{"text":"liaison","bold":true},{"text":" is interpersonal (not informational); "},{"text":"monitor","bold":true},{"text":" is informational (not decisional); "},{"text":"negotiator","bold":true},{"text":" is decisional. Strategic/tactical/operational are levels, not Mintzberg groups; technical/human/conceptual are Katz's skills."}]}]}]},{"number":"2.5","title":"Management skills","mustKnow":[{"type":"paragraph","text":[{"text":"Robert Katz","bold":true},{"text":" identified "},{"text":"three","bold":true},{"text":" basic skills:"}]},{"type":"list","ordered":true,"start":1,"items":[{"text":[{"text":"Technical skill:","bold":true},{"text":" using the tools, techniques and specialised knowledge of a field (accounting, engineering). "},{"text":"Most important for first-line managers.","bold":true}]},{"text":[{"text":"Human (interpersonal) skill:","bold":true},{"text":" working well with others, communicating, motivating, building cooperation. "},{"text":"Roughly equally important at all levels.","bold":true}]},{"text":[{"text":"Conceptual skill:","bold":true},{"text":" seeing the organisation as a whole, how its parts relate to each other and the environment; abstract thinking. "},{"text":"Most critical at the top","bold":true},{"text":", e.g. when formulating corporate strategy."}]}]},{"type":"list","ordered":false,"items":[{"text":[{"text":"Moving from first-line to top: "},{"text":"technical skill becomes less important, conceptual skill becomes more important","bold":true},{"text":"; human skill stays important throughout."}]}]},{"type":"table","header":[[{"text":"Level"}],[{"text":"Technical"}],[{"text":"Human"}],[{"text":"Conceptual"}]],"rows":[[[{"text":"Top"}],[{"text":"Low"}],[{"text":"High"}],[{"text":"Highest"}]],[[{"text":"Middle"}],[{"text":"Medium"}],[{"text":"High"}],[{"text":"Medium"}]],[[{"text":"First-line"}],[{"text":"Highest"}],[{"text":"High"}],[{"text":"Low"}]]]},{"type":"list","ordered":false,"items":[{"text":[{"text":"Other skills","bold":true},{"text":" often added: political (building a power base and networks), diagnostic and analytical, decision-making, communication, time management, design (solving problems in ways that benefit the organisation)."}]}]}],"explainMore":[{"type":"list","ordered":false,"items":[{"text":[{"text":"A conglomerate CEO studying how an import ban, rising interest rates and a rival's expansion will together affect each business is using "},{"text":"conceptual","bold":true},{"text":" skill."}]},{"text":[{"text":"A new supervisor calmly settling a quarrel between two operators uses "},{"text":"human","bold":true},{"text":" skill."}]},{"text":[{"text":"Do not mix Katz's skills with Mintzberg's role groups (interpersonal, informational, decisional)."}]}]}]},{"number":"2.6","title":"Managers as organisational stabilisers","mustKnow":[{"type":"list","ordered":false,"items":[{"text":[{"text":"Organisational stabilisers:","bold":true},{"text":" managers maintain "},{"text":"order, continuity and predictable operations","bold":true},{"text":" so the organisation keeps running smoothly, especially when disruptions hit."}]},{"text":[{"text":"They do this through plans, policies, procedures, coordination, control and quick problem-solving."}]}]}],"explainMore":[{"type":"list","ordered":false,"items":[{"text":[{"text":"During fuel scarcity, a transport company's operations manager reorganises schedules, secures alternative suppliers and keeps buses running. That is the manager as "},{"text":"stabiliser","bold":true},{"text":"."}]},{"text":[{"text":"Stabilising is "},{"text":"not","bold":true},{"text":" resisting every change or avoiding decisions. Managers balance stability with change: they keep today's operations steady while leading the changes the organisation needs (managers as change agents)."}]}]}]}],"recap":[{"type":"list","ordered":false,"items":[{"text":[{"text":"Manager = plans, organises, leads and controls others' work towards goals."}]},{"text":[{"text":"POLC: planning first (foundation); organising gives the structure; leading motivates; controlling corrects deviations."}]},{"text":[{"text":"Control steps: set standards, measure, compare, correct. Control feeds back into planning."}]},{"text":[{"text":"Process view = continuous interrelated functions; systems view = inputs, transformation, outputs, feedback; open system; interdependent subsystems."}]},{"text":[{"text":"Universality: management applies to all organisations and levels."}]},{"text":[{"text":"Levels: top (strategy, more planning), middle (translate and coordinate), first-line (daily supervision, more leading)."}]},{"text":[{"text":"Mintzberg: 10 roles; interpersonal 3, informational 3, decisional 4."}]},{"text":[{"text":"Katz: technical (first-line), human (all levels), conceptual (top)."}]},{"text":[{"text":"Managers stabilise: order, continuity, predictability."}]}]}],"theory":{"itemId":"3d0d15a4-f7ee-5b61-8879-55372b237866","question":[{"type":"paragraph","text":[{"text":"An Abuja water factory sets a standard of 5,000 cartons a week. Actual output this week is 4,600 cartons. Find the shortfall and the percentage of the standard achieved, and name the control step at which each piece of work happens."}]}]},"practice":[{"topic":"Universality of Management and Managerial Roles","named":false}]}},{"kind":"note","itemId":"be650482-400d-5653-81b3-99b5dc4d80b1","sourceKey":"guide-topic:3","position":3,"payload":{"title":"Managers as Change Agents","body":"What a change agent is and does; internal vs external ch$study_guide$);
insert into private.study_guide_chunks (guide, ordinal, chunk) values ('study_guide_bua201', 10, $study_guide$ange agents; types and drivers of change; change leadership vs change management; Lewin's three steps and force field analysis; Kotter's eight steps; causes of resistance and the six ways to reduce it; Nigerian cases: banking consolidation (2004-2005) and recapitalisation (2024), GSM (2001) and the Petroleum Industry Act (2021).","noteType":"guide_topic","number":3,"mustKnow":[{"text":"What a change agent is and does; internal vs external change agents; types and drivers of change; change leadership vs change management; Lewin's three steps and force field analysis; Kotter's eight steps; causes of resistance and the six ways to reduce it; Nigerian cases: banking consolidation (2004-2005) and recapitalisation (2024), GSM (2001) and the Petroleum Industry Act (2021)."}],"lessons":[{"number":"3.1","title":"The manager as change agent","mustKnow":[{"type":"list","ordered":false,"items":[{"text":[{"text":"Organisational change:","bold":true},{"text":" any alteration of people, structure or technology in an organisation."}]},{"text":[{"text":"Change agent:","bold":true},{"text":" a person or group who initiates, guides and supports change in an organisation; acts as a "},{"text":"catalyst","bold":true},{"text":" for change and takes responsibility for initiating and managing the change process. A manager can be one; so can a staff specialist or an outside consultant."}]},{"text":[{"text":"Manager's responsibility for transformation:","bold":true},{"text":" managers must "},{"text":"recognise the need for change, plan and lead it, and help staff adjust","bold":true},{"text":" to new ways of working. They do not avoid change, hand it all to consultants, or simply announce it and expect staff to adapt."}]}]},{"type":"paragraph","text":[{"text":"Roles of a change agent","bold":true}]},{"type":"list","ordered":true,"start":1,"items":[{"text":[{"text":"Diagnosing problems."}]},{"text":[{"text":"Communicating the need for change and a clear vision."}]},{"text":[{"text":"Facilitating communication and feedback."}]},{"text":[{"text":"Planning and supporting implementation."}]},{"text":[{"text":"Helping people cope (training, coaching, listening)."}]},{"text":[{"text":"Evaluating results and helping make the change stick."}]}]},{"type":"paragraph","text":[{"text":"Maintaining existing structures unchanged","bold":true},{"text":" is the opposite of a change agent's role."}]},{"type":"table","header":[[],[{"text":"Internal change agent (a manager or staff member)"}],[{"text":"External change agent (e.g. management consultant)"}]],"rows":[[[{"text":"Advantage"}],[{"text":"Knows the organisation's history, culture and people; has existing relationships"}],[{"text":"More "},{"text":"objective, fresh view","bold":true},{"text":"; new ideas; not tied to internal politics"}]],[[{"text":"Disadvantage"}],[{"text":"Colleagues may see him or her as "},{"text":"too close to existing relationships and politics to be objective","bold":true},{"text":", so may resist"}],[{"text":"May not fully understand the culture, history and people","bold":true},{"text":"; seen as an outsider; may push drastic change because he or she does not live with the results"}]]]}],"explainMore":[{"type":"list","ordered":false,"items":[{"text":[{"text":"Qualities of an effective managerial change agent:","bold":true},{"text":" builds trust, communicates a clear vision, listens to concerns, involves people, persists. "},{"text":"Keeping plans secret from those affected until the last minute","bold":true},{"text":" is a bad practice: it breeds rumour and resistance."}]},{"text":[{"text":"Organisational development (OD):","bold":true},{"text":" a planned, organisation-wide effort to improve effectiveness and health using "},{"text":"behavioural science","bold":true},{"text":" knowledge (team building, survey feedback, process consultation). It is not costing, company registration or a one-off staff cut."}]},{"text":[{"text":"Organisational learning","bold":true},{"text":" (a learning organisation keeps learning, adapting and changing) supports "},{"text":"innovation","bold":true},{"text":", not bureaucracy, rigidity or strategic drift."}]},{"text":[{"text":"Two metaphors: the "},{"text":"\"calm waters\"","bold":true},{"text":" view sees change as an occasional break in a stable voyage (Lewin's model fits it); the "},{"text":"\"white-water rapids\"","bold":true},{"text":" view sees change as constant and unpredictable, which is closer to Nigerian business today."}]}]}]},{"number":"3.2","title":"Types and drivers of change","mustKnow":[{"type":"paragraph","text":[{"text":"Types of change","bold":true}]},{"type":"list","ordered":true,"start":1,"items":[{"text":[{"text":"Planned change:","bold":true},{"text":" deliberately designed and implemented in advance by management to achieve specific goals. "},{"text":"Unplanned change","bold":true},{"text":" just happens (e.g. a sudden fire or a key manager's death)."}]},{"text":[{"text":"Incremental change:","bold":true},{"text":" small, continuous improvements. "},{"text":"Transformational (radical) change:","bold":true},{"text":" fundamentally alters strategy, structure or culture."}]},{"text":[{"text":"Proactive change","bold":true},{"text":" anticipates problems or opportunities; "},{"text":"reactive change","bold":true},{"text":" responds after they arrive."}]}]},{"type":"paragraph","text":[{"text":"Three areas managers change:","bold":true},{"text":" "},{"text":"structure","bold":true},{"text":" (design, authority, jobs), "},{"text":"technology","bold":true},{"text":" (equipment, processes, systems), "},{"text":"people","bold":true},{"text":" (attitudes, skills, behaviour)."}]},{"type":"paragraph","text":[{"text":"Corporate restructuring","bold":true},{"text":" may involve "},{"text":"downsizing","bold":true},{"text":", mergers, delayering or selling off divisions."}]},{"type":"paragraph","text":[{"text":"Drivers (forces) of change","bold":true}]},{"type":"table","header":[[{"text":"External drivers"$study_guide$);
insert into private.study_guide_chunks (guide, ordinal, chunk) values ('study_guide_bua201', 11, $study_guide$}],[{"text":"Internal drivers"}]],"rows":[[[{"text":"New "},{"text":"government regulation","bold":true},{"text":" or law (e.g. CBN capital rules, PIA)"}],[{"text":"Persistently "},{"text":"high staff turnover","bold":true}]],[[{"text":"Technology","bold":true},{"text":" (GSM, mobile apps, fintech)"}],[{"text":"Low morale","bold":true},{"text":" among employees"}]],[[{"text":"Competition","bold":true},{"text":" (new local or foreign rivals)"}],[{"text":"A new managing director or new strategy"}]],[[{"text":"Economic conditions (inflation, exchange rate, tax law)"}],[{"text":"A decision to restructure departments"}]],[[{"text":"Changing customer needs and demographics"}],[{"text":"Poor performance, conflict between departments"}]]]}],"explainMore":[{"type":"list","ordered":false,"items":[{"text":[{"text":"Trap:","bold":true},{"text":" a new tax law, rising inflation or a new foreign competitor is "},{"text":"external","bold":true},{"text":"; the appointment of a new MD or a decision to restructure departments is "},{"text":"internal","bold":true},{"text":" (it comes from inside, even if it responds to outside pressure)."}]},{"text":[{"text":"Example:","bold":true},{"text":" a traditional bank sees young customers move to mobile-only fintech apps, so it launches its own app and closes some branches. The driver is "},{"text":"technological change and competition in the external environment","bold":true},{"text":"."}]},{"text":[{"text":"For Nigerian firms in 2001, GSM was a "},{"text":"technological driver in the external environment","bold":true},{"text":": they changed how they sold goods, talked to customers and managed staff in the field."}]},{"text":[{"text":"The 2004-2005 banking consolidation was "},{"text":"radical (transformational)","bold":true},{"text":" change: the whole industry was remade, not adjusted."}]}]}]},{"number":"3.3","title":"Leading and managing change: Lewin and Kotter","mustKnow":[{"type":"list","ordered":false,"items":[{"text":[{"text":"Change management:","bold":true},{"text":" a structured approach to moving individuals and the organisation "},{"text":"from the current state to a desired future state","bold":true},{"text":", using processes and tools to implement and control the change (plans, timetables, training, milestones)."}]},{"text":[{"text":"Change leadership:","bold":true},{"text":" creating the "},{"text":"vision","bold":true},{"text":" and driving people to "},{"text":"embrace","bold":true},{"text":" change (inspiring, energising, urgency)."}]}]},{"type":"table","header":[[{"text":"Change leadership"}],[{"text":"Change management"}]],"rows":[[[{"text":"Vision, inspiration, urgency"}],[{"text":"Structure, plans, tools, control"}]],[[{"text":"Answers \"why\" and \"where to\""}],[{"text":"Answers \"how\" and \"when\""}]],[[{"text":"CEO tours regions painting a picture of a digital bank"}],[{"text":"Project office schedules branch software migration and tracks milestones"}]]]},{"type":"paragraph","text":[{"text":"Kurt Lewin's three-step model","bold":true},{"text":" (in order):"}]},{"type":"list","ordered":true,"start":1,"items":[{"text":[{"text":"Unfreezing:","bold":true},{"text":" making people aware that the current situation must change and preparing them for it."}]},{"text":[{"text":"Changing (moving):","bold":true},{"text":" installing the new system, structure or behaviour."}]},{"text":[{"text":"Refreezing:","bold":true},{"text":" "},{"text":"stabilising","bold":true},{"text":" the change so new behaviours become the norm (through rewards, policies, structures)."}]}]},{"type":"paragraph","text":[{"text":"Lewin's force field analysis:","bold":true},{"text":" the current state is held in balance by "},{"text":"driving forces","bold":true},{"text":" (pushing for change) and "},{"text":"restraining forces","bold":true},{"text":" (resisting change). To change, increase driving forces, reduce restraining forces, or both."}]},{"type":"paragraph","text":[{"text":"John Kotter's eight steps","bold":true},{"text":" (Leading Change, 1996):"}]},{"type":"list","ordered":true,"start":1,"items":[{"text":[{"text":"Establish a "},{"text":"sense of urgency","bold":true},{"text":" (first)."}]},{"text":[{"text":"Create a "},{"text":"guiding coalition","bold":true},{"text":": a group with enough power, credibility and skill to lead the change."}]},{"text":[{"text":"Develop a "},{"text":"vision and strategy","bold":true},{"text":"."}]},{"text":[{"text":"Communicate the change vision."}]},{"text":[{"text":"Empower employees for broad-based action (remove obstacles)."}]},{"text":[{"text":"Generate "},{"text":"short-term wins","bold":true},{"text":"."}]},{"text":[{"text":"Consolidate gains and produce more change."}]},{"text":[{"text":"Anchor","bold":true},{"text":" new approaches in the organisation's "},{"text":"culture","bold":true},{"text":" (last)."}]}]}],"explainMore":[{"type":"list","ordered":false,"items":[{"text":[{"text":"Force field worked example:","bold":true},{"text":" a manager rates forces for a new shift system from 1 (weak) to 5 (strong). Driving: competition from cheaper rivals 4, customer demand for longer hours 3, idle machines 5. Total driving = 4 + 3 + 5 = 12. Restraining: workers' fear of losing overtime pay 3, cost of retraining 4, union opposition 2. Total restraining = 3 + 4 + 2 = 9. Net = 12 − 9 = 3 in favour of change, but the manager should still reduce restraining forces (for instance, explain how pay will be protected). \"Workers' fear of losing overtime pay\" is a "},{"text":"restraining","bold":true},{"text":" force; \"competition from cheaper rivals\" is a "},{"text":"driving","bold":true},{"text":" force."}]},{"text":[{"text":"Kotter's short-term wins:","bold":true},{"text":" three months into a customer-service programme, publicly celebrating branches that halved queue times keeps momentum. A \"guiding coalition\" is "},{"text":"not","bold":true},{"text":" a union opposing change, a merger or government approval."}]},{"text":[{"text":"Wh$study_guide$);
insert into private.study_guide_chunks (guide, ordinal, chunk) values ('study_guide_bua201', 12, $study_guide$y change efforts fail (Kotter):","bold":true},{"text":" too much complacency (no urgency), no powerful guiding coalition, underestimating the vision, under-communicating it, letting obstacles block it, no short-term wins, "},{"text":"declaring victory too soon","bold":true},{"text":", and "},{"text":"not anchoring the change in the culture","bold":true},{"text":". "},{"text":"Clear communication of the reasons for change","bold":true},{"text":" is a cure, not a cause of failure."}]},{"text":[{"text":"Lewin's refreezing matches Kotter's step 8."}]}]}]},{"number":"3.4","title":"Resistance to change and how to manage it","mustKnow":[{"type":"paragraph","text":[{"text":"Causes of resistance","bold":true}]},{"type":"list","ordered":true,"start":1,"items":[{"text":[{"text":"Fear of the unknown","bold":true},{"text":" / fear of uncertainty (the most common cause)."}]},{"text":[{"text":"Fear of losing one's job, pay or skills (self-interest)."}]},{"text":[{"text":"Threats to existing "},{"text":"status and power","bold":true},{"text":"."}]},{"text":[{"text":"Habit and comfort with the familiar."}]},{"text":[{"text":"Belief that the change is wrong for the organisation; lack of trust."}]},{"text":[{"text":"Poor communication and no involvement."}]}]},{"type":"paragraph","text":[{"text":"Clear communication and involvement of employees","bold":true},{"text":" is "},{"text":"not","bold":true},{"text":" a cause; it reduces resistance."}]},{"type":"paragraph","text":[{"text":"Six methods of reducing resistance","bold":true},{"text":" (Kotter and Schlesinger):"}]},{"type":"list","ordered":true,"start":1,"items":[{"text":[{"text":"Education and communication:","bold":true},{"text":" workshops, data, answering questions so staff see why change is needed."}]},{"text":[{"text":"Participation and involvement:","bold":true},{"text":" letting affected people help design the change so they feel ownership. The "},{"text":"most effective","bold":true},{"text":" where it is feasible."}]},{"text":[{"text":"Facilitation and support:","bold":true},{"text":" training, counselling, time off to adjust."}]},{"text":[{"text":"Negotiation and agreement:","bold":true},{"text":" exchanging something of value (retraining, bonus) for acceptance."}]},{"text":[{"text":"Manipulation and co-optation:","bold":true},{"text":" covert influence, or giving resisters a token role."}]},{"text":[{"text":"Explicit and implicit coercion:","bold":true},{"text":" threats of job loss, transfer or no promotion."}]}]}],"explainMore":[{"type":"list","ordered":false,"items":[{"text":[{"text":"Match each case:","bold":true},{"text":" workshops before a new appraisal system = education and communication. Workers' representatives design a new schedule = participation and involvement. Union accepts an automated line in return for retraining and a one-off bonus = negotiation and agreement. \"Use the new attendance system by Friday or lose your job\" = explicit and implicit coercion."}]},{"text":[{"text":"Coercion, manipulation and threats are fast but damage trust and can backfire; managers use them only when speed is vital and other methods have failed."}]},{"text":[{"text":"An internal change agent may face more resistance because colleagues see him or her as part of existing politics; an outsider may face resistance for not understanding the culture."}]}]}]},{"number":"3.5","title":"Nigerian cases of change","mustKnow":[{"type":"paragraph","text":[{"text":"Banking consolidation (2004-2005)","bold":true}]},{"type":"list","ordered":false,"items":[{"text":[{"text":"CBN Governor "},{"text":"Charles Soludo","bold":true},{"text":" (announced July 2004) raised banks' minimum capital base from "},{"text":"₦2 billion to ₦25 billion","bold":true},{"text":", deadline 31 December 2005."}]},{"text":[{"text":"Banks merged, were acquired or failed; the number fell from about "},{"text":"89 to 25","bold":true},{"text":"."}]},{"text":[{"text":"It was "},{"text":"radical (transformational)","bold":true},{"text":" change and, for bank managers, an "},{"text":"external, regulatory driver","bold":true},{"text":" of change."}]}]},{"type":"paragraph","text":[{"text":"Bank recapitalisation (announced March 2024, Governor Olayemi Cardoso)","bold":true}]},{"type":"table","header":[[{"text":"Licence"}],[{"text":"New minimum capital"}]],"rows":[[[{"text":"Commercial, international"}],[{"text":"₦500 billion","bold":true}]],[[{"text":"Commercial, national"}],[{"text":"₦200 billion"}]],[[{"text":"Commercial, regional"}],[{"text":"₦50 billion"}]],[[{"text":"Merchant bank"}],[{"text":"₦50 billion"}]],[[{"text":"Non-interest, national / regional"}],[{"text":"₦20 billion / ₦10 billion"}]]]},{"type":"list","ordered":false,"items":[{"text":[{"text":"Deadline: "},{"text":"31 March 2026","bold":true},{"text":". Banks had to raise fresh capital, merge, or change licence category."}]}]},{"type":"paragraph","text":[{"text":"Telecommunications liberalisation (GSM, 2001)","bold":true}]},{"type":"list","ordered":false,"items":[{"text":[{"text":"The "},{"text":"Nigerian Communications Commission (NCC)","bold":true},{"text":" auctioned GSM licences in "},{"text":"January 2001","bold":true},{"text":"; each successful bidder paid "},{"text":"285 million US dollars","bold":true},{"text":"."}]},{"text":[{"text":"MTN Nigeria","bold":true},{"text":" and "},{"text":"Econet Wireless","bold":true},{"text":" launched commercial GSM services in "},{"text":"August 2001","bold":true},{"text":"."}]}]},{"type":"paragraph","text":[{"text":"Petroleum Industry Act (PIA)","bold":true}]},{"type":"list","ordered":false,"items":[{"text":[{"text":"Signed into law in "},{"text":"August 2021","bold":true},{"text":" (by President Muhammadu Buhari)."}]},{"text":[{"text":"NNPC","bold":true},{"text":" incorporated as a "},{"text":"limited liability company","bold":true},{"text":" (NNPC Limited) with the Corporate Affairs Commission."}]},{"text":[{"text":"Two regulators:","bold":true},{"text":" the Nigerian Upstream Petrol$study_guide$);
insert into private.study_guide_chunks (guide, ordinal, chunk) values ('study_guide_bua201', 13, $study_guide$eum Regulatory Commission ("},{"text":"NUPRC","bold":true},{"text":", upstream) and the Nigerian Midstream and Downstream Petroleum Regulatory Authority ("},{"text":"NMDPRA","bold":true},{"text":", midstream and downstream)."}]},{"text":[{"text":"Upstream companies contribute "},{"text":"3%","bold":true},{"text":" of their actual annual operating expenditure of the preceding year to "},{"text":"host community development trusts","bold":true},{"text":"."}]}]}],"explainMore":[{"type":"list","ordered":false,"items":[{"text":[{"text":"89 to 25 means 89 − 25 = 64 fewer banks, a fall of about 72% (64 ÷ 89 = 71.9%, rounded). The capital base rose 12.5 times (25 ÷ 2)."}]},{"text":[{"text":"Econet's Nigerian business later became Vmobile, then Celtel, then Zain, and today "},{"text":"Airtel","bold":true},{"text":". Globacom entered later (licensed 2002, launched 2003), so it was not one of the August 2001 launchers. NITEL was the old state operator, not a 2001 auction winner that launched in August."}]},{"text":[{"text":"The NCC is the telecoms regulator; do not confuse it with the CBN (banks), the CAC (company registration) or the BPE (privatisation)."}]},{"text":[{"text":"Host community example:","bold":true},{"text":" an upstream firm whose operating expenditure last year was ₦300 million must contribute 3% × ₦300 million = ₦9 million."}]},{"text":[{"text":"Lesson for managers in all four cases: the driver was external (regulation or technology), and firms that unfroze early, built a clear vision and communicated it handled the change better than those that resisted."}]}]}]}],"recap":[{"type":"list","ordered":false,"items":[{"text":[{"text":"Change agent = person or group who initiates, guides and supports change; a catalyst."}]},{"text":[{"text":"Internal agent knows the culture but may seem too close to politics; external agent is objective but may not understand the culture."}]},{"text":[{"text":"Types: planned/unplanned, incremental/transformational, proactive/reactive. Areas: structure, technology, people."}]},{"text":[{"text":"External drivers: regulation, technology, competition, economy. Internal: turnover, morale, new MD, restructuring."}]},{"text":[{"text":"Change leadership = vision and inspiration; change management = structured process and tools."}]},{"text":[{"text":"Lewin: unfreezing, changing, refreezing; force field = driving vs restraining forces."}]},{"text":[{"text":"Kotter: 8 steps, from sense of urgency (first) to anchoring in culture (last)."}]},{"text":[{"text":"Main cause of resistance: fear of the unknown. Most effective cure: participation and involvement."}]},{"text":[{"text":"Nigeria: ₦2bn to ₦25bn, 89 to 25 banks (Soludo, 2004-2005); ₦500bn international licence by 31 March 2026; NCC GSM auction, 285 million US dollars each, MTN and Econet launched August 2001; PIA August 2021, NNPC Limited, NUPRC and NMDPRA, 3% to host communities."}]}]}],"theory":{"itemId":"52d4b3bc-6bf9-5c5e-8957-3ab0f40d146a","question":[{"type":"paragraph","text":[{"text":"Under the 2024 recapitalisation, a commercial bank with ₦120 billion of qualifying capital wants to keep an international licence. How much new capital must it raise, and what would the shortfall be if it chose a national licence instead? Name two ways it could close the gap."}]}]},"practice":[{"topic":"Managers as Change Agents","named":false}]}},{"kind":"note","itemId":"c827312c-c262-59a9-aa24-684b9add693c","sourceKey":"guide-topic:4","position":4,"payload":{"title":"Forms of Business Ownership","body":"Sole proprietorship, partnership (ordinary, limited, LLP), companies (limited by shares, by guarantee, unlimited; private and public), cooperatives, franchises, family businesses and public enterprises: features, advantages and limitations; how to choose a form; the Nigerian rules under CAMA 2020 and the role of the CAC.","noteType":"guide_topic","number":4,"mustKnow":[{"text":"Sole proprietorship, partnership (ordinary, limited, LLP), companies (limited by shares, by guarantee, unlimited; private and public), cooperatives, franchises, family businesses and public enterprises: features, advantages and limitations; how to choose a form; the Nigerian rules under CAMA 2020 and the role of the CAC."}],"lessons":[{"number":"4.1","title":"Sole proprietorship","mustKnow":[{"type":"list","ordered":false,"items":[{"text":[{"text":"Sole proprietorship (sole trader):","bold":true},{"text":" a business owned and controlled by "},{"text":"one person","bold":true},{"text":", who takes all the profits and bears all the risks. It may employ others and use family help, but there is one owner."}]},{"text":[{"text":"Unlimited liability:","bold":true},{"text":" the owner's "},{"text":"personal assets can be taken to pay the debts of the business","bold":true},{"text":". The business and the owner are the same person in law."}]},{"text":[{"text":"Registration:","bold":true},{"text":" a sole trader using a name other than his or her own true name registers a "},{"text":"business name","bold":true},{"text":" with the "},{"text":"Corporate Affairs Commission (CAC)","bold":true},{"text":"."}]}]},{"type":"table","header":[[{"text":"Advantages"}],[{"text":"Limitations"}]],"rows":[[[{"text":"Easy, cheap and quick to start"}],[{"text":"Limited access to capital","bold":true},{"text":" (the major weakness)"}]],[[{"text":"Quick decision-making","bold":true},{"text":": no one to consult"}],[{"text":"Unlimited liability","bold":true}]],[[{"text":"Owner keeps all profits"}],[{"text":"Lack of continuity","bold":true},{"text":": may end on the owner's death"}]],[[{"text":"Close contact with customers; privacy of affairs"}],[{"text":"Owner's limited skills; heavy workload"}]],[[{"text":"Little regulation"}],[{"text":"Hard to grow large"}]]]}],"explainMore":[{"type":"list","ordered":false,"items":[{"text":[{"text":"Worked example (unlimited liability):","bold":true},{"text":" Ngozi's fashion shop owes suppliers ₦3,000,000 but has assets of only ₦1,000,000. Sho$study_guide$);
insert into private.study_guide_chunks (guide, ordinal, chunk) values ('study_guide_bua201', 14, $study_guide$rtfall = ₦3,000,000 − ₦1,000,000 = ₦2,000,000. Ngozi can be made to pay the "},{"text":"₦2,000,000 from her personal assets","bold":true},{"text":" (car, savings, land). Suppliers are not forced to write it off."}]},{"text":[{"text":"Lack of continuity:","bold":true},{"text":" Mr Adewale's well-run printing shop in Ibadan closes after his sudden death because nobody else is legally entitled to continue it."}]},{"text":[{"text":"Traps:","bold":true},{"text":" continuity after death, easy access to large capital, and limited liability are company features, not sole-trader advantages. Separation of ownership and control and double taxation are company issues, not sole-trader weaknesses."}]},{"text":[{"text":"Most Nigerian businesses (market traders, barbers, tailors, provision shops) are sole proprietorships."}]}]}]},{"number":"4.2","title":"Partnerships","mustKnow":[{"type":"list","ordered":false,"items":[{"text":[{"text":"Partnership:","bold":true},{"text":" the relationship between persons "},{"text":"carrying on a business in common with a view of profit","bold":true},{"text":"."}]},{"text":[{"text":"Size limit (section 19, CAMA 2020):","bold":true},{"text":" a partnership formed to carry on business for profit may not have "},{"text":"more than 20 persons","bold":true},{"text":" unless it is registered as a company or formed under another enactment. The limit does "},{"text":"not","bold":true},{"text":" apply to partnerships of "},{"text":"legal practitioners or accountants","bold":true},{"text":"."}]},{"text":[{"text":"Partnership deed (agreement):","bold":true},{"text":" capital contributed by each partner; profit- and loss-sharing ratio; partners' duties and salaries; interest on capital and drawings; procedure for "},{"text":"admitting or retiring a partner","bold":true},{"text":"; dissolution. (A "},{"text":"memorandum of association","bold":true},{"text":" belongs to a company, not a partnership deed.)"}]},{"text":[{"text":"No agreement on profits:","bold":true},{"text":" profits and losses are shared "},{"text":"equally","bold":true},{"text":"."}]},{"text":[{"text":"Joint and several liability:","bold":true},{"text":" partners are liable together, "},{"text":"and each partner can also be held personally liable for all the firm's debts","bold":true},{"text":"."}]},{"text":[{"text":"Mutual agency:","bold":true},{"text":" each partner can "},{"text":"bind the firm and the other partners","bold":true},{"text":" by acts done in the ordinary course of business."}]}]},{"type":"paragraph","text":[{"text":"Types of partners","bold":true}]},{"type":"list","ordered":true,"start":1,"items":[{"text":[{"text":"Active (general) partner:","bold":true},{"text":" contributes capital and manages; unlimited liability."}]},{"text":[{"text":"Sleeping (dormant) partner:","bold":true},{"text":" contributes capital and shares profits but "},{"text":"takes no part in management","bold":true},{"text":"."}]},{"text":[{"text":"Nominal partner:","bold":true},{"text":" lends only his or her "},{"text":"name","bold":true},{"text":" for reputation; contributes no capital and no management."}]},{"text":[{"text":"Limited partner:","bold":true},{"text":" liability limited to capital contributed; must not manage."}]}]},{"type":"paragraph","text":[{"text":"Types of partnership under CAMA 2020","bold":true}]},{"type":"table","header":[[],[{"text":"Ordinary partnership"}],[{"text":"Limited partnership (LP)"}],[{"text":"Limited liability partnership (LLP)"}]],"rows":[[[{"text":"Members"}],[{"text":"2 to 20 (except lawyers, accountants)"}],[{"text":"At least "},{"text":"one general partner and one limited partner","bold":true}],[{"text":"At least "},{"text":"two designated partners","bold":true},{"text":" who are individuals, "},{"text":"at least one resident in Nigeria","bold":true}]],[[{"text":"Liability"}],[{"text":"Unlimited, joint and several"}],[{"text":"General: unlimited; limited partner: limited to contribution"}],[{"text":"Partners' liability limited"}]],[[{"text":"Legal person?"}],[{"text":"No"}],[{"text":"No"}],[{"text":"Yes","bold":true},{"text":": can sue, be sued and hold property in its own name"}]],[[{"text":"Registration"}],[{"text":"Business name with CAC"}],[{"text":"Registered with CAC"}],[{"text":"Registered with CAC"}]]]}],"explainMore":[{"type":"list","ordered":false,"items":[{"text":[{"text":"Limited partner who manages:","bold":true},{"text":" Funke, a limited partner, starts managing the firm and signing contracts. She "},{"text":"becomes liable for the firm's debts incurred while she takes part in management","bold":true},{"text":". She does not become a director or lose her profits permanently."}]},{"text":[{"text":"Profit-sharing worked example:","bold":true},{"text":" Ade, Bisi and Chuka contribute ₦6,000,000, ₦3,000,000 and ₦1,000,000; profit is ₦4,500,000."}],"blocks":[{"type":"list","ordered":false,"items":[{"text":[{"text":"No agreement: ₦4,500,000 ÷ 3 = "},{"text":"₦1,500,000 each","bold":true},{"text":"."}]},{"text":[{"text":"If the deed says \"in capital ratio\" (6:3:1, total 10): Ade 6/10 × ₦4,500,000 = ₦2,700,000; Bisi 3/10 × ₦4,500,000 = ₦1,350,000; Chuka 1/10 × ₦4,500,000 = ₦450,000. Check: 2,700,000 + 1,350,000 + 450,000 = 4,500,000."}]}]}]},{"text":[{"text":"Advantages:","bold":true},{"text":" more capital and skills than a sole trader; shared workload and risk; easy to form; privacy. "},{"text":"Limitations:","bold":true},{"text":" unlimited liability; mutual agency means one partner's mistake binds all; disagreements; lack of continuity (death, retirement or bankruptcy of a partner can dissolve the firm); still limited capital."}]},{"text":[{"text":"Law and accounting firms often run as partnerships, which is why they are exempt from the 20-person limit."}]}]}]},{"number":"4.3","title":"Limited liability companies","mustKnow":[{"type":"list","ordered":false,"items":[{"text":[{"text":"Corporate personality (separate legal entity):","bold":true},{"text":" a registered company $study_guide$);
insert into private.study_guide_chunks (guide, ordinal, chunk) values ('study_guide_bua201', 15, $study_guide$is a legal person "},{"text":"separate from its owners","bold":true},{"text":"; it can own property, sue and be sued in its own name. Established in "},{"text":"Salomon v Salomon and Co Ltd (1897)","bold":true},{"text":". It mainly protects shareholders from "},{"text":"personal liability for the company's debts","bold":true},{"text":"."}]},{"text":[{"text":"Perpetual succession:","bold":true},{"text":" the company continues to exist even when shareholders die or sell their shares."}]},{"text":[{"text":"Limited liability (company limited by shares):","bold":true},{"text":" a member's liability is limited to the "},{"text":"amount, if any, unpaid on the shares","bold":true},{"text":" he or she holds."}]}]},{"type":"paragraph","text":[{"text":"Types of company (section 21, CAMA 2020)","bold":true}]},{"type":"list","ordered":true,"start":1,"items":[{"text":[{"text":"Company limited by shares:","bold":true},{"text":" private (\"Ltd\") or public (\"Plc\")."}]},{"text":[{"text":"Company limited by guarantee:","bold":true},{"text":" no share capital; liability limited to the "},{"text":"amount each member undertook to contribute to the company's assets if it is wound up","bold":true},{"text":". Used for non-profit objects (education, charity, religion, sport); no profits are distributed to members."}]},{"text":[{"text":"Unlimited company:","bold":true},{"text":" if liabilities exceed assets on winding up, members "},{"text":"can be required to contribute from their personal assets","bold":true},{"text":" to settle the shortfall."}]}]},{"type":"paragraph","text":[{"text":"Private vs public company (CAMA 2020)","bold":true}]},{"type":"table","header":[[],[{"text":"Private company (Ltd)"}],[{"text":"Public company (Plc)"}]],"rows":[[[{"text":"Members"}],[{"text":"Minimum "},{"text":"1","bold":true},{"text":" (single-member company, new in CAMA 2020); maximum "},{"text":"50","bold":true},{"text":" (joint holders count as one)"}],[{"text":"Minimum 2; no maximum"}]],[[{"text":"Shares"}],[{"text":"Restricts transfer","bold":true},{"text":"; may "},{"text":"not","bold":true},{"text":" invite the public to subscribe"}],[{"text":"May invite the public to subscribe","bold":true},{"text":"; may list on the Nigerian Exchange"}]],[[{"text":"Minimum issued share capital"}],[{"text":"₦100,000","bold":true}],[{"text":"₦2,000,000","bold":true}]],[[{"text":"Directors"}],[{"text":"At least 2 (a small company may have 1)"}],[{"text":"At least "},{"text":"three independent directors","bold":true},{"text":" among its directors"}]],[[{"text":"Company secretary"}],[{"text":"Not mandatory","bold":true},{"text":" for a small private company"}],[{"text":"Required"}]]]},{"type":"paragraph","text":[{"text":"Other CAMA 2020 rules","bold":true}]},{"type":"list","ordered":false,"items":[{"text":[{"text":"Small company:","bold":true},{"text":" need not "},{"text":"appoint auditors","bold":true},{"text":". (It still registers with the CAC, keeps accounting records and has at least one member.)"}]},{"text":[{"text":"Section 305:","bold":true},{"text":" a director stands in a fiduciary relationship towards "},{"text":"the company itself","bold":true},{"text":" (not primarily the shareholders, customers or employees)."}]},{"text":[{"text":"Section 307:","bold":true},{"text":" no person may be a director of "},{"text":"more than five public companies","bold":true},{"text":" at the same time."}]},{"text":[{"text":"Memorandum of association:","bold":true},{"text":" the company's basic constitution: name, registered office, objects or business, liability of members, share capital. "},{"text":"Articles of association:","bold":true},{"text":" detailed internal rules (meetings, appointment of directors, transfer of shares)."}]}]}],"explainMore":[{"type":"list","ordered":false,"items":[{"text":[{"text":"Worked example (limited liability):","bold":true},{"text":" Tunde holds 20,000 shares of ₦5 each and has paid ₦3 per share. If the company fails, his maximum further liability = 20,000 × (₦5 − ₦3) = "},{"text":"₦40,000","bold":true},{"text":". Once shares are fully paid, he owes nothing more. A guarantee member who undertook ₦50,000 can be called on for at most ₦50,000, and only on winding up."}]},{"text":[{"text":"Joint-stock companies","bold":true},{"text":" emerged mainly to "},{"text":"finance large-scale ventures","bold":true},{"text":" (overseas trade, railways) that no single owner could fund; investors pooled capital and later gained limited liability. Modern companies differ from sole traders mainly by "},{"text":"separate legal personality and limited liability","bold":true},{"text":"."}]},{"text":[{"text":"Best mix of limited liability and operational flexibility:","bold":true},{"text":" a "},{"text":"private limited company","bold":true},{"text":" (fewer disclosure rules than a Plc, yet limited liability)."}]},{"text":[{"text":"PLC vs private company trap:","bold":true},{"text":" both give limited liability and both have legal personality; what makes a Plc different is that it "},{"text":"can invite the public to subscribe for its shares","bold":true},{"text":". Sharing profits by patronage describes a cooperative."}]},{"text":[{"text":"Plc advantages:","bold":true},{"text":" raises large capital from the public; perpetual succession; professional managers; shares are easy to transfer. "},{"text":"Plc disadvantages:","bold":true},{"text":" must "},{"text":"disclose a great deal of information and comply with heavy regulation","bold":true},{"text":" (CAC, SEC, the Nigerian Exchange); costly to form; separation of ownership and control; double taxation (company tax on profits, then tax on dividends)."}]},{"text":[{"text":"CAMA 2020 was signed in "},{"text":"August 2020","bold":true},{"text":", replacing CAMA 1990. It introduced the single-member private company and replaced \"authorised share capital\" with "},{"text":"minimum issued share capital","bold":true},{"text":"."}]},{"text":[{"text":"Nigerian examples: Dangote Cement Plc$study_guide$);
insert into private.study_guide_chunks (guide, ordinal, chunk) values ('study_guide_bua201', 16, $study_guide$, MTN Nigeria Communications Plc and Nestlé Nigeria Plc are public companies listed on the Nigerian Exchange."}]}]}]},{"number":"4.4","title":"Cooperatives, franchises, family businesses and public enterprises","mustKnow":[{"type":"list","ordered":false,"items":[{"text":[{"text":"Cooperative society:","bold":true},{"text":" a voluntary association of people who join together on equal terms to meet their common economic needs through a "},{"text":"jointly owned and democratically controlled","bold":true},{"text":" enterprise. Its aim is to "},{"text":"provide benefits to its members","bold":true},{"text":", not returns for outside investors."}],"blocks":[{"type":"list","ordered":false,"items":[{"text":[{"text":"Voting: "},{"text":"one member, one vote","bold":true},{"text":", regardless of shares held."}]},{"text":[{"text":"Surplus: shared in proportion to the "},{"text":"business each member did with the society (patronage)","bold":true},{"text":"."}]}]}]}]},{"type":"paragraph","text":[{"text":"Types of cooperative","bold":true}]},{"type":"list","ordered":true,"start":1,"items":[{"text":[{"text":"Thrift and credit (savings and loans):","bold":true},{"text":" members save monthly and borrow at low interest."}]},{"text":[{"text":"Marketing:","bold":true},{"text":" producers collect, grade and sell their output together for better prices."}]},{"text":[{"text":"Consumers':","bold":true},{"text":" members buy goods in bulk for their own use."}]},{"text":[{"text":"Producers':","bold":true},{"text":" members pool resources to produce goods."}]},{"text":[{"text":"Multipurpose:","bold":true},{"text":" combines several of these."}]}]},{"type":"list","ordered":false,"items":[{"text":[{"text":"Franchise:","bold":true},{"text":" an arrangement in which a business owner ("},{"text":"franchisor","bold":true},{"text":") grants another party ("},{"text":"franchisee","bold":true},{"text":") the right to sell its products under its "},{"text":"brand name and business system","bold":true},{"text":", in return for fees or royalties. The franchisor earns mainly through "},{"text":"royalties and franchise fees","bold":true},{"text":"."}]},{"text":[{"text":"Family business:","bold":true},{"text":" owned and controlled by members of one family, often across generations; can take any legal form."}]},{"text":[{"text":"Public enterprise:","bold":true},{"text":" a business owned and controlled wholly or mainly by "},{"text":"government","bold":true},{"text":" to provide goods or services to the public. A "},{"text":"statutory corporation","bold":true},{"text":" is a public enterprise set up by a "},{"text":"specific Act of the legislature","bold":true},{"text":" that defines its powers, functions and management."}]},{"text":[{"text":"Privatisation","bold":true},{"text":" transfers ownership to private investors. "},{"text":"Commercialisation","bold":true},{"text":" keeps government ownership but requires the enterprise to run on commercial, profit-making lines."}]}]}],"explainMore":[{"type":"list","ordered":false,"items":[{"text":[{"text":"Cooperative cases:","bold":true},{"text":" hospital staff in Lagos contributing monthly from salaries for low-interest loans = "},{"text":"thrift and credit","bold":true},{"text":". Ondo State cocoa farmers collecting, grading and selling cocoa together = "},{"text":"marketing","bold":true},{"text":"."}]},{"text":[{"text":"Cooperative strengths:","bold":true},{"text":" democratic control, cheaper goods or credit for members, limited liability once registered. "},{"text":"Weaknesses:","bold":true},{"text":" limited capital, weak management, member disputes."}]},{"text":[{"text":"Franchise:","bold":true},{"text":" Domino's Pizza and Cold Stone Creamery in Nigeria are run by Eat'N'Go as franchisee. "},{"text":"For the franchisee:","bold":true},{"text":" proven brand, training, support; "},{"text":"but","bold":true},{"text":" fees, royalties and strict rules. "},{"text":"For the franchisor:","bold":true},{"text":" fast growth with others' capital; "},{"text":"but","bold":true},{"text":" less control over quality."}]},{"text":[{"text":"Family business:","bold":true},{"text":" strengths are trust, commitment and long-term view; weaknesses are "},{"text":"succession","bold":true},{"text":" disputes, mixing family and business money, and appointing relatives over qualified outsiders."}]},{"text":[{"text":"Why governments set up public enterprises:","bold":true},{"text":" to control strategic sectors, provide essential services private firms may neglect, prevent private monopolies exploiting consumers, create jobs. "},{"text":"Maximising profits for private shareholders is not a reason.","bold":true}]},{"text":[{"text":"Common problems in Nigeria:","bold":true},{"text":" "},{"text":"political interference","bold":true},{"text":" in appointments and decisions, inefficiency, corruption, dependence on subsidies."}]},{"text":[{"text":"The Bureau of Public Enterprises (BPE) carries out privatisation. Examples: the power sector (PHCN successor companies handed to private owners in 2013); NNPC moved the other way, from statutory corporation to NNPC Limited under the Petroleum Industry Act 2021."}]}]}]},{"number":"4.5","title":"Choosing a form of ownership and the Nigerian regulatory context","mustKnow":[{"type":"paragraph","text":[{"text":"Considerations when choosing a form","bold":true}]},{"type":"list","ordered":true,"start":1,"items":[{"text":[{"text":"Financial:","bold":true},{"text":" amount of capital needed and how it can be raised; cost of formation; tax."}]},{"text":[{"text":"Managerial:","bold":true},{"text":" skills available; how quickly decisions must be made; desired control."}]},{"text":[{"text":"Legal:","bold":true},{"text":" "},{"text":"extent of owners' liability","bold":true},{"text":" for business debts; registration and disclosure requirements; continuity; ease of transfer of ownership."}]}]},{"type":"paragraph","text":[{"text":"Regulator:","bold":true},{"text":" the "},{"te$study_guide$);
insert into private.study_guide_chunks (guide, ordinal, chunk) values ('study_guide_bua201', 17, $study_guide$xt":"Corporate Affairs Commission (CAC)","bold":true},{"text":" registers companies, business names, limited partnerships, limited liability partnerships and incorporated trustees under the "},{"text":"Companies and Allied Matters Act (CAMA) 2020","bold":true},{"text":". (Not the CBN, SEC or NIM.)"}]},{"type":"table","header":[[{"text":"Form"}],[{"text":"Owners"}],[{"text":"Liability"}],[{"text":"Legal person"}],[{"text":"Continuity"}]],"rows":[[[{"text":"Sole proprietorship"}],[{"text":"1"}],[{"text":"Unlimited"}],[{"text":"No"}],[{"text":"Weak"}]],[[{"text":"Ordinary partnership"}],[{"text":"2 to 20"}],[{"text":"Unlimited, joint and several"}],[{"text":"No"}],[{"text":"Weak"}]],[[{"text":"LLP"}],[{"text":"2 or more"}],[{"text":"Limited"}],[{"text":"Yes"}],[{"text":"Strong"}]],[[{"text":"Private company (Ltd)"}],[{"text":"1 to 50"}],[{"text":"Limited"}],[{"text":"Yes"}],[{"text":"Perpetual"}]],[[{"text":"Public company (Plc)"}],[{"text":"2 or more"}],[{"text":"Limited"}],[{"text":"Yes"}],[{"text":"Perpetual"}]],[[{"text":"Cooperative"}],[{"text":"Members, equal votes"}],[{"text":"Limited (when registered)"}],[{"text":"Yes (when registered)"}],[{"text":"Strong"}]]]}],"explainMore":[{"type":"list","ordered":false,"items":[{"text":[{"text":"An entrepreneur who needs "},{"text":"substantial capital","bold":true},{"text":" and wants to "},{"text":"protect owners' personal assets","bold":true},{"text":" should choose a "},{"text":"limited liability company","bold":true},{"text":", not a sole proprietorship, ordinary partnership or business name."}]},{"text":[{"text":"A Lagos alumni body promoting education and awarding scholarships, with no profits distributed, should register a "},{"text":"company limited by guarantee","bold":true},{"text":"."}]},{"text":[{"text":"Trap:","bold":true},{"text":" \"liability\" is the "},{"text":"legal","bold":true},{"text":" consideration; capital is financial; skills and decision speed are managerial."}]},{"text":[{"text":"The "},{"text":"SEC","bold":true},{"text":" regulates public offers of shares; the "},{"text":"CBN","bold":true},{"text":" regulates banks; the CAC handles registration. Cooperatives register with the government's cooperative department under cooperative law, not as CAMA companies."}]}]}]}],"recap":[{"type":"list","ordered":false,"items":[{"text":[{"text":"Sole trader: one owner, all profits, all risk, unlimited liability; major weakness is limited capital; may end on death."}]},{"text":[{"text":"Partnership: business in common with a view of profit; maximum 20 (lawyers and accountants exempt); equal sharing if no agreement; joint and several liability; mutual agency."}]},{"text":[{"text":"Partners: active, sleeping (capital, no management), nominal (name only), limited."}]},{"text":[{"text":"LP: at least one general and one limited partner; LLP: separate legal person, two designated partners, one resident in Nigeria."}]},{"text":[{"text":"Company: separate legal person (Salomon, 1897), perpetual succession; limited by shares (unpaid amount), by guarantee (amount undertaken), or unlimited."}]},{"text":[{"text":"CAMA 2020: single-member private company; private maximum 50 members; ₦100,000 and ₦2,000,000 minimum issued capital; Plc at least three independent directors; maximum five public directorships; small companies need no auditor or mandatory secretary; directors owe duties to the company."}]},{"text":[{"text":"Cooperative: one member, one vote; surplus by patronage; thrift and credit, marketing, consumers', producers'."}]},{"text":[{"text":"Franchise: royalties and fees. Public enterprise: government-owned; statutory corporation = created by Act; privatisation sells, commercialisation keeps ownership."}]},{"text":[{"text":"Choose by financial, managerial and legal factors; CAC registers under CAMA 2020."}]}]}],"theory":{"itemId":"dbb16b8f-ee0a-547a-82f6-f07df9c6b3bf","question":[{"type":"paragraph","text":[{"text":"Kemi and Dayo start a business with ₦5,000,000 of capital. It later owes ₦8,000,000 and its assets are worth ₦2,000,000. How much of the debt can creditors recover from the owners' personal assets if the business is (a) an ordinary partnership, (b) a private company limited by shares whose shares are fully paid?"}]}]},"practice":[{"topic":"Forms of Business Ownership","named":false}]}},{"kind":"note","itemId":"dd063cbe-cd1e-5328-9200-67f5874661ea","sourceKey":"guide-topic:5","position":5,"payload":{"title":"Corporate Governance, Leadership and Management as a Profession","body":"What a profession is and its characteristics; why management is a profession in Nigeria (NIM, Act 14 of 2003) and why some call it a semi-profession; ethics, codes and the NIM values; corporate governance meaning, principles and theories; the NCCG 2018 and the FRC; the leadership theories; leadership ethics and responsible leadership.","noteType":"guide_topic","number":5,"mustKnow":[{"text":"What a profession is and its characteristics; why management is a profession in Nigeria (NIM, Act 14 of 2003) and why some call it a semi-profession; ethics, codes and the NIM values; corporate governance meaning, principles and theories; the NCCG 2018 and the FRC; the leadership theories; leadership ethics and responsible leadership."}],"lessons":[{"number":"5.1","title":"Profession and management as a profession","mustKnow":[{"type":"list","ordered":false,"items":[{"text":[{"text":"Profession:","bold":true},{"text":" a regular work or occupation. Profession and practitioner: teaching/teacher, medicine/doctor, engineering/engineer, law/lawyer, architecture/architect, carpentry/carpenter."}]},{"text":[{"text":"Characteristics of a profession (6):","bold":true}]}]},{"type":"list","ordered":true,"start":1,"items":[{"text":[{"text":"Training:","bold":true},{"text":" extensive training to acquire specialised knowledge. Most professions require both education and training."}]},{"text":[{"text":"Skills/expertise:","bold":true},{"text":" these result from experience and $study_guide$);
insert into private.study_guide_chunks (guide, ordinal, chunk) values ('study_guide_bua201', 18, $study_guide$practice in applying knowledge."}]},{"text":[{"text":"Licence or certification:","bold":true},{"text":" a permission granted by a professional body or government authority to individuals who meet specific qualifications, which allows them to practise a profession."}]},{"text":[{"text":"Ethics:","bold":true},{"text":" the principles an organisation sets for itself in its internal and external dealings. A "},{"text":"code of ethics","bold":true},{"text":" provides the overarching moral principles and values."}]},{"text":[{"text":"Code of conduct:","bold":true},{"text":" translates the ethical principles into practical guidelines for behaviour, e.g. compliance with the law and avoiding conflicts of interest."}]},{"text":[{"text":"Standards:","bold":true},{"text":" criteria or measures for the quality of practice or performance, e.g. units of measurement, building regulations, quality management systems such as "},{"text":"ISO 9000","bold":true},{"text":"."}]}]},{"type":"list","ordered":false,"items":[{"text":[{"text":"Management (Weihrich, Cannice and Koontz, 2008):","bold":true},{"text":" the process of designing and maintaining an environment in which individuals, working together in groups, efficiently (and effectively) accomplish selected aims. It is the art of getting things done through and with others."}]},{"text":[{"text":"Management is a profession in Nigeria","bold":true},{"text":" because it involves "},{"text":"education, training (specialised knowledge), skills, ethical codes of conduct and a statutory or regulatory body","bold":true},{"text":"."}]},{"text":[{"text":"Nigerian Institute of Management (Chartered), NIM:","bold":true},{"text":" the statutory regulatory body established by an Act of the National Assembly, the "},{"text":"NIM (Establishment) Act No. 14 of 2003","bold":true},{"text":", to regulate and control the management profession in Nigeria. NIM "},{"text":"determines standards","bold":true},{"text":" for the management profession and "},{"text":"controls the practice","bold":true},{"text":" of management in Nigeria."}]}]}],"explainMore":[{"type":"list","ordered":false,"items":[{"text":[{"text":"What separates a profession from an ordinary occupation:","bold":true},{"text":" it "},{"text":"enforces discipline through a recognised professional body","bold":true},{"text":" (which licenses members, sets standards and can sanction misconduct). A profession does "},{"text":"not","bold":true},{"text":" guarantee a high income, and long experience or working with people alone does not make an occupation a profession."}]},{"text":[{"text":"Not characteristics of a profession","bold":true},{"text":" (exam distractors): a guaranteed high income for every member; membership passed down automatically from parent to child; paying a fee; holding a government post."}]},{"text":[{"text":"Match the term to its description:","bold":true},{"text":" \"permission to practise\" = licence/certification; \"practical guidelines such as obeying the law and avoiding conflicts of interest\" = code of conduct; \"overarching moral principles\" = code of ethics; \"quality measures such as ISO 9000\" = standards; \"extensive preparation combining education and practical instruction\" = training."}]},{"text":[{"text":"Code of ethics vs code of conduct:","bold":true},{"text":" the code of ethics states the broad moral principles (the \"why\"); the code of conduct turns them into specific rules of behaviour (the \"what to do\")."}]},{"text":[{"text":"Which body regulates what (do not swap them):","bold":true}]}]},{"type":"table","header":[[{"text":"Body"}],[{"text":"What it does"}]],"rows":[[[{"text":"Nigerian Institute of Management (Chartered), NIM"}],[{"text":"Regulates and controls the management profession; sets standards"}]],[[{"text":"Financial Reporting Council of Nigeria (FRC)"}],[{"text":"Issued the Nigerian Code of Corporate Governance 2018; regulates financial reporting and governance"}]],[[{"text":"Corporate Affairs Commission (CAC)"}],[{"text":"Registers companies and business names (under CAMA 2020)"}]],[[{"text":"Institute of Chartered Accountants of Nigeria (ICAN)"}],[{"text":"Regulates the accountancy profession"}]]]},{"type":"list","ordered":false,"items":[{"text":[{"text":"NIM's statutory role came from the "},{"text":"2003 Act","bold":true},{"text":", not from CAMA 2020, not from the NCCG 2018 and not from a members' resolution."}]},{"text":[{"text":"Management as a semi-profession:","bold":true},{"text":" in many countries management is called a semi-profession rather than a full profession because of "},{"text":"free (unrestricted) entry into practice, no compulsory licence and no statutory regulation","bold":true},{"text":": anyone can be appointed a manager without a specific required qualification. This is "},{"text":"not","bold":true},{"text":" because management lacks a body of knowledge or formal training. Management "},{"text":"does","bold":true},{"text":" have a systematic body of principles that can be taught, has ethical codes, and many managers receive formal training. So \"management has a systematic body of principles\" is an argument "},{"text":"for","bold":true},{"text":" professional status, not for calling it a semi-profession. In Nigeria the NIM Act gives management a statutory regulator, which is why it is treated as a profession here."}]}]}]},{"number":"5.2","title":"Ethics, the NIM values and efficiency versus effectiveness","mustKnow":[{"type":"paragraph","text":[{"text":"NIM Code of Ethics / Values (7):","bold":true}]},{"type":"list","ordered":true,"start":1,"items":[{"text":[{"text":"Integrity and honesty:","bold":true},{"text":" demonstrate integrity in professional activities."}]},{"text":[{"text":"Transparency:","bold":true},{"text":" openness in dealings."}]},{"text":[{"text":"Fairness:","bold":true},{"text":" be impartial; no favouritism or discrimination."}]},{"text":[{"text":"Accountability:","bold":true},{"text":" the obligation to give accoun$study_guide$);
insert into private.study_guide_chunks (guide, ordinal, chunk) values ('study_guide_bua201', 19, $study_guide$t for a job done or how a responsibility was undertaken."}]},{"text":[{"text":"Responsibility:","bold":true},{"text":" the obligation or duty (moral and legal) to perform a task."}]},{"text":[{"text":"Effectiveness:","bold":true},{"text":" achieving objectives or desired results."}]},{"text":[{"text":"Efficiency:","bold":true},{"text":" accomplishing a task or responsibility with the least resources."}]}]},{"type":"list","ordered":false,"items":[{"text":[{"text":"Responsibility vs accountability:","bold":true},{"text":" responsibility is the duty to "},{"text":"perform","bold":true},{"text":" a task; accountability is the obligation to "},{"text":"give account","bold":true},{"text":" for how it was done."}]},{"text":[{"text":"Ethics and responsibility in managerial practice:","bold":true},{"text":" managers set standards through "},{"text":"integrity, fairness and transparency","bold":true},{"text":", and make decisions that benefit not just themselves and shareholders but also "},{"text":"other stakeholders","bold":true},{"text":", including employees, customers and their operating environment."}]},{"text":[{"text":"Ethical theories (decision rules):","bold":true}]}]},{"type":"table","header":[[{"text":"Theory"}],[{"text":"Rule"}]],"rows":[[[{"text":"Utilitarianism"}],[{"text":"The greatest good for the greatest number"}]],[[{"text":"Deontology (duty/rights)"}],[{"text":"Follow moral duties and rules whatever the outcome"}]],[[{"text":"Ethical egoism"}],[{"text":"Act in your own self-interest"}]],[[{"text":"Virtue ethics"}],[{"text":"Act as a person of good character would"}]]]},{"type":"list","ordered":false,"items":[{"text":[{"text":"Ethical compliance:","bold":true},{"text":" obeying laws, regulations and rules; it is "},{"text":"driven by laws and rules","bold":true},{"text":". Ethics in general is wider and includes voluntary moral choices beyond what the law requires."}]}]}],"explainMore":[{"type":"list","ordered":false,"items":[{"text":[{"text":"Not NIM values:","bold":true},{"text":" favouritism, secrecy, profit maximisation at all costs."}]},{"text":[{"text":"Applying the values:","bold":true}],"blocks":[{"type":"list","ordered":false,"items":[{"text":[{"text":"A procurement officer awards a ₦12 million contract to his cousin's company although a qualified bidder quoted less: "},{"text":"fairness","bold":true},{"text":" is violated (favouritism)."}]},{"text":[{"text":"An agency publishes every bidder, bid price and winning bid online: "},{"text":"transparency","bold":true},{"text":"."}]},{"text":[{"text":"Manipulating reports to protect management's image is a breach of "},{"text":"integrity and honesty","bold":true},{"text":". Refusing work beyond your competence, declining gifts from clients and updating your skills are all "},{"text":"ethical","bold":true},{"text":" behaviour."}]}]}]},{"text":[{"text":"Worked example (efficiency vs effectiveness).","bold":true},{"text":" Two Lagos bakeries each plan and produce 2,000 loaves a day of the same quality. Bakery A spends ₦180,000 on inputs daily; Bakery B spends ₦240,000."}],"blocks":[{"type":"list","ordered":false,"items":[{"text":[{"text":"Step 1, effectiveness: both reach the planned 2,000 loaves, so they are "},{"text":"equally effective","bold":true},{"text":"."}]},{"text":[{"text":"Step 2, cost per loaf: A = ₦180,000 ÷ 2,000 = "},{"text":"₦90","bold":true},{"text":"; B = ₦240,000 ÷ 2,000 = "},{"text":"₦120","bold":true},{"text":"."}]},{"text":[{"text":"Step 3, daily saving: ₦240,000 − ₦180,000 = "},{"text":"₦60,000","bold":true},{"text":", which is ₦60,000 ÷ ₦240,000 × 100 = "},{"text":"25%","bold":true},{"text":" less than B."}]},{"text":[{"text":"Conclusion: A is "},{"text":"equally effective but more efficient","bold":true},{"text":". Efficiency is about resources used (inputs per output); effectiveness is about hitting the objective."}]}]}]},{"text":[{"text":"Trap:","bold":true},{"text":" \"treating staff impartially\" is fairness, and \"reporting results to the board\" is accountability; neither is effectiveness."}]}]}]},{"number":"5.3","title":"Corporate governance: meaning, principles and theories","mustKnow":[{"type":"list","ordered":false,"items":[{"text":[{"text":"Corporate governance (CG):","bold":true},{"text":" a system or framework of policies/guidelines by which organisations are "},{"text":"directed and controlled","bold":true},{"text":" ("},{"text":"Cadbury Report, 1992","bold":true},{"text":")."}]},{"text":[{"text":"Key principles of CG (4):","bold":true},{"text":" "},{"text":"responsibility, accountability, transparency, fairness","bold":true},{"text":" (meanings as in Lesson 5.2). Secrecy is "},{"text":"not","bold":true},{"text":" a principle."}]},{"text":[{"text":"Why CG matters:","bold":true},{"text":" it protects the interests of shareholders and other stakeholders and builds investor trust. It does "},{"text":"not","bold":true},{"text":" guarantee profit, give managers unlimited power or remove the need for external audit."}]},{"text":[{"text":"Agency theory (Jensen and Meckling, 1976):","bold":true},{"text":" shareholders ("},{"text":"principals","bold":true},{"text":") hire managers ("},{"text":"agents","bold":true},{"text":"). "},{"text":"Agency costs","bold":true},{"text":" arise from the "},{"text":"divergence of interests between owners and managers","bold":true},{"text":" (e.g. managers chasing perks or short-term bonuses), plus the cost of monitoring them. A major objective of CG is to "},{"text":"resolve conflicts between owners and managers","bold":true},{"text":"."}]},{"text":[{"text":"Stakeholder theory (R. Edward Freeman, 1984):","bold":true},{"text":" a firm should serve all groups affected by it (employees, customers, suppliers, community, government), not only shareholders. "},{"text":"CSR aligns most closely with stakeholder theory.","bold":true}]},{"text":[{"text":"Shareholder primacy / classical profit doctrine (Milton Friedman):","bold":true},{"text":" the firm's main social respo$study_guide$);
insert into private.study_guide_chunks (guide, ordinal, chunk) values ('study_guide_bua201', 20, $study_guide$nsibility is to maximise profit for shareholders within the law."}]}]}],"explainMore":[{"type":"list","ordered":false,"items":[{"text":[{"text":"Board of directors:","bold":true},{"text":" executive directors run the business day to day; "},{"text":"non-executive directors","bold":true},{"text":" do not. An "},{"text":"independent non-executive director (INED)","bold":true},{"text":" has no material ties to management or major shareholders, so INEDs mainly enhance "},{"text":"monitoring effectiveness","bold":true},{"text":": they strengthen accountability and oversight of management. They do not raise executive power or production output."}]},{"text":[{"text":"Internal audit","bold":true},{"text":" checks that controls work and records are reliable, so it strengthens "},{"text":"operational control","bold":true},{"text":"."}]},{"text":[{"text":"Social responsibility (sustainability) reporting","bold":true},{"text":" discloses a firm's social and environmental impact, so it improves "},{"text":"transparency","bold":true},{"text":"."}]},{"text":[{"text":"Governance failure","bold":true},{"text":" often results in "},{"text":"financial misreporting","bold":true},{"text":", fraud and loss of stakeholder confidence; "},{"text":"corporate failure is often linked to weak corporate governance","bold":true},{"text":". High CSR, stakeholder engagement and ethical leadership reduce, not cause, failure."}]},{"text":[{"text":"Stakeholder capitalism:","bold":true},{"text":" when managers sacrifice some short-term profit to build long-term trust with employees, customers and the community. It is the opposite of shareholder primacy."}]},{"text":[{"text":"Stakeholder mapping","bold":true},{"text":" (e.g. "},{"text":"Mendelow's power–interest matrix","bold":true},{"text":") classifies stakeholders by their "},{"text":"power or influence","bold":true},{"text":" and their "},{"text":"interest","bold":true},{"text":" in the organisation:"}]}]},{"type":"table","header":[[],[{"text":"Low interest"}],[{"text":"High interest"}]],"rows":[[[{"text":"High power"}],[{"text":"Keep satisfied"}],[{"text":"Manage closely (key players)"}]],[[{"text":"Low power"}],[{"text":"Monitor (minimum effort)"}],[{"text":"Keep informed"}]]]}]},{"number":"5.4","title":"Governance in Nigeria: the NCCG 2018","mustKnow":[{"type":"list","ordered":false,"items":[{"text":[{"text":"Nigerian Code of Corporate Governance (NCCG) 2018:","bold":true},{"text":" states the standard of principles and practices for corporate governance in Nigerian "},{"text":"public and private organisations","bold":true},{"text":"."}]},{"text":[{"text":"Issued by:","bold":true},{"text":" the "},{"text":"Financial Reporting Council of Nigeria (FRC)","bold":true},{"text":" (unveiled in January 2019)."}]},{"text":[{"text":"Aim:","bold":true},{"text":" to promote "},{"text":"transparency, integrity and public trust","bold":true},{"text":"."}]},{"text":[{"text":"Content:","bold":true},{"text":" requirements for "},{"text":"board structure, board and committee meetings, and disclosure reports","bold":true},{"text":"."}]},{"text":[{"text":"Number of principles:","bold":true},{"text":" "},{"text":"28","bold":true},{"text":"."}]},{"text":[{"text":"Compliance approach:","bold":true},{"text":" "},{"text":"\"Apply and explain\"","bold":true},{"text":": companies apply the principles in a way that suits their size and business, and explain how they have done so. (The older \"comply or explain\" approach is "},{"text":"not","bold":true},{"text":" the NCCG 2018 approach.)"}]}]},{"type":"paragraph","text":[{"text":"Key NCCG 2018 requirements:","bold":true}]},{"type":"list","ordered":true,"start":1,"items":[{"text":[{"text":"The "},{"text":"Chairman","bold":true},{"text":" and the "},{"text":"MD/CEO","bold":true},{"text":" roles are "},{"text":"separate","bold":true},{"text":" and held by "},{"text":"different persons","bold":true},{"text":"; the Chairman should be a non-executive director."}]},{"text":[{"text":"The board includes "},{"text":"independent non-executive directors","bold":true},{"text":", to strengthen accountability and oversight of management."}]},{"text":[{"text":"The board meets "},{"text":"at least once every quarter","bold":true},{"text":" (at least four times a year)."}]},{"text":[{"text":"The board evaluates itself every year, and an "},{"text":"independent external consultant","bold":true},{"text":" evaluates it "},{"text":"at least once every three years","bold":true},{"text":"."}]},{"text":[{"text":"A "},{"text":"whistleblowing framework","bold":true},{"text":" lets staff and others report unethical conduct confidentially and without suffering harm."}]},{"text":[{"text":"Board committees (e.g. audit, risk, remuneration, nomination and governance), sustainability policies and disclosure in the annual report."}]}]}],"explainMore":[{"type":"list","ordered":false,"items":[{"text":[{"text":"The 28 principles are grouped under themes: the board of directors and officers of the board, assurance (audit and risk), relationship with shareholders, business conduct and ethics, sustainability, and transparency."}]},{"text":[{"text":"Trap on counts:","bold":true},{"text":" 4 = the key principles of CG in general; "},{"text":"28","bold":true},{"text":" = the principles in the NCCG 2018."}]},{"text":[{"text":"Trap on bodies:","bold":true},{"text":" the NCCG was issued by the "},{"text":"FRC","bold":true},{"text":", not the CAC (company registration), NIM (management profession) or CBN (banking regulator)."}]},{"text":[{"text":"A proposal for one person to be both Chairman and MD/CEO of a Nigerian plc is "},{"text":"inconsistent with the Code","bold":true},{"text":"; separation stops one person from dominating the board and supervising himself."}]},{"text":[{"text":"The NCCG does not fix prices, register companies, set exchange rates, the minimum wage or tax rates."}]}]}]},{"number":"5.5","title":"Leadership theories","mustKnow":[{"type":"list","ordered":false,"items":[{"te$study_guide$);
insert into private.study_guide_chunks (guide, ordinal, chunk) values ('study_guide_bua201', 21, $study_guide$xt":[{"text":"Leadership:","bold":true},{"text":" the process in which an individual "},{"text":"influences","bold":true},{"text":" other group members towards the attainment of group or organisational goals. Leadership theories explain "},{"text":"how and why people lead","bold":true},{"text":"."}]}]},{"type":"paragraph","text":[{"text":"Leadership theories (7):","bold":true}]},{"type":"list","ordered":true,"start":1,"items":[{"text":[{"text":"Great Man / Trait theories:","bold":true},{"text":" people are "},{"text":"born","bold":true},{"text":" with innate abilities such as intelligence, charisma and courage that predispose them to leadership; the fate of organisations and societies depends on them. \"Leaders are born, not made.\""}]},{"text":[{"text":"Behavioural theories:","bold":true},{"text":" focus on "},{"text":"what leaders do","bold":true},{"text":" instead of what they are (e.g. "},{"text":"task-oriented","bold":true},{"text":" or "},{"text":"people-oriented","bold":true},{"text":"), which determines leadership success."}]},{"text":[{"text":"Contingency/Situational theories:","bold":true},{"text":" the "},{"text":"situation","bold":true},{"text":" should determine the leadership approach. People become leaders not only because of personality but also because of situational factors and the interaction between leaders and group members. "},{"text":"No single style is effective in every situation.","bold":true}]},{"text":[{"text":"Transformational/Inspirational theories:","bold":true},{"text":" leaders "},{"text":"inspire","bold":true},{"text":" and motivate followers to achieve "},{"text":"more than the expected result","bold":true},{"text":", e.g. "},{"text":"charismatic","bold":true},{"text":" leadership."}]},{"text":[{"text":"Participative/Democratic theories:","bold":true},{"text":" "},{"text":"involving followers in decision making","bold":true},{"text":" promotes consensus and commitment."}]},{"text":[{"text":"Transactional theories:","bold":true},{"text":" using "},{"text":"rewards and punishments","bold":true},{"text":" to motivate followers."}]},{"text":[{"text":"Servant leadership:","bold":true},{"text":" focus on "},{"text":"empowering and supporting","bold":true},{"text":" group members rather than exercising authority, by showing "},{"text":"empathy, listening","bold":true},{"text":" and commitment to their personal and professional development."}]}]}],"explainMore":[{"type":"list","ordered":false,"items":[{"text":[{"text":"Scholars:","bold":true},{"text":" Great Man idea is linked with Thomas Carlyle; behavioural research includes the "},{"text":"Ohio State","bold":true},{"text":" studies (initiating structure vs consideration), the "},{"text":"Michigan","bold":true},{"text":" studies (job-centred vs employee-centred), "},{"text":"Blake and Mouton's Managerial Grid","bold":true},{"text":", and "},{"text":"Kurt Lewin's","bold":true},{"text":" styles (autocratic, democratic, laissez-faire); contingency models include "},{"text":"Fiedler's","bold":true},{"text":" contingency model and "},{"text":"Hersey and Blanchard's situational leadership","bold":true},{"text":"; transformational leadership comes from "},{"text":"James MacGregor Burns","bold":true},{"text":" (1978), developed by "},{"text":"Bernard Bass","bold":true},{"text":"; servant leadership from "},{"text":"Robert Greenleaf","bold":true},{"text":" (1970)."}]},{"text":[{"text":"Hersey and Blanchard:","bold":true},{"text":" a leader who changes style according to the "},{"text":"maturity (readiness)","bold":true},{"text":" of followers is applying "},{"text":"situational leadership theory","bold":true},{"text":" (telling, selling, participating, delegating)."}]},{"text":[{"text":"Styles:","bold":true},{"text":" an "},{"text":"autocratic","bold":true},{"text":" style (leader decides alone) can work best when "},{"text":"urgent decisions are needed in a crisis","bold":true},{"text":"; it suits creativity, high-morale or decentralised settings poorly. "},{"text":"Laissez-faire","bold":true},{"text":" leaves decisions to the group."}]},{"text":[{"text":"Transformational vs transactional:","bold":true},{"text":" transformational inspires with a vision to achieve "},{"text":"more than expected","bold":true},{"text":"; transactional exchanges rewards and punishments for performance and relies on routine supervision."}]},{"text":[{"text":"Apply the theories:","bold":true}],"blocks":[{"type":"list","ordered":false,"items":[{"text":[{"text":"A Kano sales manager pays a ₦50,000 bonus to every officer who meets the monthly target and issues a query to those who fall short: "},{"text":"transactional","bold":true},{"text":"."}]},{"text":[{"text":"A Port Harcourt plant manager lets workers discuss and vote on three shift options before changing the schedule: "},{"text":"participative (democratic)","bold":true},{"text":"."}]},{"text":[{"text":"An Ibadan branch manager is directive during a cash-system failure but consults staff freely at normal times, saying \"the right style depends on the circumstances\": "},{"text":"contingency/situational","bold":true},{"text":"."}]},{"text":[{"text":"A board member who says \"great leaders are born, not made\": "},{"text":"Great Man/Trait","bold":true},{"text":"."}]}]}]},{"text":[{"text":"Not a leadership theory:","bold":true},{"text":" comparative advantage (an international trade theory)."}]}]}]},{"number":"5.6","title":"Leadership ethics and responsible leadership","mustKnow":[{"type":"list","ordered":false,"items":[{"text":[{"text":"Leadership ethics:","bold":true},{"text":" leaders guide people with the principles of "},{"text":"honesty, fairness, respect and accountability","bold":true},{"text":" in pursuing organisational or group goals. The interest of "},{"text":"all stakeholders","bold":true},{"text":" is considered instead of profit alone."}]},{"text":[{"text":"Responsible leadership:","bold":true},{"text":" pays attention to "},{"text":"ethics, sustainability and accountabilit$study_guide$);
insert into private.study_guide_chunks (guide, ordinal, chunk) values ('study_guide_bua201', 22, $study_guide$y","bold":true},{"text":", and considers the interests of "},{"text":"employees, customers, shareholders and the wider society","bold":true},{"text":". Responsible leaders "},{"text":"promote organisational effectiveness","bold":true},{"text":"."}]}]}],"explainMore":[{"type":"list","ordered":false,"items":[{"text":[{"text":"Leadership ethics most directly influence "},{"text":"organisational trust","bold":true},{"text":"; ethical leadership mainly enhances an organisation's "},{"text":"reputation","bold":true},{"text":". They do not directly move interest rates, inflation or the exchange rate."}]},{"text":[{"text":"Unethical leadership (secret decisions, rewarding friends and relatives, profit at any cost) breaks trust and is a common route to governance failure."}]},{"text":[{"text":"Responsible leadership links all of this topic: professional ethics (NIM values), good governance (NCCG 2018) and a stakeholder view of the firm."}]}]}]}],"recap":[{"type":"list","ordered":false,"items":[{"text":[{"text":"Profession = regular work or occupation; 6 characteristics: training, skills, licence/certification, ethics, code of conduct, standards (e.g. ISO 9000)."}]},{"text":[{"text":"Management is a profession in Nigeria: education, training, skills, ethical codes and a statutory regulator, "},{"text":"NIM (Act No. 14 of 2003)","bold":true},{"text":"; elsewhere it is often called a semi-profession because entry is free and no licence is compulsory."}]},{"text":[{"text":"NIM values (7): integrity and honesty, transparency, fairness, accountability, responsibility, effectiveness, efficiency."}]},{"text":[{"text":"Effectiveness = achieving objectives; efficiency = least resources."}]},{"text":[{"text":"CG = system by which organisations are directed and controlled (Cadbury, 1992); 4 principles: responsibility, accountability, transparency, fairness."}]},{"text":[{"text":"Agency costs come from owner–manager divergence; CSR fits stakeholder theory."}]},{"text":[{"text":"NCCG 2018: issued by FRC; 28 principles; \"apply and explain\"; separate Chairman and MD/CEO; quarterly board meetings; external evaluation every 3 years; whistleblowing."}]},{"text":[{"text":"7 leadership theories: trait, behavioural, contingency/situational, transformational, participative, transactional, servant."}]},{"text":[{"text":"Leadership ethics: honesty, fairness, respect, accountability for all stakeholders; responsible leadership promotes organisational effectiveness."}]}]}],"theory":{"itemId":"f268cb36-00ba-5e5c-80f4-3b60654125fd","question":[{"type":"paragraph","text":[{"text":"Two Abuja water factories each plan and produce 500 cartons of the same quality a day. Factory X spends ₦400,000 on inputs and Factory Y spends ₦500,000. Compare their effectiveness and efficiency."}]}]},"practice":[{"topic":"Corporate Governance, Leadership and Management as a Profession","named":false}]}},{"kind":"note","itemId":"c688a824-78c6-5651-81e5-faec38099696","sourceKey":"guide-topic:6","position":6,"payload":{"title":"Case Studies of Successful Managers","body":"The career path, key dates, leadership style, big decisions and lessons of six Nigerian managers (Dangote, Awosika, Otedola, Maduka, Elumelu, Wigwe) and five global managers (Welch, Nooyi, Nadella, Musk, Polman); the Igbo apprenticeship system; the core management lessons they share.","noteType":"guide_topic","number":6,"mustKnow":[{"text":"The career path, key dates, leadership style, big decisions and lessons of six Nigerian managers (Dangote, Awosika, Otedola, Maduka, Elumelu, Wigwe) and five global managers (Welch, Nooyi, Nadella, Musk, Polman); the Igbo apprenticeship system; the core management lessons they share."}],"lessons":[{"number":"6.1","title":"Aliko Dangote and Femi Otedola: industry and energy","mustKnow":[{"type":"paragraph","text":[{"text":"Aliko Dangote","bold":true}]},{"type":"list","ordered":false,"items":[{"text":[{"text":"Born "},{"text":"1957","bold":true},{"text":" in "},{"text":"Kano State","bold":true},{"text":". Studied business at "},{"text":"Al-Azhar University, Cairo","bold":true},{"text":"."}]},{"text":[{"text":"1977:","bold":true},{"text":" started a "},{"text":"small commodity-trading business with a loan from his uncle","bold":true},{"text":" (a relative). This grew into the "},{"text":"Dangote Group","bold":true},{"text":"."}]},{"text":[{"text":"Strategy: import substitution.","bold":true},{"text":" He moved from "},{"text":"importing","bold":true},{"text":" cement and sugar to "},{"text":"producing them in Nigeria","bold":true},{"text":"."}]},{"text":[{"text":"Built "},{"text":"Dangote Cement","bold":true},{"text":" into "},{"text":"Africa's largest cement producer","bold":true},{"text":"."}]},{"text":[{"text":"Dangote Refinery:","bold":true},{"text":" commissioned in "},{"text":"2023","bold":true},{"text":" at Lekki, "},{"text":"Lagos","bold":true},{"text":", with a designed capacity of 650,000 barrels a day, Africa's largest refinery. Purpose: to "},{"text":"reduce Nigeria's dependence on imported fuel","bold":true},{"text":"."}]},{"text":[{"text":"Impact:","bold":true},{"text":" major contributor to GDP, job creation and industrialisation."}]}]},{"type":"paragraph","text":[{"text":"Femi Otedola","bold":true}]},{"type":"list","ordered":false,"items":[{"text":[{"text":"Born "},{"text":"1962","bold":true},{"text":"."}]},{"text":[{"text":"2003:","bold":true},{"text":" founded "},{"text":"Zenon Petroleum and Gas","bold":true},{"text":", mainly in "},{"text":"fuel marketing and distribution, especially diesel","bold":true},{"text":"."}]},{"text":[{"text":"2007:","bold":true},{"text":" became chairman of "},{"text":"African Petroleum","bold":true},{"text":"; in "},{"text":"2010","bold":true},{"text":" renamed it "},{"text":"Forte Oil Plc","bold":true},{"text":" and built it into a major energy company."}]},{"text":[{"text":"2019:","bold":true},{"text":" sold his stake in Forte Oil and concentrated on "},{"text":"electricity generation","bold":tru$study_guide$);
insert into private.study_guide_chunks (guide, ordinal, chunk) values ('study_guide_bua201', 23, $study_guide$e},{"text":" through "},{"text":"Geregu Power Plc","bold":true},{"text":": a "},{"text":"strategic divestment into power generation","bold":true},{"text":"."}]},{"text":[{"text":"Since "},{"text":"January 2024","bold":true},{"text":": chairman of "},{"text":"First HoldCo","bold":true},{"text":" (formerly FBN Holdings), the parent of First Bank."}]}]}],"explainMore":[{"type":"list","ordered":false,"items":[{"text":[{"text":"Import substitution","bold":true},{"text":" means making at home what a country used to import. It saves foreign exchange, creates jobs and builds local value. Dangote reinforced it with "},{"text":"backward integration","bold":true},{"text":" (owning the supply of his own inputs, e.g. limestone quarries for cement)."}]},{"text":[{"text":"Decision pattern (Dangote):","bold":true},{"text":" big, long-term bets on basic goods Nigeria imports (cement, sugar, salt, fertiliser, refined fuel), with heavy capital and scale."}]},{"text":[{"text":"Divestment","bold":true},{"text":" means selling a business or stake to free capital for a better opportunity. Otedola sold Forte Oil to move into power; he is known for capital-market efficiency and restructuring. In "},{"text":"December 2025","bold":true},{"text":" he sold his controlling interest in Geregu Power and stepped down as its chairman, and he has since kept increasing his stake in First HoldCo. Geregu Power still operates in "},{"text":"electricity generation","bold":true},{"text":"."}]},{"text":[{"text":"Lesson:","bold":true},{"text":" spot where a market is moving and reposition capital before others do."}]}]}]},{"number":"6.2","title":"Cosmas Maduka and the Igbo apprenticeship system","mustKnow":[{"type":"paragraph","text":[{"text":"Cosmas Maduka","bold":true}]},{"type":"list","ordered":false,"items":[{"text":[{"text":"Born "},{"text":"1958","bold":true},{"text":"; from Nnewi, Anambra State. Founder and chairman of the "},{"text":"Coscharis Group","bold":true},{"text":"."}]},{"text":[{"text":"Lost his father as a small child, left primary school and hawked akara to support his mother."}]},{"text":[{"text":"Learned business through the "},{"text":"Igbo apprenticeship system","bold":true},{"text":", as an apprentice in his uncle's motor-parts business."}]},{"text":[{"text":"1977:","bold":true},{"text":" started Coscharis as a dealer in "},{"text":"automobile spare parts","bold":true},{"text":"; expanded into vehicle sales, assembly and other sectors."}]},{"text":[{"text":"Name:","bold":true},{"text":" "},{"text":"Cos","bold":true},{"text":"mas + "},{"text":"Charis","bold":true},{"text":" from his wife "},{"text":"Charity","bold":true},{"text":": the founder's first name and his wife's name."}]},{"text":[{"text":"2015:","bold":true},{"text":" Coscharis Motors became the "},{"text":"sole distributor of BMW","bold":true},{"text":" in Nigeria."}]},{"text":[{"text":"Style:","bold":true},{"text":" "},{"text":"faith-driven and discipline-oriented","bold":true},{"text":". Impact: youth mentorship and automotive-sector development."}]}]},{"type":"paragraph","text":[{"text":"Igbo apprenticeship system (Igba Boi)","bold":true}]},{"type":"list","ordered":false,"items":[{"text":[{"text":"A "},{"text":"traditional, mentorship-based business incubation system","bold":true},{"text":"."}]}]},{"type":"list","ordered":true,"start":1,"items":[{"text":[{"text":"The apprentice trains "},{"text":"5 to 7 years","bold":true},{"text":" under a "},{"text":"master trader","bold":true},{"text":"."}]},{"text":[{"text":"Post-training settlement capital","bold":true},{"text":" is provided to start the apprentice's own business."}]},{"text":[{"text":"Agreements are "},{"text":"trust-based and community-enforced","bold":true},{"text":" (not written contracts filed in court)."}]},{"text":[{"text":"A major contributor to "},{"text":"SME dominance in South-East Nigeria","bold":true},{"text":"."}]},{"text":[{"text":"Recognised as one of "},{"text":"Africa's largest informal venture systems","bold":true},{"text":"."}]}]}],"explainMore":[{"type":"list","ordered":false,"items":[{"text":[{"text":"Igba Boi works like a "},{"text":"business school plus venture fund","bold":true},{"text":": the apprentice learns by doing (stock, pricing, customers, suppliers) and is then \"settled\", so the master creates a future business partner, not a rival with nothing."}]},{"text":[{"text":"Trap: settlement capital comes "},{"text":"after","bold":true},{"text":" training; the period is years (5 to 7), not months, and it is not a graduate trainee scheme or Six Sigma."}]},{"text":[{"text":"Lesson:","bold":true},{"text":" mentorship and succession build lasting enterprise; credibility and discipline are capital."}]}]}]},{"number":"6.3","title":"Ibukun Awosika, Tony Elumelu and Herbert Wigwe: governance, finance and Africapitalism","mustKnow":[{"type":"paragraph","text":[{"text":"Ibukun Awosika","bold":true}]},{"type":"list","ordered":false,"items":[{"text":[{"text":"Born "},{"text":"1962","bold":true},{"text":"; Chemistry graduate of the University of Ife (now Obafemi Awolowo University)."}]},{"text":[{"text":"Founder of "},{"text":"The Chair Centre Group","bold":true},{"text":", a "},{"text":"furniture manufacturing","bold":true},{"text":" business: she built a manufacturing brand in a "},{"text":"male-dominated industry","bold":true},{"text":"."}]},{"text":[{"text":"2015:","bold":true},{"text":" became the "},{"text":"first woman to chair First Bank of Nigeria","bold":true},{"text":" (served until 2021)."}]},{"text":[{"text":"Strong advocate of "},{"text":"corporate governance and ethical leadership","bold":true},{"text":"; promotes "},{"text":"women entrepreneurship and SME development","bold":true},{"text":". Impact: inclusive leadership and institutional reform."}]}]},{"type":"paragraph","text":[{"text":"Tony Elumelu","bold":true}]},{"type":"list","ordered":false,"items":[{"text":[{"text":"Born "},{"text":"1963","bold":true},{"text":". Led investors who took over Crystal Ban$study_guide$);
insert into private.study_guide_chunks (guide, ordinal, chunk) values ('study_guide_bua201', 24, $study_guide$k in "},{"text":"1997","bold":true},{"text":" and renamed it "},{"text":"Standard Trust Bank","bold":true},{"text":", which "},{"text":"merged with United Bank for Africa (UBA) in 2005","bold":true},{"text":"."}]},{"text":[{"text":"2010:","bold":true},{"text":" founded both "},{"text":"Heirs Holdings","bold":true},{"text":" (investment company) and "},{"text":"The Tony Elumelu Foundation","bold":true},{"text":"."}]},{"text":[{"text":"2015:","bold":true},{"text":" committed "},{"text":"100 million US dollars","bold":true},{"text":" to the Tony Elumelu Foundation Entrepreneurship Programme to "},{"text":"train, fund and mentor 10,000 African entrepreneurs over 10 years","bold":true},{"text":"."}]},{"text":[{"text":"Africapitalism:","bold":true},{"text":" the philosophy that "},{"text":"Africa's private sector can transform the continent through long-term investment that creates both economic prosperity and social wealth","bold":true},{"text":"."}]},{"text":[{"text":"Invested heavily in banking, power and hospitality (Transcorp). Chairman of Heirs Holdings and Transcorp; chaired UBA from 2014 until "},{"text":"August 2026","bold":true},{"text":", when he retired at the maximum tenure."}]}]},{"type":"paragraph","text":[{"text":"Herbert Wigwe","bold":true}]},{"type":"list","ordered":false,"items":[{"text":[{"text":"With his partner "},{"text":"Aigboje Aig-Imoukhuede","bold":true},{"text":", acquired "},{"text":"Access Bank in 2002","bold":true},{"text":" and grew it into a "},{"text":"multinational institution","bold":true},{"text":"."}]},{"text":[{"text":"Group Managing Director/CEO of Access Bank from 2014, then Group CEO of Access Holdings."}]},{"text":[{"text":"Led the "},{"text":"merger with Diamond Bank","bold":true},{"text":" (completed 2019), making Access "},{"text":"Nigeria's largest bank","bold":true},{"text":": a contribution to "},{"text":"banking consolidation and corporate expansion","bold":true},{"text":"."}]},{"text":[{"text":"Strong focus on "},{"text":"risk management","bold":true},{"text":"; invested in "},{"text":"education and leadership development","bold":true},{"text":", including founding "},{"text":"Wigwe University in Isiokpo, Rivers State","bold":true},{"text":"."}]},{"text":[{"text":"Died in February 2024","bold":true},{"text":" in a helicopter crash in California, USA."}]}]}],"explainMore":[{"type":"list","ordered":false,"items":[{"text":[{"text":"Awosika's lesson:","bold":true},{"text":" gender is no barrier to building a manufacturing firm or chairing a top bank; governance and ethics are her signature. A young woman building a manufacturing brand in a male-dominated industry while championing governance would model her career, not Welch's or Otedola's."}]},{"text":[{"text":"Elumelu's decision pattern:","bold":true},{"text":" buy a small or struggling bank, turn it round, then grow by merger (STB with UBA); later, use wealth to fund entrepreneurs, which is Africapitalism in practice. Do not confuse Africapitalism with Polman's \"responsible capitalism\" or Nooyi's \"Performance with Purpose\"."}]},{"text":[{"text":"Wigwe's decision pattern:","bold":true},{"text":" growth by acquisition and merger, backed by strict risk management; his legacy includes a university to develop future leaders."}]}]}]},{"number":"6.4","title":"Jack Welch, Indra Nooyi, Satya Nadella, Elon Musk and Paul Polman","mustKnow":[{"type":"paragraph","text":[{"text":"Jack Welch (General Electric)","bold":true}]},{"type":"list","ordered":false,"items":[{"text":[{"text":"Chairman and CEO of GE, 1981 to 2001.","bold":true}]},{"text":[{"text":"Introduced "},{"text":"Six Sigma","bold":true},{"text":" (quality improvement) in the "},{"text":"mid-1990s","bold":true},{"text":"."}]},{"text":[{"text":"Performance-based ranking (\"rank and yank\", vitality curve):","bold":true},{"text":" each year reward the "},{"text":"top 20%","bold":true},{"text":" of managers (bonuses, stock options), develop the "},{"text":"middle 70%","bold":true},{"text":", dismiss the "},{"text":"bottom 10%","bold":true},{"text":"."}]},{"text":[{"text":"\"Number one or number two\":","bold":true},{"text":" every GE business should be No. 1 or No. 2 in its industry, or be fixed, sold or closed."}]},{"text":[{"text":"Focus: "},{"text":"efficiency and restructuring","bold":true},{"text":". Impact: modern performance-management systems."}]}]},{"type":"paragraph","text":[{"text":"Indra Nooyi (PepsiCo)","bold":true}]},{"type":"list","ordered":false,"items":[{"text":[{"text":"CEO of PepsiCo, 2006 to 2018.","bold":true}]},{"text":[{"text":"\"Performance with Purpose\":","bold":true},{"text":" long-term growth while having a positive impact on society and the environment."}]},{"text":[{"text":"Grouped products into "},{"text":"\"fun for you\", \"better for you\" and \"good for you\"","bold":true},{"text":" and grew the healthier ones: a "},{"text":"shift toward healthier product diversification","bold":true},{"text":"."}]},{"text":[{"text":"Focus: sustainability and environmental responsibility."}]}]},{"type":"paragraph","text":[{"text":"Satya Nadella (Microsoft)","bold":true}]},{"type":"list","ordered":false,"items":[{"text":[{"text":"CEO of Microsoft since February 2014","bold":true},{"text":", succeeding "},{"text":"Steve Ballmer","bold":true},{"text":"; also chairman since 2021."}]},{"text":[{"text":"Transformed Microsoft into a "},{"text":"cloud-first","bold":true},{"text":" company; focus on AI and sustainable technology."}]},{"text":[{"text":"Growth-mindset, empathetic leadership:","bold":true},{"text":" changed a \"know-it-all\" culture into a \"learn-it-all\" culture. Wrote "},{"text":"Hit Refresh","italic":true},{"text":" (2017)."}]}]},{"type":"paragraph","text":[{"text":"Elon Musk (Tesla and SpaceX)","bold":true}]},{"type":"list","ordered":false,"items":[{"text":[{"text":"Founded "},{"text":"SpaceX in 2002","bold":true},{"text":"; became "},{"text":"CEO of Tesla in 2008","bold":true},{"text":"."}]},{"text":[{"text":"High-risk$study_guide$);
insert into private.study_guide_chunks (guide, ordinal, chunk) values ('study_guide_bua201', 25, $study_guide$, innovation-driven","bold":true},{"text":" leadership; revolutionised electric vehicles and private space travel; major driver of the renewable-energy transition. Impact: accelerated EV adoption and technology disruption."}]}]},{"type":"paragraph","text":[{"text":"Paul Polman (Unilever)","bold":true}]},{"type":"list","ordered":false,"items":[{"text":[{"text":"CEO of Unilever, 2009 to 2019.","bold":true}]},{"text":[{"text":"2010:","bold":true},{"text":" launched the "},{"text":"Unilever Sustainable Living Plan","bold":true},{"text":", which aimed among other things to "},{"text":"halve the environmental footprint","bold":true},{"text":" of Unilever's products."}]},{"text":[{"text":"Stopped giving quarterly earnings guidance","bold":true},{"text":" to investors, arguing that quarterly targets push managers into short-term decisions."}]},{"text":[{"text":"Integrated sustainability into core strategy; promoted "},{"text":"responsible capitalism","bold":true},{"text":". Impact: a global benchmark for corporate sustainability."}]}]}],"explainMore":[{"type":"list","ordered":false,"items":[{"text":[{"text":"Matching traps:","bold":true},{"text":" Six Sigma, rank and yank, No. 1 or No. 2 = "},{"text":"Welch","bold":true},{"text":". Performance with Purpose, fun/better/good for you = "},{"text":"Nooyi","bold":true},{"text":". Cloud-first, growth mindset, "},{"text":"Hit Refresh","italic":true},{"text":", succeeded Ballmer = "},{"text":"Nadella","bold":true},{"text":". High-risk innovation, SpaceX and Tesla = "},{"text":"Musk","bold":true},{"text":". Sustainable Living Plan, no quarterly guidance, responsible capitalism = "},{"text":"Polman","bold":true},{"text":"."}]},{"text":[{"text":"Date traps:","bold":true},{"text":" 1981 to 2001 = Welch; 2006 to 2018 = Nooyi; 2009 to 2019 = Polman; 2014 = Nadella became CEO."}]},{"text":[{"text":"Welch versus Nadella","bold":true},{"text":" shows two change styles: Welch drove change through hard targets, ranking and restructuring; Nadella drove it through culture, empathy and learning. A CEO who wants employees to keep learning and experimenting should follow Nadella."}]},{"text":[{"text":"Nooyi and Polman","bold":true},{"text":" both put sustainability at the centre of strategy; Polman also attacked short-termism."}]}]}]},{"number":"6.5","title":"Styles, decisions and core lessons","mustKnow":[{"type":"table","header":[[{"text":"Manager"}],[{"text":"Signature style or decision"}],[{"text":"Main impact"}]],"rows":[[[{"text":"Dangote"}],[{"text":"Import substitution; large-scale manufacturing"}],[{"text":"Industrialisation, jobs, less import dependence"}]],[[{"text":"Awosika"}],[{"text":"Ethical, governance-focused, inclusive"}],[{"text":"Institutional reform, women and SMEs"}]],[[{"text":"Otedola"}],[{"text":"Strategic divestment; restructuring"}],[{"text":"Power generation, investor confidence"}]],[[{"text":"Maduka"}],[{"text":"Faith-driven, discipline-oriented; apprenticeship-trained"}],[{"text":"Automotive sector, youth mentorship"}]],[[{"text":"Elumelu"}],[{"text":"Africapitalism; growth by merger"}],[{"text":"Entrepreneurship-driven empowerment"}]],[[{"text":"Wigwe"}],[{"text":"Acquisition and merger with risk management"}],[{"text":"Banking consolidation, financial-sector growth"}]],[[{"text":"Welch"}],[{"text":"Efficiency, ranking, restructuring, Six Sigma"}],[{"text":"Modern performance management"}]],[[{"text":"Nooyi"}],[{"text":"Performance with Purpose"}],[{"text":"Corporate sustainability model"}]],[[{"text":"Musk"}],[{"text":"High-risk, innovation-driven"}],[{"text":"EV adoption, technology disruption"}]],[[{"text":"Nadella"}],[{"text":"Empathy, growth mindset, cloud-first"}],[{"text":"Revitalised culture, tech leadership"}]],[[{"text":"Polman"}],[{"text":"Responsible capitalism, long-termism"}],[{"text":"Sustainability benchmark"}]]]},{"type":"paragraph","text":[{"text":"Core lessons (6):","bold":true}]},{"type":"list","ordered":true,"start":1,"items":[{"text":[{"text":"Vision and strategic alignment."}]},{"text":[{"text":"Import substitution and local value creation."}]},{"text":[{"text":"Sustainability integrated into core strategy."}]},{"text":[{"text":"Risk management and corporate governance."}]},{"text":[{"text":"Mentorship and succession planning."}]},{"text":[{"text":"Innovation as competitive advantage."}]}]}],"explainMore":[{"type":"list","ordered":false,"items":[{"text":[{"text":"Link each lesson to a person: import substitution (Dangote); sustainability (Nooyi, Polman); risk management and governance (Wigwe, Awosika); mentorship and succession (Maduka and Igba Boi, Elumelu's foundation); innovation (Musk, Nadella); vision (all of them)."}]},{"text":[{"text":"Common career pattern: start small (Dangote's loan, Maduka's spare parts, Elumelu's small bank), reinvest, then grow by scale, merger or new sectors."}]}]}]}],"recap":[{"type":"list","ordered":false,"items":[{"text":[{"text":"Dangote: born 1957, Kano; Al-Azhar; 1977 trading with an uncle's loan; import substitution; Africa's largest cement producer; refinery (2023) to cut fuel imports."}]},{"text":[{"text":"Awosika: The Chair Centre (furniture); 2015 first female chairman of First Bank; governance and ethics."}]},{"text":[{"text":"Otedola: Zenon (2003, diesel); African Petroleum (2007) renamed Forte Oil (2010); sold 2019 for Geregu Power (electricity); First HoldCo chairman since 2024."}]},{"text":[{"text":"Maduka: Igbo apprenticeship; Coscharis (1977, spare parts) = Cosmas + Charity; BMW sole distributor (2015); faith and discipline."}]},{"text":[{"text":"Igba Boi: 5 to 7 years; settlement capital; trust-based, community-enforced."}]},{"text":[{"text":"Elumelu: STB merged with UBA (2005); Heirs Holdings and TEF (2010); 10,000 entrepreneurs over 10 years (2015); Africapitalism."}]},{"text":[{"text":"Wigwe: Access Bank (2002, with Aig-Imoukhuede); Diamond merger; Wigwe University, Isiokpo; died February 2024."}]},{"text":[{"text":"Welch (GE 1981 to 2001): Six Sigma, 20/70/10, No$study_guide$);
insert into private.study_guide_chunks (guide, ordinal, chunk) values ('study_guide_bua201', 26, $study_guide$. 1 or No. 2. Nooyi (PepsiCo 2006 to 2018): Performance with Purpose."}]},{"text":[{"text":"Nadella (2014, after Ballmer): cloud-first, growth mindset. Musk: SpaceX 2002, Tesla CEO 2008, high-risk innovation. Polman (Unilever 2009 to 2019): Sustainable Living Plan, no quarterly guidance."}]}]}],"theory":{"itemId":"808efc6d-172a-5b73-8f22-a8007c6aa9d7","question":[{"type":"paragraph","text":[{"text":"A Lagos firm with 200 managers copies Jack Welch's vitality curve. How many managers fall in each group, and what happens to each?"}]}]},"practice":[{"topic":"Case Studies of Successful Managers","named":false}]}},{"kind":"note","itemId":"31bd3859-2b28-57c9-b6f1-ae351caad842","sourceKey":"guide-topic:7","position":7,"payload":{"title":"The Business Environment","body":"Meaning of the business environment; internal vs external; micro (task) vs macro (general); the six PESTLE factors with Nigerian examples; environmental scanning; SWOT; competitive advantage and flexibility; how Nigeria's environment affects performance.","noteType":"guide_topic","number":7,"mustKnow":[{"text":"Meaning of the business environment; internal vs external; micro (task) vs macro (general); the six PESTLE factors with Nigerian examples; environmental scanning; SWOT; competitive advantage and flexibility; how Nigeria's environment affects performance."}],"lessons":[{"number":"7.1","title":"Meaning of the business environment; internal vs external","mustKnow":[{"type":"list","ordered":false,"items":[{"text":[{"text":"Business environment:","bold":true},{"text":" all the internal and external factors and forces that affect an organisation's operations and performance. It is not only the building, only the customers or only the laws."}]},{"text":[{"text":"Internal environment:","bold":true},{"text":" the factors "},{"text":"within","bold":true},{"text":" the organisation. These are "},{"text":"more within the control","bold":true},{"text":" of the firm's management."}]},{"text":[{"text":"External environment:","bold":true},{"text":" the factors "},{"text":"outside","bold":true},{"text":" the organisation that affect it but over which it has "},{"text":"little or no direct control","bold":true},{"text":". Managers cannot stop them, so they must "},{"text":"anticipate and adapt","bold":true},{"text":" to them."}]}]},{"type":"paragraph","text":[{"text":"Components of the internal environment","bold":true}]},{"type":"list","ordered":true,"start":1,"items":[{"text":[{"text":"Owners","bold":true},{"text":" (shareholders)"}]},{"text":[{"text":"Board of directors","bold":true}]},{"text":[{"text":"Employees","bold":true},{"text":" (their number, skills and morale)"}]},{"text":[{"text":"Organisational (corporate) culture:","bold":true},{"text":" the shared values, beliefs and norms of members"}]},{"text":[{"text":"Physical work environment and resources:","bold":true},{"text":" buildings, machines, equipment, technology in use"}]},{"text":[{"text":"Financial resources","bold":true},{"text":" (capital, cash)"}]},{"text":[{"text":"Management and structure","bold":true},{"text":" (management style, systems, procedures)"}]}]},{"type":"paragraph","text":[{"text":"Components of the external environment:","bold":true},{"text":" the "},{"text":"micro (task)","bold":true},{"text":" environment and the "},{"text":"macro (general)","bold":true},{"text":" environment (Lesson 7.2)."}]},{"type":"table","header":[[{"text":"Point"}],[{"text":"Internal environment"}],[{"text":"External environment"}]],"rows":[[[{"text":"Location"}],[{"text":"Inside the firm"}],[{"text":"Outside the firm"}]],[[{"text":"Control"}],[{"text":"Largely controllable by management"}],[{"text":"Largely uncontrollable"}]],[[{"text":"Examples"}],[{"text":"Culture, employees' skills, board, owners, equipment, finance"}],[{"text":"Customers, suppliers, competitors, inflation, exchange rate, government policy, insecurity"}]],[[{"text":"SWOT link"}],[{"text":"Strengths and weaknesses"}],[{"text":"Opportunities and threats"}]],[[{"text":"Same for all firms?"}],[{"text":"No, unique to each firm"}],[{"text":"Macro part is shared by all firms"}]]]}],"explainMore":[{"type":"list","ordered":false,"items":[{"text":[{"text":"Culture shapes ethics.","bold":true},{"text":" A firm's corporate culture directly influences its "},{"text":"ethical climate","bold":true},{"text":": whether staff feel free to cut corners or to report wrongdoing. It does "},{"text":"not","bold":true},{"text":" influence national interest rates, the exchange rate or inflation; those are external."}]},{"text":[{"text":"Trap:","bold":true},{"text":" \"The skills of the firm's own employees\" is internal, so it is "},{"text":"not","bold":true},{"text":" part of the external environment. The country's exchange rate, the firm's suppliers and its competitors are all external."}]},{"text":[{"text":"Trap:","bold":true},{"text":" The board and the shareholders are "},{"text":"internal","bold":true},{"text":", even though shareholders may live far away. They are part of the organisation itself."}]},{"text":[{"text":"Uncertainty.","bold":true},{"text":" The greatest source of uncertainty is what lies "},{"text":"outside","bold":true},{"text":" management's control, e.g. "},{"text":"political instability","bold":true},{"text":". Internal resources, culture and employee morale can be managed."}]},{"text":[{"text":"Stable vs dynamic.","bold":true},{"text":" A "},{"text":"stable (static)","bold":true},{"text":" environment changes slowly and predictably. A "},{"text":"dynamic","bold":true},{"text":" environment changes "},{"text":"rapidly and unpredictably","bold":true},{"text":". Nigeria's environment is highly dynamic: in 2023 alone, petrol subsidy was removed (May) and the naira exchange-rate windows were unified (June), sharply changing costs for almost every firm. Environments also differ in "},{"text":"complexity","bold":true},{"text":" (how many factors a firm must watch). Dynamic and complex environments create the most u$study_guide$);
insert into private.study_guide_chunks (guide, ordinal, chunk) values ('study_guide_bua201', 27, $study_guide$ncertainty."}]}]}]},{"number":"7.2","title":"Micro (task) and macro (general) environments","mustKnow":[{"type":"list","ordered":false,"items":[{"text":[{"text":"Micro (task) environment:","bold":true},{"text":" the forces "},{"text":"close to","bold":true},{"text":" a company that "},{"text":"directly","bold":true},{"text":" affect its ability to serve its customers. They affect a "},{"text":"particular","bold":true},{"text":" firm."}]},{"text":[{"text":"Macro (general) environment:","bold":true},{"text":" the "},{"text":"broad","bold":true},{"text":" external forces (political, economic, social, technological, legal, environmental) that affect "},{"text":"all","bold":true},{"text":" businesses in an economy, usually indirectly."}]},{"text":[{"text":"Key distinction:","bold":true},{"text":" the micro environment affects a particular firm directly; the macro environment consists of broad forces affecting all firms. Both are "},{"text":"external","bold":true},{"text":"."}]}]},{"type":"paragraph","text":[{"text":"Components of the micro (task) environment","bold":true}]},{"type":"list","ordered":true,"start":1,"items":[{"text":[{"text":"Customers","bold":true}]},{"text":[{"text":"Suppliers","bold":true},{"text":" (of raw materials, foodstuffs, equipment, labour, money)"}]},{"text":[{"text":"Competitors","bold":true}]},{"text":[{"text":"Intermediaries","bold":true},{"text":" (distributors, wholesalers, retailers, transporters, banks that help the firm sell and deliver)"}]},{"text":[{"text":"Publics","bold":true},{"text":" (host communities, the media, pressure groups)"}]},{"text":[{"text":"Specific regulators","bold":true},{"text":" of the industry, "},{"text":"labour unions","bold":true},{"text":" and "},{"text":"strategic partners","bold":true}]}]},{"type":"paragraph","text":[{"text":"Components of the macro (general) environment:","bold":true},{"text":" the six PESTLE factors (Lesson 7.3), e.g. elections and ideology, inflation, interest rates, exchange rates, unemployment, population growth, culture and religion, internet penetration, new laws, climate and pollution."}]},{"type":"table","header":[[{"text":"Factor"}],[{"text":"Micro or macro?"}]],"rows":[[[{"text":"Farmers and traders who supply a Lagos restaurant"}],[{"text":"Micro"}]],[[{"text":"A new competitor opening next door"}],[{"text":"Micro"}]],[[{"text":"A dispute with the main raw-material supplier"}],[{"text":"Micro"}]],[[{"text":"A complaint from a distributor"}],[{"text":"Micro"}]],[[{"text":"National inflation or unemployment rate"}],[{"text":"Macro"}]],[[{"text":"Nigeria's population growth rate"}],[{"text":"Macro"}]],[[{"text":"Level of internet penetration in Nigeria"}],[{"text":"Macro"}]],[[{"text":"Government's national fiscal policy"}],[{"text":"Macro"}]]]}],"explainMore":[{"type":"list","ordered":false,"items":[{"text":[{"text":"Trap:","bold":true},{"text":" \"The micro environment is inside the firm, the macro is outside\" is "},{"text":"wrong","bold":true},{"text":". The inside of the firm is the "},{"text":"internal","bold":true},{"text":" environment. Micro and macro are both outside; they differ in "},{"text":"closeness and directness","bold":true},{"text":"."}]},{"text":[{"text":"When a Nigerian bottling company loses sales because its biggest South-West "},{"text":"distributor","bold":true},{"text":" collapses, the distributor is part of its "},{"text":"micro","bold":true},{"text":" environment."}]},{"text":[{"text":"A foreign company with lower prices opening a large plant in Nigeria and taking customers from a local biscuit maker is a "},{"text":"threat in the local firm's micro (task) environment","bold":true},{"text":" (it is a competitor), not anything internal."}]},{"text":[{"text":"Two components of the task environment, if asked for a pair: "},{"text":"suppliers and competitors","bold":true},{"text":" (or customers and suppliers). Elections, inflation, unemployment, climate and pollution are macro."}]},{"text":[{"text":"The "},{"text":"government's fiscal policy","bold":true},{"text":" (national taxes and spending) is macro; a specific regulator acting on one industry (such as the Nigerian Communications Commission for a telecom firm) is close to the firm and is often treated as part of its task environment."}]}]}]},{"number":"7.3","title":"PESTLE analysis and environmental scanning","mustKnow":[{"type":"list","ordered":false,"items":[{"text":[{"text":"PESTLE:","bold":true},{"text":" "},{"text":"P","bold":true},{"text":"olitical, "},{"text":"E","bold":true},{"text":"conomic, "},{"text":"S","bold":true},{"text":"ocial, "},{"text":"T","bold":true},{"text":"echnological, "},{"text":"L","bold":true},{"text":"egal, "},{"text":"E","bold":true},{"text":"nvironmental. It is a tool for assessing "},{"text":"macro-environmental (external) factors","bold":true},{"text":"."}]},{"text":[{"text":"Purpose:","bold":true},{"text":" to identify external macro-environmental factors that may create "},{"text":"opportunities or threats","bold":true},{"text":"."}]},{"text":[{"text":"PESTLE does "},{"text":"not","bold":true},{"text":" examine the firm's internal strengths and weaknesses, competitors' strategies or employee performance."}]},{"text":[{"text":"Environmental scanning:","bold":true},{"text":" the process of monitoring and analysing the external environment to detect changes that may affect a business. PESTLE is most useful "},{"text":"during environmental scanning","bold":true},{"text":"."}]},{"text":[{"text":"Shorter and longer versions: "},{"text":"PEST","bold":true},{"text":" (four factors), "},{"text":"STEEPLE","bold":true},{"text":" (adds Ethical)."}]}]},{"type":"table","header":[[{"text":"Factor"}],[{"text":"What it covers"}],[{"text":"Nigerian examples"}]],"rows":[[[{"text":"Political","bold":true}],[{"text":"Government stability, ideology, policy direction, elections, insecurity, government attitude to business"}],[{"text":"Investors delaying projects before a general election; a state policy favouring $study_guide$);
insert into private.study_guide_chunks (guide, ordinal, chunk) values ('study_guide_bua201', 28, $study_guide$locally made goods in public procurement"}]],[[{"text":"Economic","bold":true}],[{"text":"Inflation, interest rates, exchange rates, income levels, unemployment, recession, economic growth"}],[{"text":"Naira depreciation raising import costs; inflation eroding a family's budget; CBN raising the monetary policy rate"}]],[[{"text":"Social","bold":true}],[{"text":"Population size and age structure, urbanisation, education, culture, religion, lifestyles, tastes"}],[{"text":"A young, urbanising population; respecting religious values in Kano; preference for locally made fashion"}]],[[{"text":"Technological","bold":true}],[{"text":"Inventions, internet and mobile access, mobile payments, automation, e-commerce"}],[{"text":"Smartphones and payment apps letting an Aba shoe-maker sell online; ATMs and online banking replacing tellers"}]],[[{"text":"Legal","bold":true}],[{"text":"The actual laws and regulations firms must obey: company, labour, tax, consumer, data laws"}],[{"text":"Nigeria Data Protection Act 2023; a new minimum wage law; NIN-SIM linkage rules; CAMA 2020"}]],[[{"text":"Environmental (ecological)","bold":true}],[{"text":"Climate, weather, pollution, waste, natural resources, sustainability"}],[{"text":"Flooding in Kogi State; oil pollution complaints in the Niger Delta"}]]]}],"explainMore":[{"type":"list","ordered":false,"items":[{"text":[{"text":"Political vs legal.","bold":true},{"text":" Political factors concern government "},{"text":"stability, ideology and policy direction","bold":true},{"text":"; legal factors concern the "},{"text":"actual laws and regulations","bold":true},{"text":" firms must obey. A policy direction announced by a government is political; once it becomes a binding law or regulation with penalties, compliance with it is legal. A new tax "},{"text":"law","bold":true},{"text":" passed by the National Assembly is legal (and economic in effect), never social."}]},{"text":[{"text":"Economic factors in action:","bold":true}],"blocks":[{"type":"list","ordered":false,"items":[{"text":[{"text":"A "},{"text":"recession","bold":true},{"text":" reduces demand mainly because of "},{"text":"reduced disposable income","bold":true},{"text":"."}]},{"text":[{"text":"Inflation","bold":true},{"text":" reduces purchasing power. "},{"text":"Worked example:","bold":true},{"text":" a family in Ibadan spends ₦50,000 a month on food. If food prices rise by 25%, the budget buys only ₦50,000 ÷ 1.25 = ₦40,000 worth of food at the old prices, a loss of ₦10,000 in real terms. The supermarket's sales "},{"text":"volume","bold":true},{"text":" falls: an economic factor."}]},{"text":[{"text":"Inflation may benefit debtors","bold":true},{"text":" because the "},{"text":"real value of the money they owe declines","bold":true},{"text":". "},{"text":"Worked example:","bold":true},{"text":" a trader owes ₦1,000,000, repayable in a year. With 25% inflation over that year, the ₦1,000,000 repaid is worth only ₦1,000,000 ÷ 1.25 = ₦800,000 in today's purchasing power."}]},{"text":[{"text":"Exchange rate.","bold":true},{"text":" An importer's container rises from ₦18 million to ₦27 million because the naira weakened. Increase = ₦27m − ₦18m = ₦9m; percentage increase = 9 ÷ 18 × 100 = "},{"text":"50%","bold":true},{"text":". This is an "},{"text":"economic","bold":true},{"text":" factor."}]},{"text":[{"text":"Interest rates.","bold":true},{"text":" When the Central Bank of Nigeria raises its "},{"text":"monetary policy rate (MPR)","bold":true},{"text":", loans become dearer: an "},{"text":"economic","bold":true},{"text":" factor, even though the CBN is a government body."}]}]}]},{"text":[{"text":"Mixed cases:","bold":true},{"text":" a regulation requiring SIM cards to be linked to National Identification Numbers is "},{"text":"legal","bold":true},{"text":"; rapid growth of mobile internet use is "},{"text":"technological","bold":true},{"text":". A fall in household incomes is economic, not technological. Changes in religious beliefs are social, not economic. Climate change and extreme weather are "},{"text":"environmental","bold":true},{"text":"; a new competitor is micro, and a change of government is political."}]},{"text":[{"text":"Economic liberalisation","bold":true},{"text":" (opening markets to private and foreign firms) tends to "},{"text":"increase competition","bold":true},{"text":". Nigeria's telecom liberalisation, with GSM licences issued in 2001, ended NITEL's near-monopoly and brought in operators such as MTN, which lowered prices and expanded access."}]},{"text":[{"text":"External change cuts both ways.","bold":true},{"text":" If the Federal Government cuts import duty on industrial machinery and a packaging firm saves ₦3 million on a new line, the environment has created an "},{"text":"opportunity","bold":true},{"text":". External changes can create opportunities as well as threats."}]}]}]},{"number":"7.4","title":"SWOT analysis, competitive advantage and flexibility","mustKnow":[{"type":"list","ordered":false,"items":[{"text":[{"text":"SWOT:","bold":true},{"text":" "},{"text":"S","bold":true},{"text":"trengths, "},{"text":"W","bold":true},{"text":"eaknesses, "},{"text":"O","bold":true},{"text":"pportunities, "},{"text":"T","bold":true},{"text":"hreats."}]},{"text":[{"text":"Strengths and weaknesses","bold":true},{"text":" come from the "},{"text":"internal","bold":true},{"text":" environment. Evaluating the firm's strengths in a SWOT is part of "},{"text":"internal environment analysis","bold":true},{"text":"."}]},{"text":[{"text":"Opportunities and threats","bold":true},{"text":" come from the "},{"text":"external","bold":true},{"text":" environment."}]}]},{"type":"table","header":[[],[{"text":"Helpful"}],[{"text":"Harmful"}]],"rows":[[[{"text":"Internal","bold":true}],[{"text":"Strengths (e.g. strong brand, skilled staff, modern plant)"}],[{"text":"Weaknesses (e.g. old machines, staff lacking modern skills, poor cash flow)"}]],[[{"text":"External","bold":true}],[{"text":"Opportunit$study_guide$);
insert into private.study_guide_chunks (guide, ordinal, chunk) values ('study_guide_bua201', 29, $study_guide$ies (e.g. lower import duty, growing young urban market, new technology)"}],[{"text":"Threats (e.g. new low-price competitor, inflation, insecurity, unfavourable regulation)"}]]]},{"type":"list","ordered":false,"items":[{"text":[{"text":"Sustainable competitive advantage","bold":true},{"text":" arises from resources that are "},{"text":"valuable, rare and hard to imitate","bold":true},{"text":" (and that the organisation is set up to exploit). This is the "},{"text":"resource-based view","bold":true},{"text":", associated with "},{"text":"Jay Barney","bold":true},{"text":" (the VRIN/VRIO test)."}]},{"text":[{"text":"Strategic flexibility:","bold":true},{"text":" the ability to change plans and resources quickly; it mainly enhances a firm's "},{"text":"ability to adapt to changes in its environment","bold":true},{"text":"."}]}]}],"explainMore":[{"type":"list","ordered":false,"items":[{"text":[{"text":"PESTLE feeds SWOT.","bold":true},{"text":" PESTLE scans the macro environment; its findings become the "},{"text":"O","bold":true},{"text":" and "},{"text":"T","bold":true},{"text":" of SWOT. A look inward at resources gives the "},{"text":"S","bold":true},{"text":" and "},{"text":"W","bold":true},{"text":"."}]},{"text":[{"text":"Paint manufacturer:","bold":true},{"text":" old machines and staff lacking modern skills are "},{"text":"weaknesses arising from the internal environment","bold":true},{"text":"."}]},{"text":[{"text":"Fashion brand:","bold":true},{"text":" more young customers preferring locally made clothing and promoting it on social media is a "},{"text":"social factor that creates an opportunity","bold":true},{"text":"."}]},{"text":[{"text":"State procurement policy favouring local goods:","bold":true},{"text":" for local manufacturers, a "},{"text":"political factor that creates an opportunity","bold":true},{"text":"."}]},{"text":[{"text":"Trap:","bold":true},{"text":" opportunities do "},{"text":"not","bold":true},{"text":" come from the firm's weaknesses, its culture or its financial ratios; those are internal."}]},{"text":[{"text":"Resources that are common, easily accessible, easily transferred to rivals or short-term cannot give a "},{"text":"sustainable","bold":true},{"text":" advantage, because rivals can copy them."}]},{"text":[{"text":"Strategic flexibility does not raise the likelihood of exiting markets, governance failure or exposure to inflation; it reduces the damage from change."}]}]}]},{"number":"7.5","title":"Impact of Nigeria's business environment on performance","mustKnow":[{"type":"paragraph","text":[{"text":"Why managers must study the environment:","bold":true},{"text":" to "},{"text":"anticipate changes, seize opportunities and reduce the impact of threats","bold":true},{"text":". The environment keeps changing, so it is a reason for planning, not a substitute for it."}]},{"type":"paragraph","text":[{"text":"Main Nigerian pressures and their effects","bold":true}]},{"type":"list","ordered":true,"start":1,"items":[{"text":[{"text":"Inflation:","bold":true},{"text":" higher input costs, falling real incomes, lower sales volumes."}]},{"text":[{"text":"Exchange-rate depreciation and forex scarcity:","bold":true},{"text":" dearer imported raw materials and machines; difficulty paying foreign suppliers."}]},{"text":[{"text":"High interest rates:","bold":true},{"text":" costlier borrowing, less expansion."}]},{"text":[{"text":"Insecurity:","bold":true},{"text":" higher insurance and security costs, disrupted distribution, lost markets."}]},{"text":[{"text":"Infrastructure deficits","bold":true},{"text":" (power, roads, ports): high energy and logistics costs."}]},{"text":[{"text":"Policy and regulatory change:","bold":true},{"text":" subsidy removal, tariffs, new laws that raise compliance costs or open new markets."}]},{"text":[{"text":"Social and technological change:","bold":true},{"text":" a large, young, urbanising population and fast mobile adoption, which create opportunities."}]}]}],"explainMore":[{"type":"list","ordered":false,"items":[{"text":[{"text":"Macro factors affect every business, including small ones.","bold":true},{"text":" An Enugu shop with ₦2 million monthly sales still feels inflation (its stock costs more), interest rates (its loans cost more) and government policy (taxes, levies) through "},{"text":"costs, prices and demand","bold":true},{"text":". The owner who says \"only my shop matters\" is wrong."}]},{"text":[{"text":"Insecurity:","bold":true},{"text":" a Kaduna food distributor facing risky highways pays more for insurance and security escorts; the external environment "},{"text":"increases operating costs and reduces performance","bold":true},{"text":". Well-managed firms cannot ignore it or change it alone."}]},{"text":[{"text":"Uncontrollable but manageable:","bold":true},{"text":" a Nigerian firm cannot stop a rise in world crude oil prices, but it can adjust its pricing and sourcing. External factors are "},{"text":"largely uncontrollable, so managers must anticipate and adapt","bold":true},{"text":". This affects all firms, not only oil sellers, because fuel, transport and the naira respond to oil prices."}]},{"text":[{"text":"Exits as evidence:","bold":true},{"text":" in 2023 several multinationals scaled down manufacturing in Nigeria, citing the difficult operating environment and forex problems: GSK Consumer Nigeria announced it would stop operating its own business there, and Procter & Gamble moved to an import-only model."}]},{"text":[{"text":"Opportunities exist too:","bold":true},{"text":" Nigeria's young population and mobile adoption have fuelled fintech growth and online selling; telecom liberalisation in 2001 transformed connectivity and created a large new industry."}]},{"text":[{"text":"How firms respond:","bold":true},{"text":" environmental scanning (PESTLE), SWOT-based strategy, local sourcing of raw materials (backward integration), hedging and cost control, investment in alternative power, strategic flexib$study_guide$);
insert into private.study_guide_chunks (guide, ordinal, chunk) values ('study_guide_bua201', 30, $study_guide$ility and building valuable, rare, hard-to-imitate resources."}]}]}]}],"recap":[{"type":"list","ordered":false,"items":[{"text":[{"text":"Business environment = all internal and external factors affecting a firm's operations and performance."}]},{"text":[{"text":"Internal (owners, board, employees, culture, resources) is largely controllable; external is largely uncontrollable, so anticipate and adapt."}]},{"text":[{"text":"Micro (task) = customers, suppliers, competitors, intermediaries, publics: close and direct. Macro (general) = broad PESTLE forces affecting all firms. Both are external."}]},{"text":[{"text":"PESTLE = Political, Economic, Social, Technological, Legal, Environmental; used in environmental scanning for macro factors; never for internal strengths."}]},{"text":[{"text":"Political = stability, ideology, policy direction; Legal = actual laws to obey."}]},{"text":[{"text":"SWOT: S and W internal; O and T external."}]},{"text":[{"text":"Inflation erodes purchasing power and benefits debtors; recession cuts disposable income; liberalisation increases competition."}]},{"text":[{"text":"Sustainable advantage = valuable, rare, hard-to-imitate resources; strategic flexibility = ability to adapt."}]},{"text":[{"text":"Nigeria: inflation, forex, interest rates, insecurity, infrastructure, policy change; they raise costs but also create opportunities."}]}]}],"theory":{"itemId":"ca335f0b-75bc-5113-ad99-cd32a9ce2b7d","question":[{"type":"paragraph","text":[{"text":"A Lagos bakery uses 400 bags of imported-wheat flour a month. Because the naira weakened, the price per bag rose from ₦60,000 to ₦78,000. (a) Compute the percentage rise in the price per bag and the extra monthly cost. (b) Classify the cause under PESTLE and SWOT, and state whether it is micro or macro."}]}]},"practice":[{"topic":"The Business Environment","named":false}]}},{"kind":"note","itemId":"0dc02609-6080-5e76-8e9a-5a6235439b68","sourceKey":"guide-topic:8","position":8,"payload":{"title":"Functional Areas I: Marketing and Human Resources","body":"Market and marketing; the six marketing functions and customer value; STP and the four bases of segmentation; the 4Ps; rural vs urban consumers in Nigeria; HRM meaning, functions and importance; how marketing and HR depend on each other and coordinate.","noteType":"guide_topic","number":8,"mustKnow":[{"text":"Market and marketing; the six marketing functions and customer value; STP and the four bases of segmentation; the 4Ps; rural vs urban consumers in Nigeria; HRM meaning, functions and importance; how marketing and HR depend on each other and coordinate."}],"lessons":[{"number":"8.1","title":"Market, marketing and the marketing functions","mustKnow":[{"type":"list","ordered":false,"items":[{"text":[{"text":"Market (old view):","bold":true},{"text":" a place where buying and selling takes place."}]},{"text":[{"text":"Market (modern view):","bold":true},{"text":" all "},{"text":"individuals and organisations that are actual or potential buyers","bold":true},{"text":" of a product. \"The car market\" means all actual or potential car buyers, not a place where cars are sold. The meaning grew beyond a place because of "},{"text":"innovation and globalisation","bold":true},{"text":"."}]},{"text":[{"text":"2 broad categories of market:","bold":true}],"blocks":[{"type":"list","ordered":true,"start":1,"items":[{"text":[{"text":"Consumer market:","bold":true},{"text":" all individuals who buy goods and services for "},{"text":"direct consumption or household use","bold":true},{"text":"."}]},{"text":[{"text":"Industrial market:","bold":true},{"text":" organisations in agriculture, forestry, fisheries, transport, construction, mining, utilities and services that buy goods and services "},{"text":"for further production","bold":true},{"text":"."}]}]}]},{"text":[{"text":"Marketing (limited definition):","bold":true},{"text":" the performance of business activities that direct the flow of goods and services to the consumer. It is too limited because marketing "},{"text":"starts before production","bold":true},{"text":" and "},{"text":"continues after the purchase","bold":true},{"text":"."}]},{"text":[{"text":"Starting point of marketing:","bold":true},{"text":" identifying and analysing the "},{"text":"needs, wants and demands","bold":true},{"text":" of consumers."}]},{"text":[{"text":"Marketing concept:","bold":true},{"text":" find out what customers need first, then produce it to satisfy them (e.g. starting production only "},{"text":"after market research","bold":true},{"text":")."}]}]},{"type":"paragraph","text":[{"text":"The 6 marketing functions","bold":true}]},{"type":"list","ordered":true,"start":1,"items":[{"text":[{"text":"Pricing","bold":true},{"text":" the product"}]},{"text":[{"text":"Distribution","bold":true},{"text":" of the product to places where it is needed"}]},{"text":[{"text":"Promotion","bold":true},{"text":" of the product and the company (making products known; making the company a household name)"}]},{"text":[{"text":"Rendering after-sale services","bold":true},{"text":" (maintenance, repairs, returning defective items)"}]},{"text":[{"text":"Training and motivating salespersons","bold":true}]},{"text":[{"text":"Planning and controlling","bold":true},{"text":" the marketing effort of the company"}]}]},{"type":"list","ordered":false,"items":[{"text":[{"text":"Customer value:","bold":true},{"text":" customer value = total benefits the customer receives − total cost to the customer (money, time, effort)."}]},{"text":[{"text":"Market share:","bold":true},{"text":" market share = firm's sales ÷ total market sales × 100."}]}]}],"explainMore":[{"type":"list","ordered":false,"items":[{"text":[{"text":"Consumer vs industrial purchases:","bold":true},{"text":" a family buying rice for its meals is in the "},{"text":"consumer","bold":true},{"text":" market. A construction firm in Abuja buying 2,000 bags of cement for an estate, a mining firm buying explosives, a transport $study_guide$);
insert into private.study_guide_chunks (guide, ordinal, chunk) values ('study_guide_bua201', 31, $study_guide$company buying tyres and a fishery buying nets are all in the "},{"text":"industrial","bold":true},{"text":" market."}]},{"text":[{"text":"After-sale service:","bold":true},{"text":" an Ikeja phone retailer offering six months of free repairs and screen checks. A beverage firm's workshop that improves its sales team's selling skills and rewards top performers is "},{"text":"training and motivating salespersons","bold":true},{"text":"."}]},{"text":[{"text":"Trap:","bold":true},{"text":" preparing the statement of financial position is accounting, "},{"text":"not","bold":true},{"text":" a marketing function. Testing in a pilot market, researching needs and designing packaging happen "},{"text":"before","bold":true},{"text":" purchase."}]},{"text":[{"text":"Concepts compared:","bold":true},{"text":" the "},{"text":"production concept","bold":true},{"text":" stresses producing at the lowest cost; the "},{"text":"selling concept","bold":true},{"text":" stresses aggressive selling; the "},{"text":"marketing concept","bold":true},{"text":" starts from customer needs."}]},{"text":[{"text":"Customer value worked example:","bold":true},{"text":" a buyer values a blender's benefits at ₦90,000 and pays ₦70,000 in total. Customer value = ₦90,000 − ₦70,000 = ₦20,000. The higher the value, the likelier the purchase and loyalty."}]},{"text":[{"text":"Market share worked example:","bold":true},{"text":" total annual juice sales in a city are ₦48,000,000; a brand sells ₦7,200,000. Market share = 7,200,000 ÷ 48,000,000 × 100 = "},{"text":"15%","bold":true},{"text":". (Same method: ₦3,000,000 of ₦12,000,000 = 25%.)"}]}]}]},{"number":"8.2","title":"Segmentation, targeting and positioning (STP)","mustKnow":[{"type":"list","ordered":false,"items":[{"text":[{"text":"STP:","bold":true},{"text":" a customer-centred framework in which a broad market is divided into "},{"text":"Segments","bold":true},{"text":", the most attractive are chosen as "},{"text":"Targets","bold":true},{"text":", and a unique image is created to "},{"text":"Position","bold":true},{"text":" the product in target consumers' minds. "},{"text":"Order: segmentation, targeting, positioning.","bold":true}]},{"text":[{"text":"Market segmentation:","bold":true},{"text":" dividing the market into smaller groups of consumers who share similar "},{"text":"needs, characteristics or behaviours","bold":true},{"text":". It improves strategy mainly by "},{"text":"enhancing targeting precision","bold":true},{"text":"."}]}]},{"type":"paragraph","text":[{"text":"4 bases of segmentation","bold":true}]},{"type":"table","header":[[{"text":"Basis"}],[{"text":"Variables"}]],"rows":[[[{"text":"Demographic","bold":true}],[{"text":"Age, gender, income, education, family size"}]],[[{"text":"Geographic","bold":true}],[{"text":"Location: country, region, city"}]],[[{"text":"Psychographic","bold":true}],[{"text":"Lifestyle, values, personality, interests"}]],[[{"text":"Behavioural","bold":true}],[{"text":"Purchase habits, usage rate, loyalty, benefits sought"}]]]},{"type":"list","ordered":false,"items":[{"text":[{"text":"Targeting:","bold":true},{"text":" "},{"text":"evaluating","bold":true},{"text":" segments and "},{"text":"selecting","bold":true},{"text":" one or more to focus on. Evaluate "},{"text":"segment size, growth potential, profitability and competition","bold":true},{"text":"; select segments that fit the company's "},{"text":"goals and resources","bold":true},{"text":"."}]},{"text":[{"text":"Positioning:","bold":true},{"text":" crafting a distinct, desirable image of the product in the target customers' minds "},{"text":"relative to competitors","bold":true},{"text":". It involves "},{"text":"unique value","bold":true},{"text":", adapting the "},{"text":"marketing mix (4Ps)","bold":true},{"text":" to the target, and "},{"text":"perception","bold":true},{"text":" (being seen as the best solution)."}]},{"text":[{"text":"Why STP matters (4):","bold":true},{"text":" "},{"text":"focus","bold":true},{"text":" (resources on the most promising customers), "},{"text":"relevance","bold":true},{"text":" (personalised messages), "},{"text":"loyalty","bold":true},{"text":" (repeat business), "},{"text":"competitive edge","bold":true},{"text":" (standing out in crowded markets)."}]},{"text":[{"text":"Segment size:","bold":true},{"text":" customers reached = total population × % in segment × % of segment targeted."}]}]}],"explainMore":[{"type":"list","ordered":false,"items":[{"text":[{"text":"Classify the basis:","bold":true},{"text":" savings accounts for those earning below ₦100,000 and above ₦1,000,000 a month = "},{"text":"demographic","bold":true},{"text":" (income). Different paint ranges for the South-South and the North-West because of climate and building style = "},{"text":"geographic","bold":true},{"text":". A fitness brand for all ages sharing an active lifestyle = "},{"text":"psychographic","bold":true},{"text":". Rewards for weekly shoppers vs occasional shoppers = "},{"text":"behavioural","bold":true},{"text":" (purchase habits, loyalty)."}]},{"text":[{"text":"Trap:","bold":true},{"text":" lifestyle is "},{"text":"psychographic","bold":true},{"text":", not demographic. Positioning is not shelf placement or logistics."}]},{"text":[{"text":"A juice advertised as \"the 100% natural choice for health-conscious mothers\" against sugary rivals is "},{"text":"positioning","bold":true},{"text":"."}]},{"text":[{"text":"Directors' personal hobbies are not a targeting criterion. STP does "},{"text":"not","bold":true},{"text":" remove the need for promotion."}]},{"text":[{"text":"Segment-size worked example:","bold":true},{"text":" Ibadan has 2,500,000 adults; 40% use smartphones; a fintech aims to reach 15% of that segment in year one. Segment = 2,500,000 × 0.40 = 1,000,000; customers = 1,000,000 × 0.15 = "},{"text":"150,000","bold":true},{"text":". (Same method: 1,800,000 Lagos women aged 18-35 × 35% × 40% = 252,000.)"}]},{"text":[{"text":"Growth strategies (Ansoff):$study_guide$);
insert into private.study_guide_chunks (guide, ordinal, chunk) values ('study_guide_bua201', 32, $study_guide$","bold":true},{"text":" "},{"text":"market penetration","bold":true},{"text":" = growing sales of "},{"text":"existing products in existing markets","bold":true},{"text":"; market development = existing products in new markets; product development = new products for existing markets; diversification = new products in new markets."}]}]}]},{"number":"8.3","title":"The marketing mix (4Ps)","mustKnow":[{"type":"list","ordered":false,"items":[{"text":[{"text":"Marketing mix:","bold":true},{"text":" the set of factors ("},{"text":"product, price, place, promotion","bold":true},{"text":") that help to execute a marketing programme."}]}]},{"type":"table","header":[[{"text":"P"}],[{"text":"Meaning"}],[{"text":"Question it answers"}]],"rows":[[[{"text":"Price","bold":true}],[{"text":"The value or worth placed on an item"}],[{"text":"How much are customers willing to pay?"}]],[[{"text":"Product","bold":true}],[{"text":"Anything offered to the public for consumption or use"}],[{"text":"What is being offered for sale?"}]],[[{"text":"Promotion","bold":true}],[{"text":"Making the product known and communicating persuasively: "},{"text":"advertising, public relations, sales promotion","bold":true}],[{"text":"How do we make it known; are customers aware?"}]],[[{"text":"Place","bold":true}],[{"text":"Making the product accessible and available"}],[{"text":"Where can it be got; how do we get the right product to the right place?"}]]]},{"type":"list","ordered":false,"items":[{"text":[{"text":"Consumer products:","bold":true},{"text":" used directly by final users. "},{"text":"Industrial products:","bold":true},{"text":" used to produce other products or in the course of production."}]},{"text":[{"text":"Place","bold":true},{"text":" is linked to the view that "},{"text":"without customers accessing the products, production is incomplete","bold":true},{"text":"."}]}]}],"explainMore":[{"type":"list","ordered":false,"items":[{"text":[{"text":"Flour sold to bakeries that make bread is an "},{"text":"industrial product","bold":true},{"text":" to the bakeries; bread bought by a household is a consumer product."}]},{"text":[{"text":"Radio jingles in Yoruba, Hausa and Igbo persuading people to try a soap = "},{"text":"promotion","bold":true},{"text":". Signing 300 new kiosks and supermarkets in Ibadan so chips are easy to find = "},{"text":"place","bold":true},{"text":"."}]},{"text":[{"text":"Trap:","bold":true},{"text":" choosing warehouses and transport routes is "},{"text":"place","bold":true},{"text":", not promotion. "},{"text":"People","bold":true},{"text":" is "},{"text":"not","bold":true},{"text":" one of the 4Ps; it belongs to the extended "},{"text":"7Ps","bold":true},{"text":" for services (adding people, process, physical evidence)."}]}]}]},{"number":"8.4","title":"Rural vs urban consumer markets in Nigeria","mustKnow":[{"type":"table","header":[[{"text":"Feature"}],[{"text":"Urban market"}],[{"text":"Rural market"}]],"rows":[[[{"text":"Income and spending"}],[{"text":"Higher disposable income; more on non-necessities"}],[{"text":"Often lower incomes, yet highly knowledgeable about quality and value"}]],[[{"text":"Preferences"}],[{"text":"International trends, digital marketing; quality and aesthetics"}],[{"text":"Functionality, durability, bulk purchases; strong cultural norms"}]],[[{"text":"Retail"}],[{"text":"More modern retail, though informal markets still dominate; high digital adoption"}],[{"text":"Informal open-air markets and kiosks; less modern retail"}]],[[{"text":"Other"}],[{"text":"Competitive; price-sensitive in some categories; affected by global factors"}],[{"text":"Fast-growing mobile access, rising literacy and connectivity"}]],[[{"text":"Value proposition"}],[{"text":"Brand and experience"}],[{"text":"Durability and value for money"}]]]},{"type":"paragraph","text":[{"text":"Blurring lines:","bold":true},{"text":" infrastructure is better in towns but improving in villages; rural consumers are adopting digital and e-commerce tools "},{"text":"through mobile phones","bold":true},{"text":"; foodstuff markets are "},{"text":"integrated, with urban prices often driving rural prices","bold":true},{"text":"; urban buyers increasingly value traditional goods while rural buyers research online."}]},{"type":"paragraph","text":[{"text":"Marketing implications:","bold":true},{"text":" adapt segmentation to the differences, using digital to reach both; build "},{"text":"robust distribution channels to overcome infrastructure gaps, especially in rural zones","bold":true},{"text":"; stress durability and value in rural areas and brand and experience in urban areas."}]}],"explainMore":[{"type":"list","ordered":false,"items":[{"text":[{"text":"A detergent firm entering Benue villages should stress "},{"text":"durability and value for money","bold":true},{"text":" (affordable sachets, bulk packs), not celebrity endorsements, luxury or supermarket-only sales."}]},{"text":[{"text":"Urban consumers switch brands more easily mainly because of "},{"text":"high exposure to alternatives","bold":true},{"text":"."}]},{"text":[{"text":"Trap:","bold":true},{"text":" \"Rural consumers have little knowledge of product quality and value\" is "},{"text":"false","bold":true},{"text":"; they are highly knowledgeable."}]}]}]},{"number":"8.5","title":"Human Resource Management (HRM)","mustKnow":[{"type":"list","ordered":false,"items":[{"text":[{"text":"HRM:","bold":true},{"text":" the practice of "},{"text":"recruiting, hiring, deploying and managing","bold":true},{"text":" an organisation's employees; the function that focuses on recruiting, managing and providing guidelines to the company's manpower."}]},{"text":[{"text":"Evolution:","bold":true},{"text":" from "},{"text":"planned exploitation of staff","bold":true},{"text":" to "},{"text":"HR metrics and measurement and strategic direction","bold":true},{"text":" to display value."}]}]},{"type":"paragraph","text":[{"text":"6 functions of HRM","bold":true}]},{"type":"$study_guide$);
insert into private.study_guide_chunks (guide, ordinal, chunk) values ('study_guide_bua201', 33, $study_guide$list","ordered":true,"start":1,"items":[{"text":[{"text":"Recruitment","bold":true},{"text":" (selection and hiring)"}]},{"text":[{"text":"Training and development","bold":true}]},{"text":[{"text":"Compensation and benefits","bold":true},{"text":" (pay, welfare packages)"}]},{"text":[{"text":"Performance appraisal","bold":true}]},{"text":[{"text":"Ensuring legal compliance","bold":true},{"text":" (employment laws, tax, minimum wage)"}]},{"text":[{"text":"Advising","bold":true},{"text":" top management on policies and department heads on job design, recruitment, selection, job descriptions"}]}]},{"type":"paragraph","text":[{"text":"5 areas of HRM's importance","bold":true}]},{"type":"list","ordered":true,"start":1,"items":[{"text":[{"text":"Recruitment and retention","bold":true}]},{"text":[{"text":"Employee development and engagement","bold":true}]},{"text":[{"text":"Compliance and risk management","bold":true}]},{"text":[{"text":"Performance management","bold":true}]},{"text":[{"text":"Organisational strategy and planning","bold":true},{"text":" (worker needs, restructuring, "},{"text":"succession plans","bold":true},{"text":")"}]}]},{"type":"list","ordered":false,"items":[{"text":[{"text":"Labour turnover rate:","bold":true},{"text":" turnover rate = number of leavers ÷ average number of employees × 100."}]}]}],"explainMore":[{"type":"list","ordered":false,"items":[{"text":[{"text":"Classify:","bold":true},{"text":" checking that Ota factory workers get at least the national minimum wage and tax rules are followed = "},{"text":"legal compliance","bold":true},{"text":". Yearly evaluation of each officer to find skill gaps = "},{"text":"performance appraisal","bold":true},{"text":". Reviewing salaries, housing allowances and medical cover by grade = "},{"text":"compensation and benefits","bold":true},{"text":". Setting selling prices is marketing, "},{"text":"not","bold":true},{"text":" HR."}]},{"text":[{"text":"Workforce (HR) planning","bold":true},{"text":" ensures the organisation has "},{"text":"the right number of people with the right skills when needed","bold":true},{"text":"."}]},{"text":[{"text":"Succession planning","bold":true},{"text":" reduces the risk of a "},{"text":"leadership vacuum","bold":true},{"text":"."}]},{"text":[{"text":"Training effectiveness","bold":true},{"text":" is best measured by "},{"text":"changes in trainees' behaviour and job performance","bold":true},{"text":" (Kirkpatrick's levels: reaction, learning, behaviour, results). Training and development is the HR activity that "},{"text":"most directly supports change management","bold":true},{"text":", because it equips staff for new ways of working."}]},{"text":[{"text":"High engagement","bold":true},{"text":" mainly improves "},{"text":"productivity","bold":true},{"text":". "},{"text":"More team autonomy","bold":true},{"text":" mainly improves "},{"text":"motivation","bold":true},{"text":". "},{"text":"High turnover","bold":true},{"text":" raises "},{"text":"recruitment and training costs","bold":true},{"text":"."}]},{"text":[{"text":"Turnover worked example:","bold":true},{"text":" a firm starts the year with 110 staff and ends with 130; 18 people left. Average staff = (110 + 130) ÷ 2 = 120. Turnover rate = 18 ÷ 120 × 100 = "},{"text":"15%","bold":true},{"text":"."}]}]}]},{"number":"8.6","title":"Interdependence of functional areas and cross-functional coordination","mustKnow":[{"type":"list","ordered":false,"items":[{"text":[{"text":"Core idea:","bold":true},{"text":" "},{"text":"marketing sells the brand externally; HR builds the brand internally.","bold":true},{"text":" Employees are the first customers who become brand advocates."}]}]},{"type":"paragraph","text":[{"text":"4 key areas of interdependence","bold":true}]},{"type":"list","ordered":true,"start":1,"items":[{"text":[{"text":"Employer branding and recruitment:","bold":true},{"text":" marketing helps HR with messaging, "},{"text":"candidate personas","bold":true},{"text":" and channels such as social media; HR helps marketing by "},{"text":"hiring skilled, culturally aligned people","bold":true},{"text":" who can deliver what marketing promises."}]},{"text":[{"text":"Internal communication and culture:","bold":true},{"text":" consistent internal messages turn employees into brand ambassadors."}]},{"text":[{"text":"Onboarding and retention:","bold":true},{"text":" a joint onboarding process; "},{"text":"employee retention = customer retention","bold":true},{"text":"."}]},{"text":[{"text":"Data and strategy:","bold":true},{"text":" marketing's analytics help HR read talent markets; HR gives insight into skills and engagement. Marketing drives revenue; HR drives workforce development."}]}]},{"type":"paragraph","text":[{"text":"Key areas of collaboration (5):","bold":true},{"text":" employer branding; recruitment and onboarding; training and development; internal and external communication (one cohesive story); sustainability initiatives."}]},{"type":"paragraph","text":[{"text":"Benefits of coordination (5):","bold":true},{"text":" stronger brand identity; improved talent acquisition; enhanced employee engagement; greater innovation; increased efficiency."}]},{"type":"paragraph","text":[{"text":"Strategies for effective coordination (4):","bold":true}]},{"type":"list","ordered":true,"start":1,"items":[{"text":[{"text":"Shared goals and metrics","bold":true},{"text":" (aligned KPIs)"}]},{"text":[{"text":"Regular meetings and workshops","bold":true}]},{"text":[{"text":"Integrated technology","bold":true},{"text":" (shared platforms for data and communication)"}]},{"text":[{"text":"Cross-functional teams","bold":true},{"text":" for key initiatives, e.g. a new product launch"}]}]}],"explainMore":[{"type":"list","ordered":false,"items":[{"text":[{"text":"Coordination "},{"text":"breaks down silos","bold":true},{"text":". Keeping each department's data on separate, unconnected systems is the opposite of integrated technology."}]},{"text":[{"text":"A ba$study_guide$);
insert into private.study_guide_chunks (guide, ordinal, chunk) values ('study_guide_bua201', 34, $study_guide$nk whose branches with highly engaged staff also have the most loyal customers shows "},{"text":"employee retention supports customer retention","bold":true},{"text":"."}]},{"text":[{"text":"Putting marketing and HR staff into one team to plan a launch = "},{"text":"cross-functional team","bold":true},{"text":"."}]},{"text":[{"text":"Wider view: marketing, HR, finance and production all depend on one another. Marketing's sales forecast tells production what to make, finance what money is needed, and HR how many staff to hire and train."}]}]}]}],"recap":[{"type":"list","ordered":false,"items":[{"text":[{"text":"Market = actual or potential buyers; consumer (own use) vs industrial (further production)."}]},{"text":[{"text":"Marketing starts with needs, wants and demands and continues after sale."}]},{"text":[{"text":"6 marketing functions: pricing, distribution, promotion, after-sale service, training and motivating salespersons, planning and controlling."}]},{"text":[{"text":"STP in order: segmentation (demographic, geographic, psychographic, behavioural), targeting (size, growth, profitability, competition), positioning (image relative to competitors)."}]},{"text":[{"text":"4Ps: product, price, place, promotion (advertising, PR, sales promotion). People is not one."}]},{"text":[{"text":"Rural: value, durability, bulk, kiosks and open markets; urban: income, trends, digital, brand switching."}]},{"text":[{"text":"HRM: 6 functions (recruitment, training, compensation, appraisal, legal compliance, advising); 5 areas of importance."}]},{"text":[{"text":"Marketing sells the brand externally; HR builds it internally. Coordinate through shared KPIs, meetings, integrated technology, cross-functional teams."}]},{"text":[{"text":"Formulas: market share = firm sales ÷ market sales × 100; segment reach = population × % × %; turnover = leavers ÷ average staff × 100."}]}]}],"theory":{"itemId":"b8c505fd-5e35-5453-be7a-afd4fc72d850","question":[{"type":"paragraph","text":[{"text":"A beverage firm estimates 3,000,000 adults in Kano. Research shows 30% prefer low-sugar drinks, and the firm aims to reach 20% of that segment in year one. Total low-sugar drink sales in Kano are ₦2,000,000,000, and the firm expects sales of ₦450,000,000. (a) How many customers will it reach? (b) What market share does it expect? (c) Which segmentation basis is \"prefer low-sugar drinks\"?"}]}]},"practice":[{"topic":"Functional Areas I: Marketing and Human Resources","named":false}]}},{"kind":"note","itemId":"3f3ac8e5-55f0-5caa-86bd-8de520be1474","sourceKey":"guide-topic:9","position":9,"payload":{"title":"Functional Areas II: Accounting, Finance and Production","body":"What accounting is, its users and concepts; the accounting equation; the three financial statements and the main ratios; the finance function, its three decisions and sources of finance; budgets, cash budgets and break-even; production systems, quality, productivity and the supply chain; operations challenges in Nigeria; how marketing, finance, HR and operations work together.","noteType":"guide_topic","number":9,"mustKnow":[{"text":"What accounting is, its users and concepts; the accounting equation; the three financial statements and the main ratios; the finance function, its three decisions and sources of finance; budgets, cash budgets and break-even; production systems, quality, productivity and the supply chain; operations challenges in Nigeria; how marketing, finance, HR and operations work together."}],"lessons":[{"number":"9.1","title":"Accounting, its users, concepts and the accounting equation","mustKnow":[{"type":"list","ordered":false,"items":[{"text":[{"text":"Accounting:","bold":true},{"text":" the process of "},{"text":"identifying, measuring, recording and communicating financial information","bold":true},{"text":" to users for decision-making."}]},{"text":[{"text":"Main purpose:","bold":true},{"text":" to provide financial information that helps users make "},{"text":"economic decisions","bold":true},{"text":". It does not replace planning, set every price or guarantee profit."}]},{"text":[{"text":"Internal users:","bold":true},{"text":" managers, directors, employees. "},{"text":"External users:","bold":true},{"text":" shareholders and potential investors, lenders (banks), suppliers, customers, government and tax authorities (e.g. the Nigeria Revenue Service, formerly FIRS), regulators, the public."}]}]},{"type":"table","header":[[{"text":"Point"}],[{"text":"Financial accounting"}],[{"text":"Management accounting"}]],"rows":[[[{"text":"Main users"}],[{"text":"External (shareholders, lenders, tax authority)"}],[{"text":"Internal (managers)"}]],[[{"text":"Time focus"}],[{"text":"Mainly past transactions"}],[{"text":"Past and future (forecasts, budgets)"}]],[[{"text":"Format"}],[{"text":"Fixed, published format set by law and standards"}],[{"text":"Flexible, as managers need"}]],[[{"text":"Detail"}],[{"text":"Summary for the whole business"}],[{"text":"Detailed, by product or department"}]]]},{"type":"paragraph","text":[{"text":"Accounting concepts","bold":true}]},{"type":"list","ordered":true,"start":1,"items":[{"text":[{"text":"Business entity:","bold":true},{"text":" the business is separate from its owner; the owner's private spending is not a business expense."}]},{"text":[{"text":"Going concern:","bold":true},{"text":" the business will continue to operate for the foreseeable future."}]},{"text":[{"text":"Accruals (matching):","bold":true},{"text":" income and expenses are recorded when earned or incurred, not when cash is received or paid; expenses are matched to the revenue they helped earn."}]},{"text":[{"text":"Historical cost:","bold":true},{"text":" assets are recorded at what they originally cost."}]},{"text":[{"text":"Consistency:","bold":true},{"text":" the same methods are used year after year."}]},{"text":[{"text":"Prudence:","bold":true},{"text":" do not overstate assets or profit; provide for likely losses."}]},{"text":[{"text"$study_guide$);
insert into private.study_guide_chunks (guide, ordinal, chunk) values ('study_guide_bua201', 35, $study_guide$:"Money measurement:","bold":true},{"text":" only items that can be measured in money are recorded."}]},{"text":[{"text":"Duality (double entry):","bold":true},{"text":" every transaction has two equal effects."}]}]},{"type":"paragraph","text":[{"text":"Accounting equation:","bold":true},{"text":" Assets = Liabilities + Owners' equity. Rearranged: Owners' equity = Assets - Liabilities; Liabilities = Assets - Owners' equity."}]}],"explainMore":[{"type":"list","ordered":false,"items":[{"text":[{"text":"Entity in action:","bold":true},{"text":" Mrs Ade pays her children's school fees from her shop's cash. It is recorded as "},{"text":"drawings","bold":true},{"text":" (the owner taking value out), not a shop expense: the business entity concept."}]},{"text":[{"text":"Accruals in action:","bold":true},{"text":" a printer finishes a ₦400,000 job in December; the customer pays in January. The ₦400,000 is December income. Recording it in January would be the "},{"text":"cash","bold":true},{"text":" basis, which is not the accruals concept."}]},{"text":[{"text":"When FIRS (now the Nigeria Revenue Service) studies published accounts to assess tax, it is an "},{"text":"external","bold":true},{"text":" user, not the preparer or a shareholder."}]},{"text":[{"text":"Trap: going concern is about continuing; \"assets at current market value\" is not going concern, and \"business separate from owner\" is entity."}]},{"text":[{"text":"Worked example 1 (equity):","bold":true},{"text":" assets ₦8,000,000, liabilities ₦2,500,000. Owners' equity = 8,000,000 - 2,500,000 = "},{"text":"₦5,500,000","bold":true},{"text":"."}]},{"text":[{"text":"Worked example 2 (assets):","bold":true},{"text":" liabilities ₦3,000,000, owners' equity ₦4,500,000. Assets = 3,000,000 + 4,500,000 = "},{"text":"₦7,500,000","bold":true},{"text":"."}]},{"text":[{"text":"Common wrong options add when you should subtract (₦8,000,000 + ₦2,500,000) or just repeat one figure."}]}]}]},{"number":"9.2","title":"Financial statements and ratios","mustKnow":[{"type":"list","ordered":true,"start":1,"items":[{"text":[{"text":"Statement of financial position (balance sheet):","bold":true},{"text":" assets, liabilities and owners' equity "},{"text":"at a particular date","bold":true},{"text":"."}]},{"text":[{"text":"Income statement (statement of profit or loss):","bold":true},{"text":" revenue and expenses "},{"text":"over a period","bold":true},{"text":" and the resulting profit or loss."}]},{"text":[{"text":"Statement of cash flows:","bold":true},{"text":" the "},{"text":"movement of cash into and out of","bold":true},{"text":" a business over a period, under three headings:"}],"blocks":[{"type":"list","ordered":false,"items":[{"text":[{"text":"Operating:","bold":true},{"text":" cash from trading (receipts from customers, payments to suppliers and staff)."}]},{"text":[{"text":"Investing:","bold":true},{"text":" buying or selling long-term assets (machines, land, vehicles)."}]},{"text":[{"text":"Financing:","bold":true},{"text":" raising or repaying long-term funds (loans, share issues, dividends paid)."}]}]}]}]},{"type":"list","ordered":false,"items":[{"text":[{"text":"Current assets","bold":true},{"text":" (turn into cash within a year): inventory, trade receivables, cash at bank, cash in hand. "},{"text":"Non-current assets:","bold":true},{"text":" land and buildings, machinery, vehicles."}]},{"text":[{"text":"Current liabilities","bold":true},{"text":" (due within a year): bank overdraft, trade payables, tax due. "},{"text":"Non-current liabilities:","bold":true},{"text":" long-term loans, debentures (e.g. a ten-year debenture). Share capital is "},{"text":"equity","bold":true},{"text":", not a liability."}]}]},{"type":"paragraph","text":[{"text":"Formulas","bold":true}]},{"type":"list","ordered":false,"items":[{"text":[{"text":"Gross profit = Revenue - Cost of sales"}]},{"text":[{"text":"Net profit (before tax) = Gross profit - Operating expenses"}]},{"text":[{"text":"Gross profit margin = Gross profit / Revenue x 100"}]},{"text":[{"text":"Net profit margin = Net profit / Revenue x 100"}]},{"text":[{"text":"Working capital = Current assets - Current liabilities"}]},{"text":[{"text":"Current ratio = Current assets / Current liabilities"}]},{"text":[{"text":"Debt-equity ratio = Total debt / Owners' equity"}]},{"text":[{"text":"Straight-line depreciation per year = (Cost - Residual value) / Useful life in years"}]}]},{"type":"table","header":[[{"text":"Ratio group"}],[{"text":"Measures"}],[{"text":"Examples"}]],"rows":[[[{"text":"Liquidity"}],[{"text":"Ability to meet "},{"text":"short-term","bold":true},{"text":" obligations"}],[{"text":"Current ratio, working capital"}]],[[{"text":"Profitability"}],[{"text":"Ability to earn profit from sales"}],[{"text":"Gross and net profit margin"}]],[[{"text":"Gearing (leverage)"}],[{"text":"Reliance on debt; financial risk"}],[{"text":"Debt-equity ratio"}]]]}],"explainMore":[{"type":"list","ordered":false,"items":[{"text":[{"text":"A ₦15,000,000 bottling machine paid for is "},{"text":"investing","bold":true},{"text":"; a ₦20,000,000 five-year bank loan received is "},{"text":"financing","bold":true},{"text":"."}]},{"text":[{"text":"Worked example 3 (profits and margins):","bold":true},{"text":" revenue ₦10,000,000, cost of sales ₦6,000,000, operating expenses ₦2,500,000."}],"blocks":[{"type":"list","ordered":false,"items":[{"text":[{"text":"Gross profit = 10,000,000 - 6,000,000 = ₦4,000,000."}]},{"text":[{"text":"Net profit = 4,000,000 - 2,500,000 = ₦1,500,000."}]},{"text":[{"text":"Gross profit margin = 4,000,000 / 10,000,000 x 100 = 40%. Net profit margin = 1,500,000 / 10,000,000 x 100 = 15%."}]}]}]},{"text":[{"text":"Trap: margin divides by "},{"text":"revenue","bold":true},{"text":", not by cost of sales. Dividing ₦5,000,000 gross profit by ₦7,000,000 cost would wrongly give 71.43%; by revenue of ₦12,000,000 it is 41.67% (rounded to 2 decimal places)."}]},{"text":[{"text":"A "},{"text":"high gross profit $study_guide$);
insert into private.study_guide_chunks (guide, ordinal, chunk) values ('study_guide_bua201', 36, $study_guide$margin","bold":true},{"text":" means sales revenue is high relative to cost of goods sold. Net profit margin measures "},{"text":"profitability","bold":true},{"text":"."}]},{"text":[{"text":"Worked example 4 (liquidity):","bold":true},{"text":" current assets ₦6,000,000, current liabilities ₦2,400,000. Working capital = 6,000,000 - 2,400,000 = ₦3,600,000. Current ratio = 6,000,000 / 2,400,000 = "},{"text":"2.5 : 1","bold":true},{"text":". Dividing the wrong way round (2.4 / 6) gives 0.4 : 1, a favourite wrong option."}]},{"text":[{"text":"A "},{"text":"very high current ratio","bold":true},{"text":" may show strong liquidity "},{"text":"or idle assets","bold":true},{"text":" (too much cash or stock not being used productively)."}]},{"text":[{"text":"Worked example 5 (gearing):","bold":true},{"text":" debt ₦3,000,000, equity ₦6,000,000. Debt-equity = 3,000,000 / 6,000,000 = 0.5. A "},{"text":"high","bold":true},{"text":" debt-equity ratio means "},{"text":"high financial leverage","bold":true},{"text":" and higher risk, not strong liquidity or low risk."}]},{"text":[{"text":"Worked example 6 (depreciation):","bold":true},{"text":" a machine costs ₦3,000,000, lasts 4 years, residual value ₦600,000. Annual charge = (3,000,000 - 600,000) / 4 = "},{"text":"₦600,000","bold":true},{"text":". Forgetting to subtract residual value gives ₦750,000, a typical wrong option."}]}]}]},{"number":"9.3","title":"The finance function and sources of finance","mustKnow":[{"type":"list","ordered":false,"items":[{"text":[{"text":"Finance function:","bold":true},{"text":" obtaining funds and allocating them efficiently to achieve the firm's objectives."}]},{"text":[{"text":"Financial planning:","bold":true},{"text":" forecasting "},{"text":"cash flows","bold":true},{"text":" and funding needs for the future."}]}]},{"type":"paragraph","text":[{"text":"Three finance decisions","bold":true}]},{"type":"list","ordered":true,"start":1,"items":[{"text":[{"text":"Investment (capital budgeting) decision:","bold":true},{"text":" what long-term assets to spend on, e.g. an ₦8,000,000 oven expected to raise output for ten years."}]},{"text":[{"text":"Financing decision:","bold":true},{"text":" how to raise funds, e.g. issuing new shares or taking a bank loan; the mix of debt and equity is the "},{"text":"capital structure","bold":true},{"text":"."}]},{"text":[{"text":"Dividend decision:","bold":true},{"text":" how much profit to pay shareholders and how much to keep (retained earnings) for expansion."}]}]},{"type":"paragraph","text":[{"text":"Sources of finance by time","bold":true}]},{"type":"table","header":[[{"text":"Term"}],[{"text":"Usual period"}],[{"text":"Examples"}]],"rows":[[[{"text":"Short"}],[{"text":"Up to 1 year"}],[{"text":"Trade credit from suppliers, bank overdraft, short-term loans, factoring, accrued expenses"}]],[[{"text":"Medium"}],[{"text":"1 to 5 years"}],[{"text":"Medium-term bank loans, hire purchase, leasing"}]],[[{"text":"Long"}],[{"text":"Over 5 years"}],[{"text":"Ordinary shares, preference shares, debentures, long-term loans, retained earnings, venture capital"}]]]},{"type":"list","ordered":false,"items":[{"text":[{"text":"Internal sources:","bold":true},{"text":" retained earnings (ploughed-back profit), sale of unused assets, better control of working capital. "},{"text":"External:","bold":true},{"text":" bank loans, new shares, debentures, trade credit, venture capital, government grants."}]},{"text":[{"text":"Equity","bold":true},{"text":" = ownership money (shares, retained earnings). "},{"text":"Debt","bold":true},{"text":" = borrowed money (loans, debentures, overdraft)."}]}]},{"type":"table","header":[[{"text":"Ordinary shareholders"}],[{"text":"Debenture holders"}]],"rows":[[[{"text":"Owners"}],[{"text":"Lenders"}]],[[{"text":"May receive "},{"text":"dividends","bold":true},{"text":" (only if declared)"}],[{"text":"Receive fixed "},{"text":"interest","bold":true},{"text":" whether or not profit is made"}]],[[{"text":"Vote at general meetings"}],[{"text":"No vote; often secured on assets"}]],[[{"text":"Paid last on winding up"}],[{"text":"Paid before shareholders"}]]]},{"type":"list","ordered":false,"items":[{"text":[{"text":"Simple interest = Principal x Rate x Time.","bold":true}]}]}],"explainMore":[{"type":"list","ordered":false,"items":[{"text":[{"text":"Venture capital","bold":true},{"text":" suits "},{"text":"start-ups with high growth potential","bold":true},{"text":"; investors take equity and accept high risk for high reward. Mature firms with stable cash flows can use cheaper sources."}]},{"text":[{"text":"A "},{"text":"rights issue","bold":true},{"text":" offers new shares to existing shareholders in proportion to their holdings; it increases "},{"text":"share capital","bold":true},{"text":" (equity), not debt or leverage."}]},{"text":[{"text":"Dividend policy","bold":true},{"text":" directly affects "},{"text":"retained earnings","bold":true},{"text":": the more paid out, the less kept for growth."}]},{"text":[{"text":"Financial leverage:","bold":true},{"text":" using more debt mainly increases "},{"text":"financial risk","bold":true},{"text":", because interest must be paid even in bad years."}]},{"text":[{"text":"Capital rationing:","bold":true},{"text":" when funds are limited, managers must "},{"text":"prioritise the projects with the highest returns","bold":true},{"text":", not accept every project."}]},{"text":[{"text":"Diversification of risk","bold":true},{"text":" reduces the "},{"text":"variability of overall returns","bold":true},{"text":". A diversified firm spreads its activities across a "},{"text":"portfolio of businesses","bold":true},{"text":", so a loss in one is cushioned by others. "},{"text":"Conglomerate diversification","bold":true},{"text":" means moving into unrelated businesses (Dangote Group spans cement, sugar, salt, fertiliser and petroleum refining). Concentrating on one market, retrenchment or downsizing does not spread risk."}]},{"text":[{"text$study_guide$);
insert into private.study_guide_chunks (guide, ordinal, chunk) values ('study_guide_bua201', 37, $study_guide$":"Worked example 7 (simple interest):","bold":true},{"text":" ₦1,500,000 borrowed from a microfinance bank at 20% a year for 3 years. Interest = 1,500,000 x 0.20 x 3 = "},{"text":"₦900,000","bold":true},{"text":". Total repayable = 1,500,000 + 900,000 = ₦2,400,000. Do not confuse interest with total repayment."}]}]}]},{"number":"9.4","title":"Budgeting, cash flow and break-even","mustKnow":[{"type":"list","ordered":false,"items":[{"text":[{"text":"Budget:","bold":true},{"text":" a financial plan, expressed in figures, for a future period. It is a tool for "},{"text":"planning and control","bold":true},{"text":"."}]},{"text":[{"text":"Budgetary control:","bold":true},{"text":" compare actual results with the budget. "},{"text":"Variance = Actual - Budget","bold":true},{"text":"; it is "},{"text":"favourable","bold":true},{"text":" if it raises profit (higher revenue or lower cost) and "},{"text":"adverse","bold":true},{"text":" if it lowers profit."}]},{"text":[{"text":"Variance analysis","bold":true},{"text":" supports "},{"text":"corrective action","bold":true},{"text":" when actual results differ from planned results."}]},{"text":[{"text":"Cash budget (cash flow forecast):","bold":true},{"text":" expected receipts and payments month by month. It helps a business "},{"text":"avoid cash shortages that could lead to insolvency","bold":true},{"text":" and plan borrowing in advance."}]},{"text":[{"text":"Closing cash = Opening cash + Receipts - Payments.","bold":true}]},{"text":[{"text":"Profit is not cash:","bold":true},{"text":" a business can show a profit and still run out of cash because "},{"text":"profit is recorded when sales are made, but customers may not have paid yet","bold":true},{"text":" (also cash tied up in stock, loan repayments, asset purchases)."}]},{"text":[{"text":"Cost-volume-profit (CVP) analysis","bold":true},{"text":" finds the "},{"text":"break-even point","bold":true},{"text":": the output where total revenue equals total cost (no profit, no loss)."}],"blocks":[{"type":"list","ordered":false,"items":[{"text":[{"text":"Contribution per unit = Selling price - Variable cost per unit"}]},{"text":[{"text":"Break-even units = Fixed costs / Contribution per unit"}]},{"text":[{"text":"Break-even revenue = Break-even units x Selling price"}]}]}]}]}],"explainMore":[{"type":"list","ordered":false,"items":[{"text":[{"text":"Small businesses often keep a simple cash book and monthly cash forecast; large organisations prepare a master budget built from sales, production, labour, overhead, capital expenditure and cash budgets."}]},{"text":[{"text":"Worked example 8 (cash budget):","bold":true},{"text":" opening cash ₦500,000, receipts ₦1,800,000, payments ₦2,100,000. Closing = 500,000 + 1,800,000 - 2,100,000 = "},{"text":"₦200,000","bold":true},{"text":". If instead opening cash were ₦200,000, receipts ₦900,000 and payments ₦1,300,000, closing = "},{"text":"-₦200,000","bold":true},{"text":": the forecast warns the owner to arrange an overdraft early."}]},{"text":[{"text":"Worked example 9 (variance):","bold":true},{"text":" budgeted transport cost ₦500,000, actual ₦560,000. Variance = 560,000 - 500,000 = ₦60,000 "},{"text":"adverse","bold":true},{"text":" (12% over budget), so the manager investigates and corrects."}]},{"text":[{"text":"Worked example 10 (break-even):","bold":true},{"text":" fixed costs ₦2,400,000 a month; price ₦2,000; variable cost ₦1,200."}],"blocks":[{"type":"list","ordered":false,"items":[{"text":[{"text":"Contribution = 2,000 - 1,200 = ₦800 per unit."}]},{"text":[{"text":"Break-even = 2,400,000 / 800 = "},{"text":"3,000 units","bold":true},{"text":"; break-even revenue = 3,000 x 2,000 = ₦6,000,000."}]},{"text":[{"text":"At 4,000 units, profit = (4,000 - 3,000) x 800 = ₦800,000."}]}]}]},{"text":[{"text":"Trap: dividing fixed costs by the selling price (2,400,000 / 2,000 = 1,200) is wrong; always use contribution."}]}]}]},{"number":"9.5","title":"Production, quality, productivity and the supply chain","mustKnow":[{"type":"list","ordered":false,"items":[{"text":[{"text":"Production:","bold":true},{"text":" the process of transforming inputs into goods and services. "},{"text":"Operations management","bold":true},{"text":" plans and controls that process."}]},{"text":[{"text":"Input-transformation-output model:","bold":true},{"text":" "},{"text":"inputs","bold":true},{"text":" (labour, raw materials, machines, capital, energy, information) → "},{"text":"transformation","bold":true},{"text":" (manufacturing, assembling, serving) → "},{"text":"outputs","bold":true},{"text":" (finished goods and services, customer satisfaction), with "},{"text":"feedback","bold":true},{"text":" for control."}]}]},{"type":"paragraph","text":[{"text":"Production systems","bold":true}]},{"type":"list","ordered":true,"start":1,"items":[{"text":[{"text":"Job (unit) production:","bold":true},{"text":" one item made to a customer's exact order, e.g. a Surulere tailor's single wedding gown."}]},{"text":[{"text":"Batch production:","bold":true},{"text":" a set quantity of one product, then the line switches to another, e.g. 500 wheat loaves, then 300 coconut loaves, then 400 meat pies."}]},{"text":[{"text":"Mass (flow) production:","bold":true},{"text":" identical products in very large volumes along an assembly line, e.g. a soft drinks bottling line."}]},{"text":[{"text":"Continuous process production:","bold":true},{"text":" non-stop processing, often 24 hours, e.g. cement, refining, flour milling."}]},{"text":[{"text":"Project production:","bold":true},{"text":" a large one-off undertaking, e.g. a bridge or a refinery."}]}]},{"type":"list","ordered":false,"items":[{"text":[{"text":"Efficiency:","bold":true},{"text":" achieving output with "},{"text":"minimum use of resources","bold":true},{"text":". "},{"text":"Effectiveness:","bold":true},{"text":" achieving the "},{"text":"intended goals","bold":true},{"text":"."}]},{"text":[{"text":"Productivity = Output / Input.","bold":true},{"t$study_guide$);
insert into private.study_guide_chunks (guide, ordinal, chunk) values ('study_guide_bua201', 38, $study_guide$ext":" Labour productivity = Output / Labour hours."}]},{"text":[{"text":"Percentage change = (New - Old) / Old x 100.","bold":true}]},{"text":[{"text":"Capacity utilisation = Actual output / Maximum possible output x 100.","bold":true}]},{"text":[{"text":"Quality control (QC):","bold":true},{"text":" inspecting output to "},{"text":"detect","bold":true},{"text":" defects. "},{"text":"Quality assurance (QA):","bold":true},{"text":" building quality into the process to "},{"text":"prevent","bold":true},{"text":" defects."}]},{"text":[{"text":"TQM:","bold":true},{"text":" organisation-wide commitment to quality and customer satisfaction through "},{"text":"continuous improvement","bold":true},{"text":". "},{"text":"Kaizen","bold":true},{"text":" (Japanese): continuous, small, step-by-step improvement."}]},{"text":[{"text":"Benchmarking:","bold":true},{"text":" comparing with leading firms to identify and adopt "},{"text":"best practices","bold":true},{"text":"."}]},{"text":[{"text":"Supply chain:","bold":true},{"text":" the network of organisations and activities that moves a product from raw material suppliers to the final customer (suppliers → manufacturer → distributors → retailers → customers)."}]},{"text":[{"text":"Just-in-time (JIT):","bold":true},{"text":" minimise inventory by receiving inputs only when they are needed for production."}]}]}],"explainMore":[{"type":"list","ordered":false,"items":[{"text":[{"text":"Worked example 11 (labour productivity):","bold":true},{"text":" 4,800 units from 600 labour hours = 4,800 / 600 = "},{"text":"8 units per labour hour","bold":true},{"text":". Dividing hours by units (600 / 4,800 = 0.125) is the reverse and wrong."}]},{"text":[{"text":"Worked example 12 (productivity change):","bold":true},{"text":" last month 5,000 units / 500 hours = 10 per hour; this month 6,600 units / 600 hours = 11 per hour. Change = (11 - 10) / 10 x 100 = "},{"text":"10% increase","bold":true},{"text":". Note output rose 32%, but productivity rose only 10% because hours also rose; always compare output "},{"text":"per hour","bold":true},{"text":"."}]},{"text":[{"text":"Worked example 13 (capacity):","bold":true},{"text":" a plant able to make 40,000 tonnes produced 32,000. Utilisation = 32,000 / 40,000 x 100 = "},{"text":"80%","bold":true},{"text":"."}]},{"text":[{"text":"To "},{"text":"raise","bold":true},{"text":" productivity: reduce waste and machine downtime, improve layout, train workers, use better technology. "},{"text":"Increasing inputs while output stays the same lowers productivity.","bold":true}]},{"text":[{"text":"Economies of scale:","bold":true},{"text":" as output grows, "},{"text":"unit cost","bold":true},{"text":" falls (bulk buying, specialised machines, cheaper finance)."}]},{"text":[{"text":"TQM stresses continuous improvement, not inspection only at the end or downsizing; its pioneers include "},{"text":"Deming","bold":true},{"text":" and "},{"text":"Juran","bold":true},{"text":"."}]},{"text":[{"text":"JIT's weakness:","bold":true},{"text":" it is especially vulnerable to "},{"text":"supply chain disruptions","bold":true},{"text":", since there is little buffer stock. In Nigeria, port delays, bad roads and forex shortages make pure JIT risky."}]},{"text":[{"text":"Vertical integration","bold":true},{"text":" (control of more stages of the supply chain):"}],"blocks":[{"type":"list","ordered":false,"items":[{"text":[{"text":"Backward:","bold":true},{"text":" a manufacturer takes over or sets up its "},{"text":"suppliers","bold":true},{"text":", producing its own raw materials (Dangote Cement owns limestone quarries; Nigerian brewers source local sorghum through farmer outgrower schemes)."}]},{"text":[{"text":"Forward:","bold":true},{"text":" a manufacturer acquires or sets up its own "},{"text":"distributors or retail outlets","bold":true},{"text":"."}]},{"text":[{"text":"Horizontal integration","bold":true},{"text":" is buying a competitor at the same stage; "},{"text":"market penetration","bold":true},{"text":" is selling more of current products in current markets."}]}]}]},{"text":[{"text":"Outsourcing","bold":true},{"text":" improves efficiency when the firm's "},{"text":"core competence is protected","bold":true},{"text":" (keep what you do best, outsource the rest), not when everything is handed out."}]},{"text":[{"text":"Operations strategy","bold":true},{"text":" must align with "},{"text":"corporate strategy","bold":true},{"text":": a low-cost firm needs efficient mass production; a premium firm needs quality and flexibility."}]}]}]},{"number":"9.6","title":"Operations challenges in Nigeria and how the functions work together","mustKnow":[{"type":"paragraph","text":[{"text":"Operations challenges in Nigeria","bold":true}]},{"type":"list","ordered":true,"start":1,"items":[{"text":[{"text":"Erratic power supply and heavy reliance on diesel generators."}]},{"text":[{"text":"Bad roads and congested seaports (longer delivery time, higher transport and maintenance costs)."}]},{"text":[{"text":"Foreign exchange shortages and naira depreciation raising the cost of imported inputs and machinery."}]},{"text":[{"text":"Insecurity disrupting supply of raw materials and movement of goods."}]},{"text":[{"text":"Inadequate skilled labour and weak maintenance culture."}]},{"text":[{"text":"High cost of finance and multiple taxation."}]},{"text":[{"text":"Counterfeiting and inconsistent government policy."}]}]},{"type":"paragraph","text":[{"text":"How the functions work together","bold":true}]},{"type":"list","ordered":false,"items":[{"text":[{"text":"Marketing","bold":true},{"text":" forecasts demand and sets the price and promotion."}]},{"text":[{"text":"Operations","bold":true},{"text":" plans capacity, materials and output to meet that forecast."}]},{"text":[{"text":"Finance","bold":true},{"text":" budgets and raises the money for capacity, stock and staff."}]},{"text":[{"text":"HR","bold":true},{"text":" recruits and trains the people needed."}]},{$study_guide$);
insert into private.study_guide_chunks (guide, ordinal, chunk) values ('study_guide_bua201', 39, $study_guide$"text":[{"text":"Accounting","bold":true},{"text":" records results and reports variances for control."}]}]}],"explainMore":[{"type":"list","ordered":false,"items":[{"text":[{"text":"A Kano manufacturer whose deliveries to Lagos take far longer than planned because of poor roads faces an "},{"text":"infrastructure-related operations challenge","bold":true},{"text":", not a segmentation, dividend or going concern problem."}]},{"text":[{"text":"Good integration:","bold":true},{"text":" marketing forecasts 30% higher demand; "},{"text":"operations plans extra capacity, finance budgets for it, and HR plans the extra staff.","bold":true},{"text":" Cutting the budget, freezing recruitment or waiting for \"proof\" are poor coordination."}]},{"text":[{"text":"Poor integration:","bold":true},{"text":" if marketing "},{"text":"overestimates","bold":true},{"text":" demand and production follows, operations ends up with "},{"text":"excess inventory","bold":true},{"text":" (money tied up, storage cost, possible write-off). Underestimating causes shortages and lost sales."}]},{"text":[{"text":"Shared forecasts, regular cross-functional meetings, integrated software and joint KPIs keep the functions aligned."}]}]}]}],"recap":[{"type":"list","ordered":false,"items":[{"text":[{"text":"Accounting identifies, measures, records and communicates financial information for decisions; users are internal or external."}]},{"text":[{"text":"Concepts: entity, going concern, accruals, historical cost, consistency, prudence, money measurement, duality."}]},{"text":[{"text":"Assets = Liabilities + Owners' equity."}]},{"text":[{"text":"Three statements: financial position (a date), income statement (a period), cash flows (operating, investing, financing)."}]},{"text":[{"text":"Margins divide by revenue; working capital = CA - CL; current ratio = CA / CL; high debt-equity = high leverage and risk."}]},{"text":[{"text":"Finance decisions: investment, financing, dividend. Sources: short, medium, long; internal or external; equity or debt."}]},{"text":[{"text":"Budget = plan in figures for planning and control; closing cash = opening + receipts - payments; break-even = fixed costs / contribution."}]},{"text":[{"text":"Production systems: job, batch, mass, continuous process, project. Productivity = output / input."}]},{"text":[{"text":"QC detects, QA prevents; TQM and kaizen = continuous improvement; JIT is vulnerable to supply disruption."}]},{"text":[{"text":"Marketing, operations, finance and HR must plan together."}]}]}],"theory":{"itemId":"d211cce5-9f77-51bd-a727-6b0874eb06e8","question":[{"type":"paragraph","text":[{"text":"A pure-water producer in Ibadan has fixed costs of ₦3,600,000 a month. Each bag sells for ₦500 and has a variable cost of ₦300. (a) How many bags must it sell each month to break even? (b) What profit does it make if it sells 25,000 bags?"}]}]},"practice":[{"topic":"Functional Areas II: Accounting, Finance and Production","named":false}]}},{"kind":"note","itemId":"10570774-1acf-5f4b-a018-e56734d1706c","sourceKey":"guide-topic:10","position":10,"payload":{"title":"Contemporary Management Issues in Nigeria","body":"How insecurity, infrastructure deficits, inflation and foreign exchange constraints affect businesses; leadership failures and governance weaknesses; innovation, digitisation and global competition; how Nigerian managers respond, with real company cases.","noteType":"guide_topic","number":10,"mustKnow":[{"text":"How insecurity, infrastructure deficits, inflation and foreign exchange constraints affect businesses; leadership failures and governance weaknesses; innovation, digitisation and global competition; how Nigerian managers respond, with real company cases."}],"lessons":[{"number":"10.1","title":"Insecurity and infrastructure deficits","mustKnow":[{"type":"list","ordered":false,"items":[{"text":[{"text":"Insecurity:","bold":true},{"text":" threats to lives and property (banditry, kidnapping, terrorism, farmer-herder clashes, militancy, armed robbery, pipeline vandalism) that make normal business activity risky."}]}]},{"type":"paragraph","text":[{"text":"Effects of insecurity on business","bold":true}]},{"type":"list","ordered":true,"start":1,"items":[{"text":[{"text":"Higher operating costs:","bold":true},{"text":" private security guards, escorted convoys, higher insurance premiums."}]},{"text":[{"text":"Disrupted supply of raw inputs:","bold":true},{"text":" farmers abandon farms, so agro-processors cannot get enough maize, sorghum or cassava."}]},{"text":[{"text":"Restricted movement","bold":true},{"text":" of staff and goods."}]},{"text":[{"text":"Smaller reachable markets","bold":true},{"text":" in affected areas."}]},{"text":[{"text":"Difficulty attracting staff","bold":true},{"text":" to postings in affected areas."}]},{"text":[{"text":"Reduced foreign direct investment (FDI):","bold":true},{"text":" foreign investors are "},{"text":"discouraged because of higher risk","bold":true},{"text":"."}]},{"text":[{"text":"Loss of assets, lives and investor confidence."}]}]},{"type":"list","ordered":false,"items":[{"text":[{"text":"Infrastructure deficit:","bold":true},{"text":" inadequate or poor-quality public facilities: electricity, roads, rail, seaports, water, broadband."}]}]},{"type":"paragraph","text":[{"text":"Effects of infrastructure deficits","bold":true}]},{"type":"list","ordered":true,"start":1,"items":[{"text":[{"text":"Erratic power:","bold":true},{"text":" heavy spending on diesel and generators, which "},{"text":"raises production costs and reduces competitiveness","bold":true},{"text":"."}]},{"text":[{"text":"Bad roads:","bold":true},{"text":" "},{"text":"longer distribution time and higher transport and vehicle-maintenance costs","bold":true},{"text":"; rural customers harder to reach."}]},{"text":[{"text":"Congested seaports:","bold":true},{"text":" goods stuck for weeks, demurrage and extra charges."}]},{"text":[{"text":"Overall, infrastructure deficiencies "},{"t$study_guide$);
insert into private.study_guide_chunks (guide, ordinal, chunk) values ('study_guide_bua201', 40, $study_guide$ext":"increase logistics and operating costs","bold":true},{"text":"."}]}]},{"type":"paragraph","text":[{"text":"Common responses:","bold":true},{"text":" alternative power (generators, "},{"text":"solar systems","bold":true},{"text":", gas-fired captive plants), own logistics fleets, regional warehouses, security partnerships, insurance, and locating plants close to raw materials or markets."}]}],"explainMore":[{"type":"list","ordered":false,"items":[{"text":[{"text":"High diesel bills caused by unreliable public power are an "},{"text":"external infrastructure challenge","bold":true},{"text":", not an ethical lapse, a governance issue or internal inefficiency: the cause lies outside the firm."}]},{"text":[{"text":"An importer whose containers sit for weeks at a congested port and pays extra charges faces an "},{"text":"infrastructure and logistics constraint","bold":true},{"text":", not a marketing, recruitment or dividend problem."}]},{"text":[{"text":"Trap: insecurity never makes movement "},{"text":"easier","bold":true},{"text":". \"Easier movement of staff and goods across all regions\" is the option that is "},{"text":"not","bold":true},{"text":" an effect."}]},{"text":[{"text":"Telecoms operators such as MTN Nigeria and Airtel Nigeria power many base stations with diesel and suffer fibre cuts and vandalism; costs end up in tariffs and reduce profit."}]},{"text":[{"text":"Under the "},{"text":"Petroleum Industry Act (PIA) 2021","bold":true},{"text":", oil companies must fund "},{"text":"Host Communities Development Trusts","bold":true},{"text":" (3% of their actual annual operating expenditure), partly to reduce conflict and vandalism in producing areas."}]}]}]},{"number":"10.2","title":"Inflation, foreign exchange and the cost of finance","mustKnow":[{"type":"list","ordered":false,"items":[{"text":[{"text":"Inflation:","bold":true},{"text":" a "},{"text":"sustained rise in the general price level","bold":true},{"text":" over time. Not a one-time rise in one product's price; a fall in the general price level is "},{"text":"deflation","bold":true},{"text":"."}]},{"text":[{"text":"Measured in Nigeria by the "},{"text":"Consumer Price Index (CPI)","bold":true},{"text":" published by the "},{"text":"National Bureau of Statistics (NBS)","bold":true},{"text":"."}]},{"text":[{"text":"Inflation rate = (CPI this period - CPI last period) / CPI last period x 100.","bold":true}]},{"text":[{"text":"Types:","bold":true},{"text":" "},{"text":"demand-pull","bold":true},{"text":" (too much money chasing too few goods) and "},{"text":"cost-push","bold":true},{"text":" (rising input costs such as fuel, power, imports and wages)."}]}]},{"type":"paragraph","text":[{"text":"Effects of high inflation on business","bold":true}]},{"type":"list","ordered":true,"start":1,"items":[{"text":[{"text":"Reduces consumers' purchasing power","bold":true},{"text":" and "},{"text":"raises input costs","bold":true},{"text":"."}]},{"text":[{"text":"Erodes the real value of fixed incomes","bold":true},{"text":" and savings, so workers demand pay rises."}]},{"text":[{"text":"Makes "},{"text":"forecasting costs and prices","bold":true},{"text":", budgeting and long-term planning difficult (frequent price-list and menu changes)."}]},{"text":[{"text":"Pushes up interest rates as the central bank tightens money supply."}]}]},{"type":"list","ordered":false,"items":[{"text":[{"text":"Exchange rate:","bold":true},{"text":" the price of one currency in terms of another, e.g. naira per US dollar. "},{"text":"Depreciation","bold":true},{"text":" of the naira means "},{"text":"more naira are needed for each dollar","bold":true},{"text":"."}]},{"text":[{"text":"Naira cost of an import = Dollar price x Exchange rate.","bold":true}]}]},{"type":"paragraph","text":[{"text":"Effects of naira depreciation and forex scarcity","bold":true}]},{"type":"list","ordered":true,"start":1,"items":[{"text":[{"text":"Raises the naira cost of imported inputs","bold":true},{"text":", so firms "},{"text":"dependent on imported raw materials","bold":true},{"text":" suffer most."}]},{"text":[{"text":"Exporters paid in dollars receive more naira for each dollar earned.","bold":true}]},{"text":[{"text":"Forex scarcity","bold":true},{"text":" makes it hard for multinationals to obtain dollars to "},{"text":"pay foreign suppliers or send profits (dividends) to parent companies","bold":true},{"text":"."}]},{"text":[{"text":"Firms with dollar loans see the naira value of their debt rise."}]}]},{"type":"list","ordered":false,"items":[{"text":[{"text":"High lending interest rates","bold":true},{"text":" make bank loans "},{"text":"expensive","bold":true},{"text":" and "},{"text":"limit SMEs' ability to expand","bold":true},{"text":"."}]}]}],"explainMore":[{"type":"list","ordered":false,"items":[{"text":[{"text":"Worked example 1 (inflation rate):","bold":true},{"text":" CPI rises from 200 to 250. Inflation = (250 - 200) / 200 x 100 = "},{"text":"25%","bold":true},{"text":"."}]},{"text":[{"text":"Worked example 2 (real income):","bold":true},{"text":" a worker earns ₦100,000 a month and prices rise 25%. Real value = 100,000 / 1.25 = "},{"text":"₦80,000","bold":true},{"text":" in old prices. To keep the same standard of living the salary must rise to 100,000 x 1.25 = ₦125,000. This is why textile workers demand a pay rise after rapid price increases."}]},{"text":[{"text":"Worked example 3 (depreciation and an importer):","bold":true},{"text":" a firm imports 20,000 US dollars of raw materials. At ₦800 per dollar they cost 20,000 x 800 = ₦16,000,000. If the naira falls to ₦1,500 per dollar, they cost 20,000 x 1,500 = ₦30,000,000, an increase of (1,500 - 800) / 800 x 100 = "},{"text":"87.5%","bold":true},{"text":"."}]},{"text":[{"text":"Worked example 4 (exporter):","bold":true},{"text":" a cashew exporter earns 10,000 US dollars. At ₦800 per dollar it receives ₦8,000,000; at ₦1,500 per dollar it receives ₦15,000,000. Depreciation helps exporters, other things being$study_guide$);
insert into private.study_guide_chunks (guide, ordinal, chunk) values ('study_guide_bua201', 41, $study_guide$ equal."}]},{"text":[{"text":"Recent context:","bold":true},{"text":" petrol subsidy removal (announced 29 May 2023) and the Central Bank of Nigeria's unification of exchange-rate windows (June 2023) sent the naira from under ₦500 per dollar to well above ₦1,000 per dollar and pushed inflation sharply up. The CBN raised its Monetary Policy Rate repeatedly in 2023 and 2024, making loans dearer."}]},{"text":[{"text":"Several multinationals cited forex difficulties when scaling down: "},{"text":"GSK Consumer Nigeria","bold":true},{"text":" (2023) announced it would stop operating in Nigeria and use third-party distributors, and "},{"text":"Procter & Gamble","bold":true},{"text":" (December 2023) moved from local manufacturing to an import model."}]},{"text":[{"text":"Import substitution","bold":true},{"text":" (producing locally what you used to import) mainly reduces "},{"text":"exposure to foreign exchange risk","bold":true},{"text":". "},{"text":"Backward integration","bold":true},{"text":" into local raw materials does the same: a brewery that sets up its own farms to grow grains it once imported is integrating "},{"text":"backward","bold":true},{"text":", not forward."}]}]}]},{"number":"10.3","title":"Leadership failures and governance weaknesses","mustKnow":[{"type":"list","ordered":false,"items":[{"text":[{"text":"Corruption:","bold":true},{"text":" the "},{"text":"abuse of entrusted power for private gain","bold":true},{"text":" (Transparency International's definition)."}]},{"text":[{"text":"Effects:","bold":true},{"text":" "},{"text":"raises the cost of doing business and creates unfair competition","bold":true},{"text":"; contracts go to the connected, not the efficient; public trust falls; investors stay away."}]},{"text":[{"text":"Ethical response to a bribe request:","bold":true},{"text":" "},{"text":"refuse, document the request and report it through the proper channels.","bold":true},{"text":" Paying from personal funds or hiding it as \"miscellaneous\" is still bribery."}]},{"text":[{"text":"Nigeria's main anti-corruption bodies: the "},{"text":"Independent Corrupt Practices and Other Related Offences Commission (ICPC)","bold":true},{"text":" and the "},{"text":"Economic and Financial Crimes Commission (EFCC)","bold":true},{"text":"."}]}]},{"type":"paragraph","text":[{"text":"Governance weaknesses that hurt business","bold":true}]},{"type":"list","ordered":true,"start":1,"items":[{"text":[{"text":"Weak corporate governance and insider abuse:","bold":true},{"text":" boards that fail to check the chief executive; insider loans."}]},{"text":[{"text":"Poor succession planning:","bold":true},{"text":" no one prepared to take over when the founder or leader leaves."}]},{"text":[{"text":"Policy inconsistency:","bold":true},{"text":" sudden import bans or tariff changes "},{"text":"increase uncertainty and make long-term planning difficult","bold":true},{"text":"."}]},{"text":[{"text":"Multiple taxation:","bold":true},{"text":" several overlapping levies and taxes from different levels of government on the same activity."}]},{"text":[{"text":"Slow and uncertain contract enforcement:","bold":true},{"text":" court cases take years, so firms avoid giving credit."}]},{"text":[{"text":"Large informal sector:","bold":true},{"text":" many unregistered businesses make "},{"text":"reliable data and regulation harder","bold":true},{"text":" and narrow the tax base."}]},{"text":[{"text":"Weak regulation and enforcement","bold":true},{"text":" generally (e.g. against counterfeiting and pollution)."}]}]}],"explainMore":[{"type":"list","ordered":false,"items":[{"text":[{"text":"Bank case:","bold":true},{"text":" in August 2009 the CBN removed the chief executives of five banks (including Oceanic Bank and Intercontinental Bank) over huge non-performing and insider loans. Oceanic's former chief executive, Cecilia Ibru, later pleaded guilty and forfeited assets. The lesson: when a board fails to check a chief executive who grants unsecured loans to firms he secretly controls, the cause of failure is "},{"text":"weak corporate governance and insider abuse","bold":true},{"text":"."}]},{"text":[{"text":"In June 2024 the CBN revoked "},{"text":"Heritage Bank's","bold":true},{"text":" licence, saying its financial condition had kept deteriorating and its board and management had failed to improve its performance: a reminder that weak oversight can destroy even established firms."}]},{"text":[{"text":"Succession:","bold":true},{"text":" many Nigerian family businesses collapse after the founder's death because heirs were not prepared and ownership quarrels follow. Good practice: groom successors early, separate ownership from management, and appoint professional managers and independent directors."}]},{"text":[{"text":"Multiple taxation","bold":true},{"text":" is not a tax incentive or a tax holiday (those reduce tax to attract investment). The 2025 tax reform laws, in force from January 2026, aim partly to harmonise taxes and reduce this burden."}]},{"text":[{"text":"Contract enforcement:","bold":true},{"text":" a supplier that refuses credit to new customers because debt recovery through the courts takes years is reacting to slow and uncertain enforcement of contracts."}]},{"text":[{"text":"Host communities:","bold":true},{"text":" when a pipeline leak damages farmland and fishing waters, the best long-term response is to "},{"text":"clean up, compensate fairly and engage the community through social responsibility programmes","bold":true},{"text":", not to deny the damage or pay only community leaders privately."}]}]}]},{"number":"10.4","title":"Innovation, digitisation and global competition","mustKnow":[{"type":"list","ordered":false,"items":[{"text":[{"text":"Innovation:","bold":true},{"text":" turning new ideas into new or better products, processes or business models. An "},{"text":"innovation strategy","bold":true},{"text":" supports "},{"text":"competitive advantage","bold":true},{"text":"."}]}$study_guide$);
insert into private.study_guide_chunks (guide, ordinal, chunk) values ('study_guide_bua201', 42, $study_guide$,{"text":[{"text":"Digitisation:","bold":true},{"text":" using digital technology (mobile apps, cloud, online platforms, data analytics) to run business activities."}]},{"text":[{"text":"Managers rely on innovation and digitisation to "},{"text":"improve efficiency, reach new customers and stay competitive","bold":true},{"text":"."}]}]},{"type":"paragraph","text":[{"text":"Benefits of digital payments and mobile banking for small businesses:","bold":true},{"text":" faster, easier transactions; access to customers without relying only on cash; records of sales; access to credit based on transaction history. They do "},{"text":"not","bold":true},{"text":" guarantee protection from all fraud or remove the need for records."}]},{"type":"paragraph","text":[{"text":"Challenges of digitisation","bold":true}]},{"type":"list","ordered":true,"start":1,"items":[{"text":[{"text":"Cybersecurity risk:","bold":true},{"text":" phishing, hacking, data breaches."}]},{"text":[{"text":"Shortage of staff with the needed digital skills.","bold":true}]},{"text":[{"text":"Cost of technology and unreliable power and internet."}]},{"text":[{"text":"Data protection compliance ("},{"text":"Nigeria Data Protection Act 2023","bold":true},{"text":")."}]}]},{"type":"list","ordered":false,"items":[{"text":[{"text":"Globalisation:","bold":true},{"text":" the "},{"text":"increasing integration of national economies through trade, investment, technology and information flows","bold":true},{"text":"."}],"blocks":[{"type":"list","ordered":false,"items":[{"text":[{"text":"Challenge:","bold":true},{"text":" "},{"text":"stronger competition from imported goods and foreign firms","bold":true},{"text":"; pressure to meet international standards."}]},{"text":[{"text":"Opportunity:","bold":true},{"text":" "},{"text":"access to wider international markets and foreign investment","bold":true},{"text":", technology and partnerships."}]}]}]},{"text":[{"text":"Brain drain:","bold":true},{"text":" skilled professionals emigrating for better pay and conditions (popularly \"japa\")."}]},{"text":[{"text":"HR response to brain drain:","bold":true},{"text":" improve "},{"text":"retention through better pay, training and career development","bold":true},{"text":", plus succession and replacement planning."}]},{"text":[{"text":"Counterfeiting:","bold":true},{"text":" fake copies bearing a firm's brand name, causing lost sales and "},{"text":"unfair competition","bold":true},{"text":"."}]}]}],"explainMore":[{"type":"list","ordered":false,"items":[{"text":[{"text":"An employee who clicks a fake email link and lets hackers into the customer database illustrates "},{"text":"cybersecurity risk","bold":true},{"text":", not an infrastructure, tax or forex problem. Defences: staff training, strong passwords and multi-factor authentication, backups."}]},{"text":[{"text":"Nigerian fintechs such as "},{"text":"Paystack","bold":true},{"text":" (acquired by Stripe in 2020), "},{"text":"Flutterwave","bold":true},{"text":", "},{"text":"Moniepoint","bold":true},{"text":" and "},{"text":"OPay","bold":true},{"text":" have spread point-of-sale terminals, transfers and mobile wallets to traders across the country."}]},{"text":[{"text":"Under the "},{"text":"African Continental Free Trade Area (AfCFTA)","bold":true},{"text":", which Nigeria signed in July 2019 and under which trading began in January 2021, Nigerian firms gain a wider African market but also face more competition."}]},{"text":[{"text":"A Lagos hospital that cannot fill specialist posts because doctors have moved abroad is experiencing "},{"text":"brain drain","bold":true},{"text":". Cutting training or salaries makes it worse."}]},{"text":[{"text":"Counterfeiting","bold":true},{"text":" is fought with regulators such as "},{"text":"NAFDAC","bold":true},{"text":" (food, drugs, cosmetics) and the "},{"text":"Standards Organisation of Nigeria (SON)","bold":true},{"text":", plus anti-fake packaging and consumer education."}]}]}]},{"number":"10.5","title":"Managing in Nigeria: responses and company cases","mustKnow":[{"type":"paragraph","text":[{"text":"Contemporary challenges facing managers in Nigeria (summary):","bold":true},{"text":" insecurity; infrastructure deficits; inflation; foreign exchange constraints; high interest rates; corruption and weak governance; policy inconsistency; multiple taxation; brain drain; counterfeiting; cybersecurity threats; global competition. "},{"text":"Uninterrupted, cheap public power is not one of them.","bold":true}]},{"type":"paragraph","text":[{"text":"Managerial responses","bold":true}]},{"type":"list","ordered":true,"start":1,"items":[{"text":[{"text":"Scenario planning:","bold":true},{"text":" preparing responses to "},{"text":"several possible future situations","bold":true},{"text":" (it does not predict the future exactly or replace budgets)."}]},{"text":[{"text":"Backward integration and local sourcing","bold":true},{"text":" to cut forex exposure."}]},{"text":[{"text":"Import substitution.","bold":true}]},{"text":[{"text":"Alternative power","bold":true},{"text":" (generators, solar, gas)."}]},{"text":[{"text":"Innovation and digitisation.","bold":true}]},{"text":[{"text":"Cost control, hedging and pricing reviews","bold":true},{"text":" under inflation."}]},{"text":[{"text":"Strong governance, ethics and succession planning.","bold":true}]},{"text":[{"text":"Talent retention","bold":true},{"text":" strategies."}]},{"text":[{"text":"Corporate social responsibility","bold":true},{"text":" and community engagement."}]}]},{"type":"paragraph","text":[{"text":"Correct challenge-effect pairs","bold":true}]},{"type":"table","header":[[{"text":"Challenge"}],[{"text":"Most direct business effect"}]],"rows":[[[{"text":"Inflation"}],[{"text":"Lower consumer purchasing power; higher input costs"}]],[[{"text":"Naira depreciation"}],[{"text":"Higher naira cost of imported inputs"}]],[[{"text":"Insecurity"}],[{"text":"Higher security and insurance costs; disrupted suppl$study_guide$);
insert into private.study_guide_chunks (guide, ordinal, chunk) values ('study_guide_bua201', 43, $study_guide$ies"}]],[[{"text":"Poor roads"}],[{"text":"Slower deliveries; higher transport costs"}]],[[{"text":"Erratic power"}],[{"text":"Higher production costs (diesel)"}]],[[{"text":"Corruption"}],[{"text":"Higher cost of doing business; unfair competition"}]]]}],"explainMore":[{"type":"list","ordered":false,"items":[{"text":[{"text":"Dangote Group:","bold":true},{"text":" backward integration in cement using local limestone helped turn Nigeria from a cement importer into a self-sufficient producer; the "},{"text":"Dangote Petroleum Refinery","bold":true},{"text":" at Lekki (designed for 650,000 barrels a day) aims to reduce the country's reliance on imported fuel and the forex it consumes."}]},{"text":[{"text":"Nigerian Breweries and other brewers","bold":true},{"text":" replaced much imported barley with "},{"text":"locally sourced sorghum","bold":true},{"text":" through farmer outgrower schemes: import substitution that cuts forex risk."}]},{"text":[{"text":"GSK Consumer Nigeria and Procter & Gamble","bold":true},{"text":" (2023) show the opposite outcome: when forex scarcity, high costs and inflation make local manufacturing unviable, multinationals scale down or exit."}]},{"text":[{"text":"Moniepoint and OPay","bold":true},{"text":" show innovation turning infrastructure gaps (few bank branches, cash dependence) into business opportunities."}]},{"text":[{"text":"Oceanic and Intercontinental Banks","bold":true},{"text":" (2009) show the cost of weak boards and insider lending."}]},{"text":[{"text":"Exam pattern: when a question pairs a challenge with an effect, choose the pair that makes economic sense (depreciation raises import costs); reject pairs that reverse it (inflation raising purchasing power, insecurity lowering insurance, bad roads speeding deliveries)."}]}]}]}],"recap":[{"type":"list","ordered":false,"items":[{"text":[{"text":"Insecurity raises operating costs, disrupts raw inputs, restricts movement and discourages FDI."}]},{"text":[{"text":"Infrastructure deficits (power, roads, ports) raise logistics and operating costs and are external challenges."}]},{"text":[{"text":"Inflation = sustained rise in the general price level; it cuts purchasing power, raises costs and erodes fixed incomes."}]},{"text":[{"text":"Naira depreciation raises importers' costs and gives exporters more naira per dollar; forex scarcity blocks payments and profit repatriation."}]},{"text":[{"text":"Corruption = abuse of entrusted power for private gain; refuse, document and report bribe requests."}]},{"text":[{"text":"Governance weaknesses: insider abuse, poor succession, policy inconsistency, multiple taxation, slow contract enforcement, informality."}]},{"text":[{"text":"Digitisation brings speed and reach but also cybersecurity risk and skills gaps."}]},{"text":[{"text":"Globalisation = integration of economies; threat of imports, opportunity of wider markets."}]},{"text":[{"text":"Responses: scenario planning, backward integration, import substitution, alternative power, retention, CSR."}]}]}],"theory":{"itemId":"f7aad9b0-e0af-5252-b21a-da37bd999d42","question":[{"type":"paragraph","text":[{"text":"A Nigerian paint maker imports pigments worth 12,000 US dollars a month. The exchange rate moves from ₦900 per dollar to ₦1,350 per dollar. (a) What is the change in the naira cost of the pigments, and by what percentage does it rise? (b) Name two strategies the firm could use to reduce this exposure."}]}]},"practice":[{"topic":"Contemporary Management Issues in Nigeria","named":false}]}}],"theory":[{"kind":"theory_question","itemId":"9e27de07-deff-553b-8100-c1b8ba78e7e2","sourceKey":"guide-theory:1","position":1,"payload":{"prompt":"A Surulere bakery aims to sell 2,000 loaves a week at ₦700 each. In Week 1 it bakes 2,000 loaves at a total cost of ₦1,000,000 and sells all of them. In Week 2 it cuts total cost to ₦800,000 for 2,000 loaves but sells only 1,200. Find the cost per loaf and profit each week, and say which week was more efficient and which more effective."},"answer":{"kind":"model_answer","itemId":"a5103fc2-ab0a-5aa4-9a79-4a1d452cd222","sourceKey":"guide-answer:1","payload":{"body":"• Week 1: cost per loaf = ₦1,000,000 ÷ 2,000 = ₦500. Revenue = 2,000 × ₦700 = ₦1,400,000. Profit = ₦1,400,000 − ₦1,000,000 = ₦400,000.\n• Week 2: cost per loaf = ₦800,000 ÷ 2,000 = ₦400. Revenue = 1,200 × ₦700 = ₦840,000. Profit = ₦840,000 − ₦800,000 = ₦40,000.\n• Week 2 is more efficient (₦400 per loaf against ₦500: fewer resources per unit). Week 1 is more effective (it met the 2,000-loaf sales goal). Efficiency alone is not enough: Week 2's lower unit cost earned a tenth of Week 1's profit because it missed the goal."}}},{"kind":"theory_question","itemId":"3d0d15a4-f7ee-5b61-8879-55372b237866","sourceKey":"guide-theory:2","position":2,"payload":{"prompt":"An Abuja water factory sets a standard of 5,000 cartons a week. Actual output this week is 4,600 cartons. Find the shortfall and the percentage of the standard achieved, and name the control step at which each piece of work happens."},"answer":{"kind":"model_answer","itemId":"08224961-2bde-57cb-b9fc-2dc13f95eb44","sourceKey":"guide-answer:2","payload":{"body":"• Step 1, set standards: 5,000 cartons a week.\n• Step 2, measure actual performance: 4,600 cartons.\n• Step 3, compare: shortfall = 5,000 − 4,600 = 400 cartons. Percentage achieved = 4,600 ÷ 5,000 × 100 = 92% (an 8% shortfall).\n• Step 4, take corrective action: find the cause (for example machine downtime or power cuts) and fix it; if the standard is unrealistic, revise the plan, which shows control feeding back into planning."}}},{"kind":"theory_question","itemId":"52d4b3bc-6bf9-5c5e-8957-3ab0f40d146a","sourceKey":"guide-theory:3","position":3,"payload":{"prompt":"Under the 2024 recapitalisation, a commercial bank with ₦120 billion of qualifying capital wants to keep an international licence. How much new capital must it raise, and what would the shortfall be if it chose a national licence instead? Name t$study_guide$);
insert into private.study_guide_chunks (guide, ordinal, chunk) values ('study_guide_bua201', 44, $study_guide$wo ways it could close the gap."},"answer":{"kind":"model_answer","itemId":"a71c133a-36b0-57e1-808d-4cd3acbe2c88","sourceKey":"guide-answer:3","payload":{"body":"1. International licence: ₦500 billion − ₦120 billion = ₦380 billion to raise.\n2. National licence: ₦200 billion − ₦120 billion = ₦80 billion.\n3. Ways to close the gap: raise fresh equity (rights issue or public offer), or merge with or acquire another bank; alternatively, downgrade to a licence category whose threshold it can meet."}}},{"kind":"theory_question","itemId":"dbb16b8f-ee0a-547a-82f6-f07df9c6b3bf","sourceKey":"guide-theory:4","position":4,"payload":{"prompt":"Kemi and Dayo start a business with ₦5,000,000 of capital. It later owes ₦8,000,000 and its assets are worth ₦2,000,000. How much of the debt can creditors recover from the owners' personal assets if the business is (a) an ordinary partnership, (b) a private company limited by shares whose shares are fully paid?"},"answer":{"kind":"model_answer","itemId":"2f7d4199-d727-518f-87bb-38c5dfef2c78","sourceKey":"guide-answer:4","payload":{"body":"1. Shortfall = ₦8,000,000 − ₦2,000,000 = ₦6,000,000.\n2. (a) Ordinary partnership: liability is unlimited, joint and several, so creditors can recover the full ₦6,000,000 from the partners' personal assets, from either partner alone if necessary.\n3. (b) Private company with fully paid shares: the company is a separate legal person and members owe only unpaid amounts on their shares, which is ₦0. Creditors recover nothing from the owners personally; they bear the ₦6,000,000 loss."}}},{"kind":"theory_question","itemId":"f268cb36-00ba-5e5c-80f4-3b60654125fd","sourceKey":"guide-theory:5","position":5,"payload":{"prompt":"Two Abuja water factories each plan and produce 500 cartons of the same quality a day. Factory X spends ₦400,000 on inputs and Factory Y spends ₦500,000. Compare their effectiveness and efficiency."},"answer":{"kind":"model_answer","itemId":"a5dbdcf1-8e66-52f5-a188-688b88d070c7","sourceKey":"guide-answer:5","payload":{"body":"1. Effectiveness: both meet the 500-carton objective, so they are equally effective.\n2. Cost per carton: X = ₦400,000 ÷ 500 = ₦800; Y = ₦500,000 ÷ 500 = ₦1,000.\n3. X saves ₦500,000 − ₦400,000 = ₦100,000 a day, which is ₦100,000 ÷ ₦500,000 × 100 = 20% of Y's cost.\n4. Conclusion: X is equally effective but more efficient than Y."}}},{"kind":"theory_question","itemId":"808efc6d-172a-5b73-8f22-a8007c6aa9d7","sourceKey":"guide-theory:6","position":6,"payload":{"prompt":"A Lagos firm with 200 managers copies Jack Welch's vitality curve. How many managers fall in each group, and what happens to each?"},"answer":{"kind":"model_answer","itemId":"1ffb43b3-2d70-59c8-92d1-4e1bdd836769","sourceKey":"guide-answer:6","payload":{"body":"1. Top 20%: 200 × 0.20 = 40 managers, rewarded with bonuses and stock options.\n2. Middle 70%: 200 × 0.70 = 140 managers, kept and developed.\n3. Bottom 10%: 200 × 0.10 = 20 managers, dismissed.\n4. Check: 40 + 140 + 20 = 200."}}},{"kind":"theory_question","itemId":"ca335f0b-75bc-5113-ad99-cd32a9ce2b7d","sourceKey":"guide-theory:7","position":7,"payload":{"prompt":"A Lagos bakery uses 400 bags of imported-wheat flour a month. Because the naira weakened, the price per bag rose from ₦60,000 to ₦78,000. (a) Compute the percentage rise in the price per bag and the extra monthly cost. (b) Classify the cause under PESTLE and SWOT, and state whether it is micro or macro."},"answer":{"kind":"model_answer","itemId":"910e50ba-1cad-5259-954b-5e72249ec6af","sourceKey":"guide-answer:7","payload":{"body":"(a) Rise per bag = ₦78,000 − ₦60,000 = ₦18,000. Percentage rise = 18,000 ÷ 60,000 × 100 = 30%.\nOld monthly cost = 400 × ₦60,000 = ₦24,000,000. New monthly cost = 400 × ₦78,000 = ₦31,200,000. Extra monthly cost = ₦31,200,000 − ₦24,000,000 = ₦7,200,000 (check: 400 × ₦18,000 = ₦7,200,000).\n(b) Naira depreciation is an economic factor in the macro (general) environment. In SWOT it is a threat, because it is external and harmful. The bakery cannot control it but can adapt, e.g. by blending in local cassava flour, adjusting prices or buying ahead."}}},{"kind":"theory_question","itemId":"b8c505fd-5e35-5453-be7a-afd4fc72d850","sourceKey":"guide-theory:8","position":8,"payload":{"prompt":"A beverage firm estimates 3,000,000 adults in Kano. Research shows 30% prefer low-sugar drinks, and the firm aims to reach 20% of that segment in year one. Total low-sugar drink sales in Kano are ₦2,000,000,000, and the firm expects sales of ₦450,000,000. (a) How many customers will it reach? (b) What market share does it expect? (c) Which segmentation basis is \"prefer low-sugar drinks\"?"},"answer":{"kind":"model_answer","itemId":"0bd3d7c5-a8f2-58ec-9be2-1dd5836793ef","sourceKey":"guide-answer:8","payload":{"body":"(a) Segment = 3,000,000 × 0.30 = 900,000. Customers = 900,000 × 0.20 = 180,000.\n(b) Market share = 450,000,000 ÷ 2,000,000,000 × 100 = 22.5%.\n(c) Preference for low sugar is a benefit sought, so the basis is behavioural (if framed as a health-conscious lifestyle, psychographic)."}}},{"kind":"theory_question","itemId":"d211cce5-9f77-51bd-a727-6b0874eb06e8","sourceKey":"guide-theory:9","position":9,"payload":{"prompt":"A pure-water producer in Ibadan has fixed costs of ₦3,600,000 a month. Each bag sells for ₦500 and has a variable cost of ₦300. (a) How many bags must it sell each month to break even? (b) What profit does it make if it sells 25,000 bags?"},"answer":{"kind":"model_answer","itemId":"ceaf40e7-afa9-5a5c-8eaf-ec8c01bf9521","sourceKey":"guide-answer:9","payload":{"body":"1. Contribution per bag = 500 - 300 = ₦200.\n2. (a) Break-even = 3,600,000 / 200 = 18,000 bags (break-even revenue = 18,000 x 500 = ₦9,000,000).\n3. (b) Bags above break-even = 25,000 - 18,000 = 7,000. Profit = 7,000 x 200 = ₦1,400,000.\n4. Check: revenue 25,000 x 500 = ₦12,500,000; total cost = 3,600,000 + 25,000 x 300 = ₦11,100,000; profit = ₦1,400,000."}}},{"kind":"theory_question","itemId":"f7aad9b0-e0af-5252-b2$study_guide$);
insert into private.study_guide_chunks (guide, ordinal, chunk) values ('study_guide_bua201', 45, $study_guide$1a-da37bd999d42","sourceKey":"guide-theory:10","position":10,"payload":{"prompt":"A Nigerian paint maker imports pigments worth 12,000 US dollars a month. The exchange rate moves from ₦900 per dollar to ₦1,350 per dollar. (a) What is the change in the naira cost of the pigments, and by what percentage does it rise? (b) Name two strategies the firm could use to reduce this exposure."},"answer":{"kind":"model_answer","itemId":"0d2f6367-bbf5-51cd-96a4-452acae2101f","sourceKey":"guide-answer:10","payload":{"body":"1. Old cost = 12,000 x 900 = ₦10,800,000.\n2. New cost = 12,000 x 1,350 = ₦16,200,000.\n3. Increase = 16,200,000 - 10,800,000 = ₦5,400,000; percentage = 5,400,000 / 10,800,000 x 100 = 50%.\n4. (b) Backward integration or local sourcing of pigments (import substitution), and passing costs through careful price reviews or hedging; scenario planning helps prepare for further moves."}}}]}$study_guide$);
